window.__D("text/likkutei-sichot/c001",{"p":[[1301410141,"ויתירה מזו: מדברי רש\"י — \"והי' מתפלל ואומר יהי רצון שתהא זו כאלו היא עשוי' בבני\" — מוכח, שאברהם עשה דבר זה (הקרבת האיל \"תחת בנו\") לא מפני ציווי הקב\"ה (או שהבין שכן הוא חפצו של הקב\"ה), אלא שזה הי' רצונו (ו\"חידושו\") של אברהם, שלכן הוצרך להתפלל להקב\"ה שתתקבל הקרבה זו \"כאילו היא עשוי' בבני\".\nוהתמי' במקומה: הקב\"ה אמר לאברהם \"מוצא שפתי לא אשנה לא אמרתי לך שחטהו אלא העלהו\" — ואברהם רצה והשתדל להוסיף קרבן \"תחת בנו\"?!\nב. יש מפרשים שזה הי' \"תמורת<sup data-n=\"647\">11</sup> מה שהי' בלבו לשחוט את בנו, על דרך ודובר<sup data-n=\"648\">12</sup> אמת בלבבו\", כי מאחר ש\"הי' בדעתו לגמור הפעל. . חשב שהי' מחוייב לתת במקומו כופר ותמורת זה במקום זה\"<sup data-n=\"649\">13</sup>.\nכלומר: עם היות שציווי השם הי' רק \"העלהו\" ולא \"שחטהו\", מ\"מ, מאחר שאברהם גמר בלבו לשחוט את בנו, חל עליו חיוב לקיים מה שהי' בלבו (עכ\"פ — ע\"י תמורה) — משום \"ודובר אמת בלבבו\"<sup data-n=\"650\">14</sup>.\nאבל דוחק גדול לתרץ כן בפרש\"י — כי לא מצינו אף רמז לתירוץ זה בפרש\"י; ולאידך, אין התירוץ \"פשוט\" כ\"כ שנאמר שאין רש\"י צריך לכותבו בפירוש (כי התלמיד יעמוד על זה מעצמו) — שהרי יש מקום לומר להיפך, שבנידון זה לא שייך כלל זה ד\"דובר אמת בלבבו\", כי מאחר ש\"לא הי' חפץ הקב\"ה לשחטו\", שוב אין מקום לומר שאברהם ישתדל לקיים מחשבתו הקודמת (לו גם באופן ד\"כאילו\" בנו שחוט), דלא כחפצו של הקב\"ה.\nולכן, גם את\"ל שרש\"י ס\"ל שיש מקום לביאור זה, הו\"ל לכותבו בפירוש (וכמדובר כמ\"פ, שרש\"י כתב פירושו בשפה ברורה מבלי שיצטרך הלומד לחפש ביאור במפרשים כדי להבין כוונתו).\nג. ויובן זה בהקדים עוד תמי' בכתובים אלה — שלא מצינו שרש\"י מתרצה:\nבכתובים מסופר<sup data-n=\"651\">15</sup>, דכאשר שלח \"אברהם את ידו. . לשחוט את בנו\" קרא אליו מלאך ה' \"ויאמר אל תשלח ידך אל הנער גו' כי עתה ידעתי כי ירא אלקים אתה ולא חשכת את בנך את יחידך ממני\", ולאחרי שראה אברהם את האיל \"ויעלהו לעולה תחת בנו\", קרא אליו מלאך ה' \"שנית מן השמים, ויאמר בי נשבעתי נאום ה' כי יען אשר עשית את הדבר הזה ולא חשכת את בנך את יחידך, כי ברך אברכך והרבה ארבה את זרעך גו' והתברכו בזרעך גו'\".\nואינו מובן (כמו שהקשו במפרשים<sup data-n=\"652\">16</sup>):",[["647","11","ספורנו כאן."],["648","12","תהלים טו, ב."],["649","13","אברבנאל כאן."],["650","14","ראה ב\"ב פח, א וברבינו גרשום ורשב\"ם. פרש\"י מכות כד, א."],["651","15","כב, י ואילך."],["652","16","אברבנאל (שאלה הכ\"ב), צרור המור ועוד.\nולהעיר מרש\"י ריש פרשתנו (יח, ב) \"שאין מלאך אחד עושה שתי שליחות\". אבל נוסף לזה שכאן אי\"ז בגדר שליחות אחרת, הרי עיקר השאלה כאן היא — למה הי' ההפסק דהקרבת האיל כו' בין שתי האמירות."]]],[1301410142,"מדוע הוצרך המלאך לקרוא אליו \"שנית מן השמים\" למסור לו את כל הברכות המגיעות לו \"יען אשר עשית את הדבר הזה ולא חשכת את בנך את יחידך\", ולא אמר לו כל זה בקריאה הראשונה?\nומשמעות הכתובים היא, דאף שאברהם נתברך ברכות אלו \"יען אשר עשית את הדבר הזה ולא חשכת את בנך את יחידך\", מ\"מ, לא נתברך בהן בפועל עד אחר הקרבת האיל — וטעמא בעי.\nד. ויש לומר הביאור בזה:\nהחידוש שבברכות אלו, \"הרבה ארבה את זרעך ככוכבי השמים וכחול גו' וירש זרעך גו' והתברכו בזרעך גו'\"<sup data-n=\"653\">17</sup> — אף שכבר נתברך אברהם בתוכן דומה כמ\"פ לפנ\"ז (כמסופר בפ' לך<sup data-n=\"654\">18</sup>) — הוא (כמפורש בכתוב) שכאן נשבע הקב\"ה עליהן<sup data-n=\"655\">19</sup> — \"בי נשבעתי נאום ה' כי יען גו' כי ברך אברכך גו'\" (שע\"י השבועה הובטח ששום דבר לא יבטל ברכות אלו<sup data-n=\"656\">20</sup>).\nועפ\"ז אין לתמוה מדוע לא פירש רש\"י מהי הסיבה שבגללה באה השבועה דוקא בקריאה \"שנית\", לאחרי הקרבת האיל — כי זהו מובן מהמסופר בחומש בשבועת הקב\"ה בפעם הראשונה:\nבהכתובים לאחרי המבול נאמר<sup data-n=\"657\">21</sup> \"ויבן נח מזבח לה' גו' ויעל עולות גו' וירח ה' את ריח הניחוח ויאמר גו' לא אוסיף לקלל גו' ולא אוסיף עוד להכות גו'\", ופירש רש\"י \"לא אוסיף. ולא אוסיף, כפל הדבר לשבועה, הוא שכתוב<sup data-n=\"658\">22</sup> אשר נשבעתי מעבור מי נח ולא מצינו בה שבועה אלא זו\". הרי מפורש, דזה שנשבע הקב\"ה שלא יוסיף עוד להביא מבול, בא ע\"י ריח הניחוח מקרבנותיו של נח.\nוהוא הדבר בנדו\"ד: זה שהקב\"ה נשבע על הברכות הוא בא ע\"י קרבנו של אברהם (— בהקרבת האיל)<sup data-n=\"659\">23</sup>. ולכן באה שבועה זו רק בקריאה ה\"שנית\", לאחרי העלאת האיל.\nוזהו גם הטעם שרצה אברהם להקריב את האיל<sup data-n=\"660\">24</sup> \"תחת בנו\" — כי כדי שקרבנו יפעול שהברכות על נסיון העקידה (שהם ענינים עיקריים לקיומו של עם ישראל) יובטחו לו בשבועה, הי' צ\"ל שייכות וקשר בין הקרבן והנסיון. וע\"ד שמצינו בקרבנותיו של נח (שפעלו שבועת ה' \"לא אוסיף\"), דנוסף על זה שהקריבם תיכף לאחרי צאתו מן התיבה (בסמיכות ובהמשך להמבול), הנה הקרבנות עצמם היו מבהמות אלו שניצלו מן",[["653","17","כב, יז-יח."],["654","18","יב, ב-ג. יג, טז. טו, ה. יז, ו."],["655","19","וכ\"ה ברמב\"ן כאן (ובארברבנאל (שאלה הכ\"ג) הקשה עליו. ואכ\"מ). וראה רד\"ק כאן פסוק טזיז. ועוד."],["656","20","בלשון הרמב\"ן (ועד\"ז ברד\"ק) \"שלא יגרום שום חטא\" (וראה רש\"י וישלח לב, יא).\nואין רש\"י צריך לפרש זה — כי זהו פשטות תוכן ענין השבועה, ובלשון הכתוב שהובא ברש\"י כאן \"לא אחלל בריתי\". וכמפורש ג\"כ לעיל גבי נח ע\"ד שבועת השם ובריתו (נח ח, כא ובפרש\"י. שם ט, יא) שלא יביא עוד מבול לשחת הארץ, אף \"כשתעלה במחשבה לפני להביא חושך ואבדון לעולם\" (רש\"י שם ט, יד)."],["657","21","נח ח, ככא."],["658","22","ישעי' נד, ט."],["659","23","ראה מדרש תדשא פי\"ד: ע\"י הקרבן קבלו אברהם יצחק ויעקב ברכת עולם שנאמר בי נשבעתי נאום ה'. ובפרקי דר\"א (ספל\"א): עלה ריח ניחוח של איל לפני כסא הכבוד וערב לו כריח ניחוח של יצחק ונשבע לברכו כו'."],["660","24","וע\"פ הנ\"ל הערה 10 — חיפש אברהם בהמה כדי להקריבה \"תחת בנו\"."]]],[1301410143,"המבול<sup data-n=\"661\">25</sup> — כמו\"כ בעניננו, שכדי לקשר קרבן זה עם עקידת יצחק הקריב אברהם את האיל \"תחת בנו\".\nה. עפ\"ז מובנת ג\"כ האריכות בפרש\"י על הכתוב \"תחת בנו\" — \"על כל עבודה שעשה ממנו הי' מתפלל ואומר יהי רצון שתהא זו כאילו היא עשוי' בבני (והולך ומפרט כל העבודות —) כאלו בני שחוט. . דמו זרוק. . מופשט. . נקטר ונעשה דשן\" — כי זה מבליט ביותר את הקשר שבין הקרבת האיל למעשה העקידה, שע\"י הקרבת האיל \"תחת בנו\" פעל אברהם שיצחק עצמו יהי' בגדר של קרבן.\nכלומר: בכוונת הכתוב שהקרבת האיל היתה \"תחת בנו\" הי' אפשר לפרש, שהקרבת האיל היתה במקום הקרבת בנו, והיינו שע\"י הקרבת האיל הסתלק מ\"בנו\" גדר של קרבן, וחל על האיל<sup data-n=\"662\">26</sup>; ומחדש רש\"י, שהפירוש ב\"תחת בנו\" הוא להיפך, שע\"י הקרבת האיל ה\"ז \"כאילו היא עשוי' בבני\", ועי\"ז חל על יצחק גדר קרבן. ודבר זה — חלות גדר קרבן על יצחק ע\"י הקרבת האיל — הי' \"חידושו\" של אברהם, ולכן הוזקק להתפלל ע\"ז להקב\"ה — \"יהי רצון שתהא זו כאלו היא עשוי' בבני\".\nוהסברת הדבר: כוונתו של הקב\"ה במעשה העקידה היתה לכאורה רק לנסות את אברהם (כמפורש בקרא<sup data-n=\"663\">27</sup>), שיהי' מוכן בהחלט גמור להקריב את בנו יחידו לה', אבל לא שיצחק ייעשה<sup data-n=\"664\">28</sup> קרבן בפועל<sup data-n=\"665\">*28</sup> (כי, אדרבה, \"מוצא שפתי לא אשנה\", ולכן אמר \"העלהו\" ולא \"שחטהו\", כי \"לא הי' חפץ הקב\"ה לשחטו\");\nאבל אברהם, שרצה לפעול שבועת הקב\"ה (על ידי \"ריח ניחוח\" דקרבנות, כנ\"ל), השתדל שיחול על יצחק גדר קרבן<sup data-n=\"666\">29</sup>, כדי שבמעשה העקידה תהי' גם",[["661","25","ראה פרש\"י נח ז, ב. ח, כ."],["662","26","ראה אברבנאל שבהערה 13. ולהעיר מב\"ר פרשתנו פנ\"ו, ט."],["663","27","פרשתנו כב, א."],["664","28","ולהעיר ממשנ\"ת במק\"א (סה\"מ פר\"ת ע' קז. סה\"מ תיש\"א ע' 289. ובארוכה ד\"ה נתת תשל\"ו פ\"ה, פ\"ט (סה\"מ מלוקט ח\"א ע' קפחט. שם ע' קצג). וש\"נ) בגדר ענין הנסיון, שכמה מהם ענינם הוא רק — מנגד לעבודת האדם, הגברא, ואין בהנ\"ל \"חפצא\" [כמו נהר דעקידה (תנחומא פרשתנו כב) דכשירד אברהם לתוך הנהר נתבטלה מציאותו, כי כל מציאותו היתה רק כדי לנסותו כו']."],["665","*28","כי פשיטא דמ\"ש (כב, ב) \"והעלהו שם לעולה\" אין הכוונה שעל ידי העלי' לחוד חל על מי שהוא שם \"עולה\" [ואדרבה, ע\"ד הפשט (וההלכה) זה (שם עולה) נעשה בדוקא קודם הכניסה להעזרה, ועאכו\"כ קודם ההעלאה למזבח] — כ\"א (בלשון רש\"י שם) \"העלהו להר לעשותו עולה\", היינו שיהי' ג\"כ ענין דעשי'<sup data-n=\"e14\">*</sup> — ולכן שאל אברהם שיעשה בו חבלה וכו' (דאינו מובן לכאורה כלל שייכות חבלה. . לקרבן! — וראה לקמן סעיף ז)."],["666","29","ועפ\"ז יומתק (יתורץ?) איך יצחק \"נתקדש. . להיות עולה תמימה\" (רש\"י תולדות כה, כו. כו, ב) ע\"י עלי' לחוד למזבח?<sup data-n=\"e15\">*</sup> — וע\"פ הנ\"ל, נעשה זה ע\"י שחיטה כו' ושריפת האיל \"תחת בנו\", שהקב\"ה קיבל תפילתו שיהא נחשב \"כאילו היא עשוי' בבני\" (וראה רש\"י פרשתנו כב, יד (וכן בחוקותי כו, מב) \"אפרו של יצחק צבור כו'\"). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251131\" data-slug=\"likkutei-sichot\" data-id=\"1300251131\">לקו\"ש חכ\"ה ע' 131</a>."],["e14","*","אבל לא כל מעשהו של עולה, היינו שחיטה — כ\"א רק \"העלהו\"; אלא אברהם, שרצה שיחול על יצחק גדר קרבן בפועל, הקריב את האיל \"תחת בנו\" והתפלל שיהא נחשב \"כאילו היא עשוי' בבני\", כדלקמן בפנים. וראה לקמן הערה 29 ובשוה\"ג שם."],["e15","*","שהרי עכצ\"ל שהכוונה כאן לקדושה מעין קדושת העולה לאחרי הקרבתו ולא לקריאת שם בלבד, שזה נעשה לפני העלי' למזבח (ראה לעיל הערה *28).\n[ובמפרשי רש\"י תולדות כו, ב (מב\"ר פס\"ד, ג) שיצחק נתקדש להפסל ב\"יוצא\". אבל צע\"ג איך אפ\"ל (ע\"ד הפשט) — שחי נפסל. . ביוצא! — ומפורש בכה\"ג שרק ז' ימי המילואים \"לא יצא\", משא\"כ אפר דקרבן. וק\"ל. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151200\" data-slug=\"likkutei-sichot\" data-id=\"1300151200\">לקו\"ש חט\"ו ע' 200</a> ואילך (ובהערה 7 שם)]."]]],[1301410144,"המעלה של \"קרבן\" (ועי\"ז הברכות על מעשה העקידה יובטחו לו באופן של שבועה); ולכן הקריב את האיל \"תחת בנו\", והתפלל להקב\"ה \"יהי רצון שתהא זו כאילו היא עשוי' בבני\".\n[ובזה יומתק המשך הכתוב \"בי נשבעתי גו' יען אשר עשית את הדבר הזה ולא חשכת את בנך את יחידך\", שמשמעו, ש(גם) השבועה שאחרי הקרבת האיל היא \"יען\" (תוצאה מזה) ש\"עשית גו' ולא חשכת את בנך את יחידך\" — כי (גם) ע\"י הקרבת האיל הראה אברהם שלא חשך את בנו יחידו מהשם, מכיון שהתפלל אז ש\"תהא זו כאלו היא עשוי' בבני\"<sup data-n=\"667\">30</sup>].\nו. אבל עדיין חסר ביאור: הן אמת שמצינו גבי נח ששבועת ה' באה על ידי \"ריח הניחוח\" של קרבנות — מ\"מ, בנדו\"ד, איך יתכן לומר שנסיון העקידה עצמו, שבו גילה אברהם שמוכן להקריב את בנו יחידו לה', אין בו כדי לפעול שבועת ה', ורק הקרבת האיל \"תחת בנו\" היא היא הגורמת שבועת ה'<sup data-n=\"668\">31</sup>?\nויש לומר הביאור בזה:\nאף שבמעשה העקידה גילה אברהם שהי' מוכן ומזומן למסור בנו יחידו לה', מ\"מ, אין זה עדיין בגדר ודאי של קרבן, כי לא בא לידי הקרבה בפועל. כי גם לאחרי ההחלטה בלב שלם, וכל ההכנות שעשה כדי להקריב את יצחק כקרבן, ש\"כבש את רחמיו\" כדי למוסרו לה' — עכ\"ז, מכיון שלא עשה לו \"מאומה\"<sup data-n=\"669\">32</sup> ולא באה הקרבה זו בפועל, הרי אין זה ודאי. וכמובן בפשטות, שאינה דומה כלל כבישת הרחמים בההכנות \"לשחוט את בנו\" לכבישת הרחמים הדרושה בעת העשי' בפו\"מ<sup data-n=\"670\">33</sup>.\n[וע\"ד מעלת האדם המוסר נפשו להשם בפועל ממש, לגבי זה שמסירת נפשו היא רק בכח<sup data-n=\"671\">34</sup> (אף שהחליט במחשבתו להיות מוכן (כשיבוא לידו) למסור נפשו לה'). כי כאשר האדם צריך למסור את עצמו בפועל, עליו לעורר בנפשו תקיפות וכחות ביתר שאת ויתר עז מהכחות שהוא מעורר להיות מוכן לזה במחשבה לחוד, וכמובן בפשטות].\nובמילא: בנוגע לנסיון העקידה הי' מספיק גם ה\"כבש את רחמיו\" שבההכנה של אברהם, כי בזה כבר \"ידעתי כי ירא אלקים אתה\"<sup data-n=\"640\">4</sup> וכו' — מ\"מ, עדיין אין בזה העילוי שבקרבן, הקרבה לה' (בפועל).\nז. וזהו ג\"כ הטעם דכאשר א\"ל המלאך לאברהם \"אל תשלח ידך אל הנער\" אמר אברהם \"אעשה בו חבלה ואוציא ממנו מעט דם\"<sup data-n=\"673\">35</sup> — דלכאורה, מהי",[["667","30","להעיר גם מכלי יקר כאן."],["668","31","כלומר: אף שבהקרבת האיל יש המעלה דקרבן (הפועל שבועת ה') — מ\"מ, בנוגע ליצחק (היינו חלות גדר קרבן על יצחק), במה עדיפא מחשבת וכוונת אברהם בהקרבת האיל \"תחת בנו\", לגבי מעשה העקידה עצמו?"],["669","32","פרשתנו כב, יב ובפרש\"י."],["670","33","להעיר מאברבנאל כאן (השאלה הב') \"איך יאמרו. . כדי. . שתצא לפועל, כי הוא לא שחט בפועל את יצחק בנו ומי יודע אם הי' מתחיל לשחוט בראותו טפת דם אם הי' מתחרט ויכמרו רחמיו ולא יצא דבר לפעל\"."],["671","34","ראה בארוכה שערי תשובה (לאדמו\"ר האמצעי) ח\"א ד\"ה אחרי ה\"א פל\"זח. ועוד."],["640","4","שם, יב."],["673","35","רש\"י שבהערה 32. — ע\"פ הערה 29 יתורץ הקס\"ד \"אעשה בו חבלה כו'\", אף שיצחק עולה תמימה."]]],[1301410145,"התועלת בהוצאת מעט דם, הרי גם בזה לא יקיים הציווי<sup data-n=\"639\">3</sup> ד\"העלהו. . לעולה\"? — אלא מפני שעי\"ז יורגש בו הענין דמסירה בפועל<sup data-n=\"675\">36</sup>.\nולכן, כאשר ענהו המלאך \"אל תעש לו מאומה\", \"אל תעש בו מום\"<sup data-n=\"669\">32</sup> — ורצה אברהם שבמעשה העקידה יהי' בו העילוי של קרבן — הקריב את האיל \"תחת בנו\", ובכל עבודה ועבודה שעשה בהאיל התפלל ואמר \"יהי רצון שתהא זו כאילו היא עשוי' בבני\":\nכאשר אברהם שחט את האיל, חשב והרגיש בנפשו שהוא שוחט את יצחק (ועד\"ז בשאר העבודות שעשה בהאיל), באופן שבהקרבת האיל הי' מעורר בעצמו המדה ד\"כובש את רחמיו\" בפועל, שהרי בעת מעשה השחיטה הי' מורגש במחשבתו<sup data-n=\"677\">37</sup> שהוא שוחט את יצחק.\nוע\"ז התפלל אברהם, שע\"י מחשבה והתעוררות זו יהי' נחשב \"כאילו היא עשוי' בבני\", העילוי שבהקרבה בפועל;\nוע\"ז בא מענה השם (על ידי המלאך) — \"בי נשבעתי נאום ה' כי יען אשר עשית את הדבר הזה גו' כי ברך אברכך והרבה ארבה את זרעך גו' וירש זרעך את שער אויביו\",\nשזה יקויים ובמילואו \"בגאולה העתידה לנו\"<sup data-n=\"678\">38</sup>, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת ש\"פ וירא תשל\"ז) </span>",[["639","3","כב, ב."],["675","36","ראה אברבנאל שבהערה 33: בראותו טפת דם כו'."],["669","32","פרשתנו כב, יב ובפרש\"י."],["677","37","עיין שע\"ת שם פרטי הדרגות שבמסנ\"פ בכח."],["678","38","רמב\"ן פרשתנו כב, טז בסופו. ולהעיר מפרקי דר\"א (ספל\"א) שקרן ימין של האיל \"עתיד לתקוע בו לעתיד לבא\". וראה המשך יונתי תר\"ם ע' מג."]]],[1301410146,"<h3>שיחה א</h3>\nא. איתא בפרקי דר' אליעזר<sup data-n=\"679\">1</sup>, שכאשר בא אברהם לקנות את מערת המכפלה מאת בני חת \"אמרו לו אנו יודעים שהקב\"ה עתיד ליתן לך ולזרעך את כל הארצות האל כרות עמנו שבועה<sup data-n=\"680\">2</sup> שאין בני ישראל יורשים את עיר יבוס כי אם ברצונם של בני יבוס (ש\"חתיים היו\"<sup data-n=\"681\">3</sup>) — וכרת עמהם ברית<sup data-n=\"682\">4</sup> — ואח\"כ קנה את מערת המכפלה\".\nוצריך ביאור:\nא) איך הסכים אברהם לכרות עמהם שבועה שלא ירשו בני ישראל את עיר היבוס — היפך הבטחת הקב\"ה אליו \"את כל הארץ גו' לך אתננה ולזרעך עד עולם\"<sup data-n=\"683\">5</sup>.\nב) הרי עשיריות בשנים לפני זה כרת ה' את אברם ברית לזרעך נתתי את הארץ הזאת<sup data-n=\"684\">6</sup>.\nוביותר יש לתמוה ע\"פ המפורש בהמשך דברי הפרקי דר\"א ד\"כשבאו ישראל לארץ. . לא היו יכולין ליכנס (בעיר היבוסי) מפני אות ברית שבועת אברהם. . וכשמלך דוד ורצה ליכנס. . לא הניחו אותו. . מכח ברית שבועת אברהם\". וכן הוא בספרי<sup data-n=\"685\">7</sup> דמש\"נ גבי יהושע<sup data-n=\"686\">8</sup> \"ואת היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם\", פירושו \"יכולים היו אבל אינן רשאים\" (וכמפורש ברש\"י<sup data-n=\"687\">9</sup> שהאיסור הוא \"לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה\"), הרי ששבועת אברהם הטילה איסור<sup data-n=\"688\">10</sup> על בנ\"י לכבוש את ירושלים<sup data-n=\"689\">11</sup>.\nב. להלן שם בפרקי דר\"א מסופר, דכאשר לא הניחו את דוד ליכנס בעיר ו\"אמרו לו אין אתה יכול ליכנס בעיר היבוסי עד שתסיר כל הגלולים הללו שכתוב עליהם אותו שבועת אברהם, אמר דוד לאנשיו כל מי שיעלה בראשונה ויסיר את הגלולים הללו שכתוב עליהם אות ברית שבועת אברהם יהי' לראש ועלה בראשונה יואב בן צרוי'",[["679","1","פל\"ו."],["680","2","כ\"ה בפדר\"א לפנינו \"כרות עמנו שבועה\"<sup data-n=\"e16\">*</sup>. וביל\"ש יהושע (רמז כח) \"כרות עמנו ברית\". וכ\"ה בערוך (ערך עור) ואברבנאל ש\"ב ה, ו. וביל\"ש וירא (רמז פב) \"כרות עמנו ברית ושבועה\". וראה המשך הלשון בפדר\"א \"וכתבו עליהם שבועת אברהם. . מפני אות ברית שבועת אברהם\". וביל\"ש וירא (וערוך) שם \"וכתבו עליהם ברית שבועת אברהם\". ועד\"ז ביל\"ש יהושע ובאברבנאל שם \"ברית השבועה\". ואכ\"מ."],["681","3","פדר\"א שם — לפנ\"ז."],["682","4","כן הגי' הרד\"ל בפדר\"א שם, על פי יל\"ש וירא ויהושע שם."],["683","5","לך יג, טו. ועוד. וראה לקמן סעיף ג."],["684","6","לך טו, יח."],["685","7","פ' ראה יב, יז."],["686","8","יהושע טו, סג."],["687","9","פ' ראה שם."],["688","10","והוא דלא כפרש\"י יהושע שם שלא היו רשאין מחמת השבועה שנשבע אברהם לאבימלך (ולהעיר מתוס' שאנץ לסוטה י, א) — דהרי בימי דוד כבר עברו הדורות שהוזכרו בהשבועה (רש\"י ש\"ב ה, ח (בסופו). וראה רד\"ק שם, ו (בסופו). פי' רבינו ישעי' שם, ט)."],["689","11","השקו\"ט בפרש\"י פ' ראה שם ע\"ד הפשט — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291080\" data-slug=\"likkutei-sichot\" data-id=\"1300291080\">לקו\"ש חכ\"ט ע' 80</a> ואילך."],["e16","*","וכ\"ה בפדר\"א שם להלן בברית שכרת יצחק עם עמי הארץ."]]],[1301410147,"כו'\" (וכמפורש בכתוב<sup data-n=\"690\">12</sup> שדוד לכד את העיר). ומסיים שם (בפדר\"א): \"ואח\"כ<sup data-n=\"691\">13</sup> קנה את עיר היבוסי לישראל בכתב עולם לאחוזת עולם\".\nואינו מובן (וכמו שהקשו במפרשים<sup data-n=\"692\">14</sup>):\nמתחילת הענין, שלא הניחו לדוד ליכנס לעיר \"מכח ברית שבועת אברהם\", מוכח שבימי דוד עדיין היתה השבועה קיימת;\nאבל מהמשך הסיפור, שנלחם יואב עם בני יבוס ולכד את העיר (כמפורש בכתוב), משמע ששבועת אברהם כבר בטלה.\n[ועוד זאת: אם שבועת אברהם לא בטלה — מהי התועלת בהסרת הגלולים עם השבועה הכתובה עליהם? וכי בכוחה של הסרה זו לבטל תוקפה של השבועה<sup data-n=\"693\">15</sup>?! ועכצ\"ל שכבר בטלה שבועת אברהם<sup data-n=\"694\">16</sup>, והי' מותר ללכוד העיר, והטעם שצוה להסיר הצלמים הוא (כמ\"ש במפרשים<sup data-n=\"695\">17</sup>) \"רק מפני שהי' זה כעין חלול ה' כ\"ז שהיו עומדים, כענין השבועה לגבעונים\"<sup data-n=\"696\">18</sup> (ז.א. היות שלפי דעתם של היבוסים עדיין השבועה קיימת היו צריכים לבטל זכר השבועה למנוע חילול השם)].\nואילו מסיום הענין, ש\"אח\"כ קנה את עיר היבוסי לישראל בכתב עולם לאחוזת עולם\", משמע שקנה את העיר כדי שרכישת העיר תהי' \"ברצונם של בני יבוס\"<sup data-n=\"697\">19</sup>!\nעוד צריך ביאור: ע\"י מה נשתנה, שבעת כיבוש יהושע \"לא יכלו גו' להורישם\", שלא היו רשאים להורישם מפני השבועה (אף שנצטוו \"והורשתם את כל יושבי הארץ וגו'\"<sup data-n=\"698\">20</sup>), ולדוד הי' מותר ללכוד העיר<sup data-n=\"699\">21</sup>?\nג. ויובן זה בהקדם הדו\"ד בין אברהם ובני חת שהובא ברז\"ל:\nעל הפסוק<sup data-n=\"700\">22</sup> \"גר ותושב אנכי עמכם\" אמרו רז\"ל<sup data-n=\"701\">23</sup>: \"אם תרצו הריני גר ואם",[["690","12","ש\"ב ה, ז."],["691","13","במשך זמן לאח\"ז — כמפורש בש\"ב בסופו."],["692","14","רד\"ל לפדר\"א שם (אות צו). וראה גם אברבנאל שבהערה 2."],["693","15","ואף שכן אמרו לדוד כמפורש בקרא (ש\"ב ה, ו) וכהובא בפדר\"א — צ\"ל שאמרו זה דרך משטה אני בך (וכיו\"ב). וראה מפרשים לש\"ב שם."],["694","16","בא' מתירוצי הרד\"ל שם, \"שבאמת השבועה לא בטלה ולכן לא הי' דוד יכול לירש ארצם. . עד שקנאו ממנו אח\"ז\". ומה שהסיר הגלולים, אינו מפני השבועה (שהי' כתוב עליהם), אלא מפני \"שהי' שונא לשמוע ולראות הגלולים בסמוך לו\". ע\"ש. אבל נוסף לזה שמפשטות הלשון בפדר\"א משמע שהסרת הגלולים היתה מפני השבועה הכתובה עליהם, הרי צלמים בכלל היו עוד כו\"כ, כדמוכח מקראי. ואכ\"מ."],["695","17","רד\"ל שם. ועוד."],["696","18","גיטין מו, א. רמב\"ם הל' מלכים פ\"ו ה\"ה."],["697","19","להעיר שביל\"ש וירא ויהושע שם, וכן בערוך ואברבנאל שם — לא הובא לשון הפדר\"א \"כי אם ברצונם של בני יבוס\"."],["698","20","מסעי לג, נב ואילך."],["699","21","ברד\"ל שם \"כיון שנצטוו בתורה (שופטים כ, טז) לא תחי' כל נשמה הרי נתבטל הברית ע\"פ הדבור\". וצ\"ע, דלפ\"ז גם בימי יהושע כבר בטלה השבועה (ועוד קודם שבע שכבשו), ואיך נאמר ביהושע שם \"לא יכלו. . להורישם\", שאינם רשאים (כספרי ורש\"י ראה שם). ודוחק לומר שלא יכלו מצד החילול השם שבדבר, כי פשטות הלשון לא משמע הכי אלא שנאסרו מצד השבועה עצמה.\nבזית רענן ליל\"ש יהושע שם דבני יבוס \"פרצו הגדר תחלה שנלחמו עם ישראל\" (ולכן הותר לישראל לכבוש ארצם). אבל ראה רד\"ל שם, שביבוסי לא מצאנו שפרצו הגדר. ע\"ש. ואכ\"מ."],["700","22","פרשתנו כג, ד."],["701","23","פרש\"י עה\"פ, מב\"ר פנ\"ח, ו."]]],[1301410148,"לאו אהי' תושב ואטלנה מן הדין<sup data-n=\"702\">24</sup> שאמר לי הקב\"ה<sup data-n=\"703\">25</sup> לזרעך אתן את הארץ הזאת\".\nוצריך ביאור:\nא) מכיון שביכלתו ליטלנה \"מן הדין\" — למה השתדל כ\"כ לקנות את מערת המכפלה (ובכסף מלא<sup data-n=\"704\">26</sup>)?\nב) כשאמר אברהם לבני חת \"אטלנה מן הדין\" התכוון בודאי שיאמינו לדבריו<sup data-n=\"705\">27</sup> שהקב\"ה הבטיח לו הארץ הזאת, וא\"כ אין תועלת בסירובם ויתנוה לו מרצונם הטוב — ולמה אמר \"אטלנה\" שמשמעו בע\"כ?\nג) באם הי' לוקחה בחוזק יד ובע\"כ<sup data-n=\"706\">28</sup> — יש בזה משום חילול השם אצל בני חת (שאברהם הי' מוכר אצלם כ\"נשיא אלקים\"<sup data-n=\"707\">29</sup>, ומפורסם כאיש שהנהגתו היא בתכלית החסד, היושר והצדק<sup data-n=\"708\">30</sup>).\nד) מדיוק לשונו \"אם תרצו הריני גר ואם לאו אהי' תושב\"<sup data-n=\"709\">31</sup> משמע, שהיותו גר או תושב תלוי ברצונם של בני חת. כלומר: אם ירצו בני חת למכור את מערת המכפלה, אזי \"הריני גר\" שאי אפשר לו ליטלנה מן הדין, ורק כשאין רצונם בכך (\"ואם לאו\"), אזי — \"אהי' תושב ואטלנה מן הדין\".\nותמוה: איך יתכן לומר שה\"דין\", אם מותר לאברהם ליטול את מערת המכפלה או לא, יהי' תלוי ברצונם<sup data-n=\"710\">32</sup> של בני חת?\nה) מדוע הביא אברהם את ההוכחה (שהוא יכול ליטלנה מן הדין) מהבטחת הקב\"ה \"לזרעך אתן את הארץ הזאת\" — שהנתינה היא לזרעו של אברהם — ולא מהבטחת הנתינה לאברהם עצמו — \"את כל הארץ גו' לך אתננה\"<sup data-n=\"711\">33</sup>?\nלפי המדרש<sup data-n=\"712\">34</sup>, שההוכחה היא מזה שא\"ל הקב\"ה \"לזרעך נתתי את הארץ הזאת\"<sup data-n=\"713\">35</sup>, אתי שפיר — כי כתוב זה אינו הבטחה על העתיד, אלא ל' עבר, בלשון הירושלמי<sup data-n=\"714\">36</sup> \"לזרעך נתתי — כבר נתתי\", וכדאיתא גם במדרש<sup data-n=\"715\">37</sup> על כתוב זה, ש\"מאמרו של הקב\"ה מעשה\". וא\"כ עדיפא אמירה זו של הקב\"ה (\"לזרעך נתתי\") גם לגבי האמירה \"לך אתננה\" שהיא רק הבטחה על העתיד;\nאבל לפי פרש\"י, שההוכחה היא מ\"לזרעך אתן את הארץ הזאת\" — קשה, כנ\"ל: מדוע לא הביא ההבטחה \"לך אתננה\"<sup data-n=\"716\">38</sup>?",[["702","24","בב\"ר \"אם רציתם גר ואם לאו מארי ביתא\"."],["703","25","לך יב, ז. ובב\"ר הובא פסוק אחר — ראה בסוף הסעיף."],["704","26","פרשתנו שם, ט."],["705","27","ולהעיר מפדר\"א שהובא לעיל (סעיף א), ש\"אמרו לו אנו יודעים שהקב\"ה עתיד ליתן לך ולזרעך כו'\"."],["706","28","להעיר מפי' המיוחס לרש\"י בב\"ר שם \"מארי ביתא, בעל כרחכם שכך כו'\". אבל מובן שאין כוונתו שיקחנו בחזקה ובזרוע, כ\"א בע\"כ בדין."],["707","29","פרשתנו שם, ו."],["708","30","ראה וירא (יח, יט) למען אשר יצוה גו' לעשות צדקה ומשפט."],["709","31","ברש\"י בב\"ר שם: הריני כגר. ובמדרש אגדה (באבער): אם תרצו אהי' כגר ואם לאו אהי' כתושב."],["710","32","להעיר מהגירסא בב\"ר (הובאה בהוצאת תיאדור) \"אם רציתי\". וכן במדרש שכל טוב כאן."],["711","33","לך יג, טו. ועד\"ז שם, יז. וראה הלשון בפדר\"א שהובא בתחילת השיחה."],["712","34","ב\"ר שם."],["713","35","לך טו, יח."],["714","36","חלה פ\"ב ה\"א."],["715","37","ב\"ר פמ\"ד, כב."],["716","38","ביאור דברי רש\"י (והשינוי לגבי לשון המדרש) ע\"ד הדרש (והרמז) — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151146\" data-slug=\"likkutei-sichot\" data-id=\"1300151146\">לקו\"ש חט\"ו ע' 146</a> ואילך (וש\"נ). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151204\" data-slug=\"likkutei-sichot\" data-id=\"1300151204\">וראה שם ע' 204</a> ואילך ע\"ד ההלכה."]]],[1301410149,"ד. וי\"ל הביאור בכל זה:\nבבעלות בנ\"י על ארץ ישראל יש שני פרטים: בעלות כללית — זה שכל הארץ שייכת לכלל ישראל, ובעלות פרטית — זה שכל אחד מישראל יש לו חלק פרטי בארץ השייך (רק) אליו.\nושני אופני בעלות אלו דבנ\"י בארץ ישראל באו בפועל<sup data-n=\"717\">39</sup> על ידי שני קנינים: הבעלות הכללית באה ע\"י כיבוש הארץ ע\"י יהושע כו', שעי\"ז נקנית כללות א\"י לכלל ישראל, והבעלות הפרטית דכאו\"א מישראל בחלקו הפרטי נעשית על ידי ישיבה וחזקה, שכ\"א ישב והחזיק בחלקו<sup data-n=\"718\">40</sup>.\nזאת ועוד: שני אופנים אלה בבעלות אינם תלויים זב\"ז; אפשר להיות בעלות כללית בלי בעלות פרטית ובעלות פרטית בלי בעלות כללית.\nהסברת הדבר:\nבעלות כללית אינה שוללת הבעלות הפרטית, וכמו בעלות המלך על המדינה שלו, דעם היות שכל הארץ כולה היא ברשות המלך<sup data-n=\"719\">41</sup>, מ\"מ אין זה שולל בעלותו הפרטית של כאו\"א מבני המדינה על רכושו הפרטי (ביתו, שדהו וכו'), אלא שמצד בעלותו של המלך על כל הארץ חלים כמה דינים גם על הרכוש הפרטי של כאו\"א — דדינא דמלכותא דינא<sup data-n=\"720\">42</sup>, ולכן מוטל עליו לשלם מסים למלך על רכוש זה, ועד שבתנאים מסויימים יכול המלך ליטול גם את רכושו של האיש הפרטי<sup data-n=\"721\">43</sup>, וכהדין ד\"מלך פורץ גדר. . ואין ממחין בידו\"<sup data-n=\"722\">44</sup>, וכו'.\nולאידך, בעלות הפרטית אינה מביאה (בהכרח) בעלות כללית<sup data-n=\"723\">45</sup>. וכמו שמצינו לאחרי חורבן הראשון, דאף את\"ל שבטלה בעלותם הכללית של בנ\"י על הארץ<sup data-n=\"724\">46</sup> — ד\"כיון שנלקחה הארץ מידיהם בטל הכיבוש\" ועד ש\"נפטרה מן התורה ממעשרות ומשביעית שהרי אינה מן ארץ ישראל\"<sup data-n=\"725\">47</sup> — מ\"מ נשארה בעלות היחיד על קרקעו, וכמש\"נ בירמי'<sup data-n=\"726\">48</sup> \"שדות בכסף יקנו וכתוב בספר וחתום\", כי אין הבעלות הפרטית תלוי' בבעלות הכללית.\nה. ועפ\"ז מובנים דברי אברהם לבני חת — \"אם תרצו הריני גר ואם לאו אהי'",[["717","39","דאף שא\"י ירושה לנו מאבותינו (ב\"ב קיט, ב. ע\"ז נג, ב) — מ\"מ \"לא נקנית להם אלא בחזקה כו' במה ירשתם בישיבה כו'\" (שו\"ע אדה\"ז חו\"מ קו\"א להל' הפקר בתחלתו). וראה בארוכה השקו\"ט בגדרי הבעלות דא\"י מזמן האבות — אנציקלופדי' תלמודית ערך א\"י (ע' ר ואילך. וש\"נ). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151103\" data-slug=\"likkutei-sichot\" data-id=\"1300151103\">לקו\"ש חט\"ו ס\"ע 103</a> ואילך. וש\"נ. ועוד. ואכ\"מ."],["718","40","ראה המקנה קידושין (כו, א ד\"ה בחזקה מנ\"ל. שם יד, ב ד\"ה בא\"ד ועוד נראה) דהחזקה היינו החלוקה שביניהם לקנות כאו\"א חלקו, ולא לקנות מן הכנענים. ועיין שו\"ע אדה\"ז שם. ואכ\"מ."],["719","41","ראה שו\"ע אדה\"ז שם ס\"ג."],["720","42","גיטין י, ב. וש\"נ. וראה קו\"א לשו\"ע אדה\"ז שם."],["721","43","ראה רמב\"ם הל' גזלה ואבידה פ\"ה הי\"א ואילך. הל' מלכים פ\"ד."],["722","44","ב\"ב ק, ריש ע\"ב. וראה גם משנה סנהדרין כ, ב ובפרש\"י שם. וראה רמב\"ם הל' מלכים פ\"ה ה\"ג ובלח\"מ שם."],["723","45","ובארות אברהם ויצחק, קנית חלקת השדה מיד בני חמור נשיא הארץ וכו' יוכיחו."],["724","46","שנעשית על ידי כיבוש יהושע (דאתי כיבוש ומבטל כיבוש — ראה הנסמן בהערה הבאה). וראה בהנסמן לעיל הערה 39. ואכ\"מ."],["725","47","רמב\"ם ספ\"ו מהל' ביהב\"ח ובנ\"כ שם."],["726","48","לב, מד. וראה ב\"ב כח, סע\"ב. וברבינו גרשום שם: מי שקנה עכשיו בתים או שדות במקום הזה יכתוב בשטר ויחתום עדים כדי שתהא הקרקע ברשותכם וכשתחזרו מן הגלות ויבואו המוכרים להוציא מידכם כו' תראו להם שטריכם כו'."]]],[1301410150,"תושב ואטלנה מן הדין\": החילוק בין האופן ד\"הריני גר\" (עי\"ז שבני חת ימכרו לו את מערת המכפלה) להאופן ד\"אהי' תושב ואטלנה מן הדין\" — הוא בגדר הבעלות של אברהם על מערת המכפלה:\nמערת המכפלה, כמו כל הארץ סביב לה, היתה אז ברשותם ובבעלותם הכללית של בני חת, ובקשת אברהם לקנותה מעפרון היתה רק לרכוש את הבעלות הפרטית (דעפרון) של מקום זה, אבל גם אח\"כ תשאר בעלותה הכללית בידי בני חת (שלא מצינו שאברהם כבש מלכות בני חת).\nוזהו \"הריני גר\" — כי הארץ נשארה בבעלותם הקודמת של בני חת, ואברהם הוא \"גר\" הקונה רכוש פרטי במדינת — במלכות בני חת.\nאמנם כל זה הוא אם יסכימו בני חת למכור לו את מערת המכפלה, אבל \"אם לאו — אהי' תושב ואטלנה מן הדין\", שנטילת המערה תהי' תוצאה (והמשך) מהבעלות הכללית על ארץ ישראל.\nוהביאור: אברהם ידע שאדם וחוה קבורים במערת המכפלה<sup data-n=\"727\">49</sup>, ובאם לא יסכימו בני חת למוכרה לו (באופן שתגיע לו הבעלות הפרטית), וירצו להכריחו לקבור שרה במק\"א לא אצל חוה צלע מצלעותיו דיציר כפיו של הקב\"ה, הרי איגלאי מילתא שכבר הגיע זמן קיום ההבטחה \"לזרעך אתן את הארץ הזאת\", ותנתן לו (גם) הבעלות הכללית — \"אטלנה מן הדין\"<sup data-n=\"728\">50</sup>.\nו. עפ\"ז מתורץ ג\"כ מדוע הובא ע\"ז בפרש\"י הכתוב \"לזרעך אתן את הארץ הזאת\" (או במדרש \"לזרעך נתתי את הארץ הזאת\") — ולא הכתוב \"לך אתננה\", ובהקדים:\nשני אופני בעלות הנ\"ל לישראל בארץ ישראל הובטחו לאברהם אבינו: הכתובים \"לזרעך אתן את הארץ הזאת\", \"לזרעך נתתי את הארץ\", ענינם בעלות הכללית של עם ישראל על הארץ, ואילו בהכתוב \"לך אתננה\" מדובר בבעלות הפרטית של ישראל על חלקו בארץ.\nוההסברה בזה — יש לומר:\nההבטחה \"לזרעך אתן את הארץ הזאת\" (וכן הכתוב \"לזרעך נתתי את הארץ הזאת\") כוללת את כל הארץ בלשון \"כללי\", \"הארץ הזאת\". והוא לפי שהנידון הוא \"הארץ\" — ארץ ישראל השייכת בכללותה לכללות עם ישראל;\nבההבטחה ד\"לך אתננה\" הרי הכתוב מאריך בה ומפרט ואומר<sup data-n=\"729\">51</sup> \"ראה מן המקום אשר אתה שם צפונה ונגבה וקדמה וימה גו' לך אתננה ולזרעך עד עולם ושמתי את זרעך כעפר הארץ אשר אם יוכל איש למנות את עפר הארץ גם זרעך ימנה. קום התהלך בארץ לארכה ולרחבה גו'\".\nכלומר:\nא) בכתובים אלו מודגש גודל שטח הארץ וגם פרטיו (\"וראה גו' צפונה ונגבה וקדמה וימה גו'\") וריבוי זרעו של אברהם ומנין בו — שמשמעות המשך הכתובים היא, שנתינת ארץ רחבת ידים כזו מתאימה לההבטחה ד\"ושמתי את זרעך כעפר הארץ\", שלכן זקוקים הם לארץ גדולה ביותר וחלק זרעך יהי' בצפונה, חלקו בנגבה וכו'; וענין זה קשור עם הבעלות הפרטית של כאו\"א מישראל על חלקו בארץ.",[["727","49","ראה פרש\"י פרשתנו כג, ב."],["728","50","ע\"ד כיבוש מלך. ולכן אמר ע\"ז \"אטלנה מן הדין\" שמשמעו בע\"כ."],["729","51","לך יג, יד-יז."]]],[1301410151,"ב) \"קום התהלך בארץ לארכה ולרחבה\" — שאברהם יחזיק בארץ, קנין חזקה (כמבואר בגמ'<sup data-n=\"730\">52</sup>) — קאי ג\"כ על קנין השייך לבעלות פרטית, כנ\"ל שחזקה היא (בעיקרה) בקנין הפרטי.\nז. ויש לומר, שזהו גם טעם החילוק שבין הכתובים — דבפסוקים המדברים אודות הבעלות הכללית נאמר רק \"לזרעך\", ואילו בהכתובים ע\"ד הבעלות הפרטית נאמר \"לך אתננה ולזרעך עד עולם\", בהדגשת הנתינה לאברהם בפ\"ע:\nאברהם אבינו הי': (א) ראש לאומה הישראלית, הכוללת את כל בנ\"י, ומצד זה הנה כל ענין שנאמר אליו (או ניתן לו) הרי זה ענין ד\"כלל ישראל\"<sup data-n=\"731\">53</sup>; והוא גם (ב) ה\"אב\" של כאו\"א מישראל באופן פרטי, כתוארו \"אברהם אבינו\", אביהם של כאו\"א מישראל.\nולפי זה: ההבטחה לאברהם ע\"ד הבעלות הכללית דא\"י היא לאברהם בתור ראש האומה (כלל ישראל), וההבטחה בנוגע להבעלות הפרטית — היא לאברהם בתור ה\"אב\" של כאו\"א מישראל<sup data-n=\"732\">54</sup>.\nולכן בהכתובים שבהם באה הבטחה לאברהם ע\"ד הבעלות הכללית, נאמר בהם רק \"לזרעך אתן\" (לזרעך נתתי), כי זה אינו בגדר ירושה באופן פרטי מאב לבן, אלא ניתן לכלל ישראל (ולהעיר שהוא הוא אותו ה\"כלל\" במשך כל הדורות<sup data-n=\"733\">55</sup>); משא\"כ בהבעלות הפרטית שנאמרה לאברהם בתור \"אב\", שמוריש לכאו\"א מבניו, נאמר \"לך אתננה<sup data-n=\"734\">56</sup> ולזרעך\", שבזה מודגש היחס ד\"אב\" ו\"בן\" שבין אברהם וזרעו, שעי\"ז באה הארץ בירושה מהאב — אברהם — לזרעו עד עולם<sup data-n=\"735\">57</sup>.",[["730","52","ב\"ב ק, א (דעת ר\"א). ובתרגום יונתן לך שם \"עבד בה חזקתה\". וראה גם ירושלמי קדושין פ\"א ה\"ג. וכן בהנסמן לעיל הערה 39."],["731","53","וכפשוטו, דאז (לפני לידת יצחק) הי' אברהם כלל ישראל להיותו היהודי היחידי. ולהעיר מצפע\"נ עה\"ת ר\"פ וישב בנוגע ליעקב."],["732","54","להעיר מיחזקאל לג, כד: אחד הי' אברהם ויירש את הארץ ואנחנו רבים לנו נתנה הארץ למורשה."],["733","55","דצבור לא מת (הוריות ו, א) — אלא שצ\"ע אם כן הוא בנוגע לפני מ\"ת ולאחר מ\"ת."],["734","56","ראה גם ע\"ז נג, ב: מכדי ירושה היא להם מאבותיהם. ובפרש\"י שם ד\"ה ואשריהם. וע\"פ הנ\"ל בפנים יש לפרש מ\"ש רש\"י שם \"שהרי לאברהם נאמר כי לך אתננה\", כי שם קאי לא רק בדין הבעלות הכללית אלא בדין הבעלות הפרטית, וכדיוק לשון הגמרא \"ירושה היא להם מאבותיהם\". וראה יחזקאל שם ובמפרשים. ועצ\"ע."],["735","57","ואולי יש לקשר לזה השקו\"ט והפלוגתא אם גר מביא בכורים וקורא (ראה בכורים פ\"א מ\"ד), ולהלכה פסק הרמב\"ם (הל' בכורים פ\"ד ה\"ג) \"הגר מביא וקורא שנאמר לאברהם (לך יז, ה) אב המון גוים נתתיך הרי הוא אב כל העולם כולו שנכנסין תחת כנפי שכינה\". וראה פיהמ\"ש להרמב\"ם בכורים שם.\nוע\"פ הנ\"ל י\"ל דזה מה שגר קורא הוא לא מצד היותו חלק מכלל ישראל (כבנ\"י שאצלם ישנה הבעלות כללית מאברהם כראש האומה), כ\"א בגדר בן היורש מאב שלו — אברהם<sup data-n=\"e17\">*</sup>.\nולהעיר שלעתיד גם הגרים יטלו חלק בארץ, שנאמר (יחזקאל מז, כאכג) \"וחלקתם את הארץ וגו' לכם ולהגרים הגרים בתוככם וגו' והי' בשבט אשר גר הגר אתו שם תתנו נחלתו\". וי\"ל דזהו בגדר בעלות פרטית שלהם בארץ דיורשים מאברהם<sup data-n=\"e18\">**</sup>.\nוראה רמב\"ן ב\"ב (פא, א) שהגרים בני אברהם ראוים לירושה אלא שנתחלקה הארץ ליוצאי מצרים כו'. וראה אנציקלופדי' תלמודית ערך גר. וש\"נ. ואכ\"מ."],["e17","*","להעיר מפיהמ\"ש להרמב\"ם שם: לפי שאברהם הי' אב לכל העולם לפי שהוא למדם אמונה."],["e18","**","וראה המשך דברי הרמב\"ם בהל' בכורים שם \"ולאברהם היתה השבועה תחלה שיירשו בניו את הארץ\"."]]],[1301410152,"ח. ע\"פ כל הנ\"ל יש לבאר ג\"כ ענין שבועת אברהם לבני חת \"שאין בני ישראל יורשים את עיר יבוס כי אם ברצונם\":\nאף שבנ\"י נצטוו<sup data-n=\"698\">20</sup> \"והורשתם את כל יושבי הארץ גו' וישבתם בה גו' והתנחלתם את הארץ\", שבזה נכלל לא רק מעשה הכיבוש של הבעלות כללית, כ\"א גם \"וישבתם בה\", שזהו חזקת כ\"א בקרקע שלו, בעלות הפרטית — מ\"מ שאני הבעלות הכללית מבעלות הפרטית, דהבעלות הכללית ניתנה כולה לעם ישראל, מבלי שום נתינת מקום לשליטת זר; משא\"כ בנוגע לישיבה בארץ, הרי בתנאים מסויימים מותרים גם האומות להשאר בארץ, וגם מז' האומות. וכמו שנצטווינו<sup data-n=\"737\">58</sup> \"כי תקרב אל עיר להלחם עלי' וקראת אלי' לשלום\", שדין זה הוא גם בנוגע לז' האומות<sup data-n=\"738\">59</sup>, וכמו שעשה יהושע ד\"שלשה<sup data-n=\"739\">60</sup> כתבים שלח יהושע עד שלא נכנס לארץ הראשון שלח להם מי שרוצה לברוח יברח וחזר ושלח מי שרוצה להשלים ישלים כו'\"<sup data-n=\"740\">61</sup>.\nועפ\"ז יש לבאר בנדו\"ד: שבועת אברהם לא היתה שבנ\"י לא ירשו את הבעלות הכללית דעיר (ארץ) היבוס — כי אא\"פ להשבע נגד הבטחת הקב\"ה \"לזרעך אתן (נתתי) את הארץ הזאת\"; אלא המדובר בשייכות להבעלות הפרטית, דאף שבנ\"י ישלטו על ארץ יבוס כי היא חלק מארצם, מ\"מ בקשו לכרות ברית שלא יחזיקו בה ישראל בבעלות פרטית \"כי אם ברצונם\" (של בני יבוס). והיינו, שגם בני חת הסכימו להשאר תחת שליטת וממשלת בנ\"י, וכל כוונתם היתה רק שלא תושלל מהם בעלותם הפרטית על עיר יבוס — שבאופן זה אין איסור (וכההודעה ה\"רוצה להשלים ישלים\")<sup data-n=\"741\">62</sup>.\n[וענין זה מודגש גם בלשון בקשת בני חת — \"אנו יודעים שהקב\"ה עתיד ליתן לך ולזרעך את כל הארצות האל, כרות עמנו שבועה כו'\", היינו שגם הם יודעים שהקב\"ה עתיד ליתן הארץ (כולל עיר היבוס) לישראל, ולכאורה מה מקום לכרות ברית לעשות ההיפך — \"שאין בנ\"י יורשים כו'\"? אלא שגם לדעת בני חת, השבועה \"שאין בנ\"י יורשים את עיר יבוס\" אינה בסתירה לזה \"שהקב\"ה עתיד ליתן לך ולזרעך את כל הארצות האל\"].\nובזה יומתק הקשר בין שבועה זו לקניית מערת המכפלה: לאחרי שהסכימו למסור (למכור) לאברהם את בעלותו הפרטית של מקום מערת המכפלה — ביקשו מאברהם, מדה כנגד מדה, שישבע להם דגם כאשר הבעלות הכללית",[["698","20","מסעי לג, נב ואילך."],["737","58","שופטים כ, יו\"ד ואילך."],["738","59","רמב\"ם הל' מלכים פ\"ו. וראה בארוכה לח\"מ שם."],["739","60","רמב\"ם שם ה\"ה (מירושלמי שביעית פ\"ו ה\"א)."],["740","61","וראה רמב\"ן שופטים שם. מפרשי רש\"י שם. ועוד."],["741","62","ראה בארוכה רד\"ק ש\"ב כד, כג שבני היבוס היו \"למס עובד\"<sup data-n=\"e19\">*</sup> (ראה רמב\"ם הל' מלכים שם ה\"א). וצע\"ק שבשופטים (א, כא) לא נאמר אצל היבוסי שהיו \"למס\" כמש\"נ שם לאח\"ז אצל שאר האומות ש\"לא הורישו\"."],["e19","*","דמפשטות לשונו \"שנשארו שם משכבשוה בני יהודה כו' והיו שם למס עובד כו' ע\"י המס שהיו עובדים לבני יהודה ובני בנימין\" משמע שכוונתו דעוד מזמן כיבוש בני יהודה ובני בנימין היו למס עובד (אבל ראה אברבנאל ש\"ב שם)."]]],[1301410153,"של הארץ תעבור לרשות ישראל, לא תלקח מהם הבעלות הפרטית של עיר היבוס \"כי אם ברצונם\".\nט. עפ\"ז מובן גם המשך הסיפור בפרקי דר\"א בנוגע לדוד המלך:\nטעמו של דוד ש\"רוצה ליכנס בעיר היבוסי\" בפשטות הי' כי בא הזמן להכין את מקום המקדש, שהוא בעיר היבוס (ירושלים)<sup data-n=\"742\">63</sup>. וע\"פ הנ\"ל, ששבועת אברהם לבני חת היתה רק בשייכות לבעלות הפרטית של העיר, מובן בפשטות, שלקיחת מקום זה כדי להכין בנין המקדש מעיקרא לא נכללת בשבועה זו. שהרי לקיחה זו היא בשביל כלל ישראל, ושייכת לבעלות הכללית על הארץ (וע\"ד לקיחת רכוש פרטי הנצרך להנהגת המלוכה ע\"י המלך).\nכלומר: אי קיום השבועה הי' רק אם הי' מגרש אותם מהעיר כדי שיתיישב איש פרטי במקומם, לקיחת הבעלות הפרטית דהיבוסי ע\"י בעלות פרטית דבנ\"י (וזוהי כוונת הכתוב ביהושע \"לא יכלו. . להורישם\"), משא\"כ לקיחת המקום עבור כלל ישראל אין זה שייך להשבועה [וכשם שידע אברהם שהקב\"ה עתיד ליתן לו כל הארצות האל, כך ידע שבמקום העקדה בהר ה' יראה<sup data-n=\"743\">64</sup> — שעתידים לבנות ביהמ\"ק בעיר היבוסי, ולא ישבע להם \"שאין בנ\"י יורשים את עיר יבוס כי אם ברצונם\" באופן שבנין ביהמ\"ק יהי' תלוי ברצונם של בני יבוס!].\nיוד. עפ\"ז מובן, דזה שבני היבוס לא הניחו לדוד ליכנס מכח ברית שבועת אברהם הי' שלא כדין, שהרי בזה התנגדו לבעלות הכללית של בנ\"י על הארץ (בטעותם שבשבועת אברהם נכלל גם שהבעלות הכללית על עיר היבוס היא בידיהם), ומותר לו לדוד להלחם עמהם וללכוד העיר.\nומטעם זה צוה דוד להסיר הגלולים שעליהם כתובה השבועה — מאחר שבני היבוס השתמשו בשבועה זו שלא כדין.\nאמנם, מזה גופא מובן, דגם לאחרי שלכד דוד את עיר היבוס עדיין לא בטלה עי\"ז השבועה, כי לכידתו את העיר היתה רק מדין כיבוש מלך, כדי לשלוט עליהם (בעלות הכללית), ואין זה נוגע להשבועה שלא תלקח מהם הבעלות הפרטית \"כי אם ברצונם\";\nולכן, אף שהי' יכול להורישם מכח הבעלות הכללית (ע\"ד מלך פורץ גדר כו'), ובפרט מקום המקדש שנצרך לכלל ישראל — מ\"מ, כדי לצאת ידי השבועה, \"קנה את עיר היבוסי לישראל<sup data-n=\"744\">65</sup> בכתב עולם לאחוזת עולם\".\n<span data-k=\"q\">(משיחת ש\"פ ראה תשמ\"ו) </span>",[["742","63","ראה רד\"ל לפדר\"א שם אות פז. וראה מפרשים לש\"ב בסופו."],["743","64","וירא כב, יד ובפרש\"י שם."],["744","65","תיבה זו (שלכאורה מיותרת) משמעה — בעלות כללית דישראל. אבל עפמ\"ש בפדר\"א שם שדוד לקח מכל שבט נ' שקלים י\"ל, שהכוונה לבעלות פרטית, כדי שיהי' לכל ישראל קנין במקום המקדש ובעיר ירושלים (כפשטות לשון הפדר\"א שדוד קנה כל עיר היבוסי*). וצ\"ע בהא שירושלים לא נתחלקה לשבטים (יומא יב, א. רמב\"ם הל' רוצח ושמירת נפש פ\"ט ה\"ד (מהשיעורים דשבוע זה — בשנת הדפסת השיחה — תשמ\"ז)). ואכ\"מ.\n————————\n*) והוא דלא כפשטות הכתובים בסוף ש\"ב (ודה\"א כא, יח ואילך) שקנה רק מקום הגורן (מקום המקדש). וראה זבחים קטז, ב ובפרש\"י שם."]]],[1301410154,"<h3>שיחה ב</h3>\nא. מן הפסוק<sup data-n=\"745\">1</sup> \"ואבא היום אל העין גו'\" מעתיק רש\"י \"ואבא היום\" ומפרש \"היום יצאתי והיום באתי מכאן שקפצה לו הארץ\". היינו, דמיתור לשון הכתוב \"ואבא היום\" — דלכאורה, \"היום למה לי\"<sup data-n=\"746\">2</sup> — ילפינן, שכוונת אליעזר היתה, \"היום יצאתי והיום באתי. . שקפצה לו הארץ\".\nוהנה נת' כמ\"פ, דכאשר רש\"י כותב \"מכאן\" (ואינו מסתפק בכתיבת הפירוש) — כוונתו בזה לדייק ולשלול, שדבר זה נלמד \"מכאן\" דוקא ולא ממקום אחר לפני זה (אף שלכאורה קס\"ד ללמוד משם דבר זה).\nויש להבין בנדו\"ד (שהוסיף \"מכאן\") — איזה \"מקום אחר\" שולל רש\"י בכתבו \"מכאן שקפצה לו הארץ\"?\nוהנה מקורו של פרש\"י זה הוא בסנהדרין<sup data-n=\"747\">3</sup>, דאיתא שם \"שלשה קפצה להם הארץ אליעזר עבד אברהם. . דכתיב ואבא היום אל העין למימרא דההוא יומא נפק\" (וכ\"ה בפרקי דר\"א<sup data-n=\"748\">4</sup> ומדרש תנחומא<sup data-n=\"749\">5</sup>). אבל במדרש רבה פרשתנו<sup data-n=\"750\">6</sup> עה\"פ<sup data-n=\"751\">7</sup> \"ויקם וילך אל ארם נהרים\" איתא \"ר' יצחק אמר בן יומו\" (\"בו ביום שיצא משם בו ביום בא לעין\"<sup data-n=\"752\">8</sup>), הרי שהענין דקפיצת הדרך של אליעזר כבר נרמז, לדעת המדרש, במ\"ש לעיל \"ויקם וילך אל ארם נהרים\", שהכניסה אל \"ארם נהרים\" היתה \"בו ביום\" ש\"ויקם וילך\".\nועפ\"ז הי' אפשר לומר, שכוונת רש\"י במ\"ש \"מכאן שקפצה לו הארץ\" היא לשלול דעת המדרש שילפינן זה מהכתוב \"ויקם וילך אל ארם נהרים\", ומובן גם טעמו בזה — כי בפשוטו של מקרא אין הכרח בפסוק \"ויקם וילך\" שהלך בקפיצת הדרך (משא\"כ \"כאן\" שיש יתור לשון דתיבת \"היום\" כנ\"ל).\nאמנם אין ביאור זה מספיק, כי זה שרש\"י צריך לשלול מקומות אחרים הוא רק כשיש קס\"ד בפשוטו של מקרא ללמוד דבר זה ממק\"א, אבל בנדו\"ד הרי מפשטות הלשון \"ויקם וילך\" אין משמעות והכרח שקפצה לו הארץ<sup data-n=\"753\">9</sup> — ולכאורה אין צורך לרש\"י לשלול זה<sup data-n=\"754\">10</sup>.\n[ובפרט שגם במדרש ממשיך \"הוא דעתי'",[["745","1","פרשתנו כד, מב."],["746","2","רא\"ם, גו\"א ועוד עה\"פ. חדא\"ג מהרש\"א סנהדרין צה, סע\"א. ועוד."],["747","3","שם."],["748","4","פט\"ז."],["749","5","ויצא ג."],["750","6","פנ\"ט, יא."],["751","7","כד, י."],["752","8","רש\"י לב\"ר שם."],["753","9","ביפ\"ת (השלם) לב\"ר שם \"דאל\"כ וילך וילך למה לי [\"וילך וכל טוב גו' ויקם וילך גו'\"], ועוד מ\"ש דכתיב הכא ויקם ולא בוילך קמא\" — הרי בפשטות י\"ל, ד\"וילך קמא\" לא בא לספר הליכתו בפועל, אלא שלקח עמו \"(וילך ו)כל טוב אדוניו בידו\". ועוד: \"וילך אל ארם נהרים\" אין פירושו ביאתו לארם נהרים אלא (תחילת) הליכתו לשם (ע\"ד \"וילך חרנה\" — ר\"פ ויצא וברש\"י)."],["754","10","וכן מ\"ש בב\"ר (פ\"ס, ו) עה\"פ (כד, כז) \"ברוך ה' גו' אשר לא עזב חסדו גו' בדרך נחני ה' גו'\" — \"ממה שקפצה הדרך לפני הייתי יודע כו'\" (וראה בחיי עה\"פ. מת\"כ לב\"ר שם) — שאין הכרח בפשטות ל' הכתוב שם שהיתה קפיצת הדרך. וראה רש\"י עה\"פ שם \"בדרך, דרך המזומן כו'\"."]]],[1301410155,"דר' יצחק ואבא היום אל העין היום יצאתי והיום באתי\", שי\"ל שכוונת המדרש היא<sup data-n=\"755\">11</sup>, שעיקר הלימוד שקפצה לו הארץ הוא ממש\"נ \"ואבא היום\" — ומזה ראי' לפרש דמ\"ש כאן \"ויקם וילך\" היינו \"בן יומו\"].\nב. אח\"כ ממשיך רש\"י: \"אמר רבי אחא יפה שיחתן של עבדי אבות לפני המקום מתורתן של בנים שהרי פרשה של אליעזר כפולה בתורה והרבה גופי תורה לא נתנו אלא ברמיזה\".\nותמוה — ענין זה מאי בעי הכא, באמצע דברי אליעזר? לכאורה, הו\"ל לרש\"י לכתוב ביאור זה (המוסב על כללות ה\"פרשה של אליעזר\") תיכף בתחילת דברי אליעזר (שהוכפלו) או בסיומם; ועוד למה הביאו רש\"י בכתוב זה דוקא?\nוביותר תמוה: במדרש רבה<sup data-n=\"756\">12</sup> — כן הובא מאמר ר\"א בקשר לתחילת הכפלת סיפור אליעזר<sup data-n=\"757\">13</sup>, ואילו רש\"י משנה<sup data-n=\"758\">14</sup> ומביאו בהמשך הסיפור עה\"פ ואבא היום גו'!\nלכאורה אפשר להסביר, כי דברי אליעזר שלפני פסוק זה (\"ואבא היום גו'\") הם סיפור של דברי אברהם, ולכן אין לתמוה (כ\"כ) מדוע חוזרת התורה עליהם; ורק בפסוק \"ואבא היום גו'\" שבו מתחיל סיפורו (ודבריו) של אליעזר עצמו, יש לדייק מדוע בא הכתוב להכפיל (גם) ענין זה — ולכן מתרץ רש\"י \"יפה שיחתן של עבדי אבות כו'\".\nאבל מלבד הדוחק בעצם החילוק (שהקושיא בהכפלת הסיפור היא רק על דברי אליעזר עצמו) — הרי סו\"ס גם דבריו הראשונים של אליעזר אינם (דברי אברהם) אלא \"שיחתן של עבדי אבות\", הם חלק מסיפורו של אליעזר, ופשטות כוונת רש\"י ב\"יפה שיחתן כו'\" היא גם לדיבורים אלו, וכמובן מהמשך לשונו \"שהרי פרשה של אליעזר כפולה בתורה\", ופשוט שב\"פרשה\" נכללים גם דיבוריו הראשונים.\nג. גם צריך להבין:\nא) גם את\"ל שעיקר הקושיא בטעם הכפלת הפרשה היא בכתוב זה, ולכן מתרצה רש\"י כאן דוקא — עדיין אינו מובן, מדוע כותב רש\"י ענין זה בהמשך לפירושו \"ואבא היום. . מכאן שקפצה לו הארץ\", וה\"ז ענין בפ\"ע והו\"ל לכתבו בדיבור בפ\"ע<sup data-n=\"759\">15</sup>? [וכמו שמצינו במקומות רבים בפרש\"י על התורה, דכאשר מפרש שני ענינים נפרדים באותן התיבות, דרכו להעתיק תיבות הכתוב פעמיים<sup data-n=\"760\">16</sup>, לחלק",[["755","11","כמ\"ש בנחלת יעקב על פרש\"י כאן (בתי' הב'). — במדרש לקח טוב שם \"ויקם וילך, מלמד שקפצה לו הדרך\". אבל כמה פי' בו הם מדרש ואינם בפשוטו של מקרא."],["756","12","פ\"ס, ח."],["757","13","עה\"פ (כד, לב) \"ויתן תבן גו'\". ואף שדברי אליעזר מתחילים בפסוק לד — נקבע המאמר על פסוק זה, בגלל הדרשה הב' דר\"א שבמדרש שם \"יפה רחיצת רגלי עבדי בתי אבות כו'\" (ראה יפה תואר (השלם) לב\"ר שם)."],["758","14","ובנחלת יעקב על פרש\"י כאן ש\"גירסת הרב (רש\"י) היתה על זה הפסוק\" (היינו שכן היתה גירסת רש\"י במדרש).\nומה שביאר הטעם \"לפי שבזה הפסוק נכפל הנס דהא מרומז בפסוק ויקם וילך וגם בזה הפסוק\" (וראה יפה תואר (השלם) ונזר הקדש (השלם) לב\"ר פנ\"ט שם) — צע\"ג לפרש כן ברש\"י, שהרי רש\"י מדייק \"מכאן שקפצה לו הדרך\", ושולל הלימוד מלפני זה, מ\"ויקם וילך\" (כנ\"ל ס\"א). וראה עוד תי' (ע\"ד הדרש כו') בחדושי מהרש\"א עה\"ת פרשתנו (כד, יז). נחל קדומים (להחיד\"א) ועוד כאן."],["759","15","ראה הערה שלפנ\"ז."],["760","16","לדוגמא בפרשתנו לעיל — כד, ז. שם, יט. שם, כא."]]],[1301410156,"שני הענינים בשני ד\"ה נפרדים (מאחר שאין קשר ביניהם — בתוכנם)].\nיש מפרשים<sup data-n=\"761\">17</sup> \"דקשה לרש\"י מאי בא לנו הקרא לאשמעינן שקפצה לו הארץ. . דאין לומר שבזה נמי הוכיח שמה' יצא הדבר ליתן לו את רבקה, שהרי נס זה נעשה לו אין זה הוכחה על רבקה דלמא בתולה אחרת יש בעיר הזאת שישאנה, א\"נ משום שזכותו של אברהם היא שקפצה לו הארץ, אלא על כרחך צ\"ל: אף שאין צריך לכתוב ולא אשמעינן כלום אפילו הכי כתבו משום דבא לאשמעינן שחביב לפני הקב\"ה כדר' אחא וכו'\".\nאבל תירוץ זה צע\"ג, שהרי אף אם נאמר שבנס זה (של קפיצת הדרך) אין \"הוכחה על רבקה\" בפרט<sup data-n=\"762\">18</sup>, הרי פשיטא שהוא מראה בגלוי שה' הצליח דרכו בשליחות זו (בכלל)<sup data-n=\"763\">19</sup> — והרי זו היתה כוונת אליעזר, להוכיח לבתואל שהשם עמו והצליחו בכל — וכיצד אפשר לומר שדבר זה \"לא אשמעינן כלום\"?\nובפרט שדבר זה נוגע גם למבוקש עיקרי בשייכות לרבקה — בקשת אליעזר \"אל תאחרו אותי וה' הצליח דרכי\"<sup data-n=\"764\">20</sup>, היינו לקחת את רבקה בלי שהי' ועיכוב בטענו \"וה' הצליח דרכי\", שבפשטות הראי', דכיון שהקב\"ה עשה לו נס דקפיצת הדרך, הרי מזה הוכחה שאין לאחר את שילוחה של רבקה<sup data-n=\"765\">21</sup>.\nב) מדוע מעתיק רש\"י שם בעל המאמר — \"אמר רבי אחא\"? — וכמדובר כמה פעמים, שבהביאו שם האומר כוונתו ליישב שאלה בהענין שיכולה להתעורר אצל \"תלמיד ממולח\" לאחרי התבוננות כו' (שלכן אין רש\"י צריך לתרצה בפירוש, אלא רק ע\"י ציון שם בעל המאמר, כלומר, שהתשובה מרומזת בשיטתו (או הנהגתו וכיו\"ב) של תנא או אמורא זה).\nד. ויש לומר, שחדא מתורצת בחבירתה, כלומר, דיוקו של רש\"י (הנ\"ל סעיף א) \"מכאן שקפצה לו הארץ\", הוא המכריח המשך פירושו \"אמר רבי אחא יפה שיחתן כו'\":\nעצם ההכפלה (אפילו כשהיא באופן מפורט ובאריכות) — ע\"פ פשוטו של מקרא אינו דבר המוקשה ומכריח ביאור<sup data-n=\"766\">22</sup>, כי מצינו כמ\"פ בתורה הכפלת ענין, ולא נחית רש\"י לפרש בכל פעם טעם ההכפלה [וע\"ד סיפור בריאת אדם הראשון, שנשנה בתורה פעמיים<sup data-n=\"767\">23</sup> (פעם בדרך כלל ופעם בדרך פרט<sup data-n=\"768\">24</sup>) ולא פרש\"י הטעם שנאמר בב' מקומות (ולא",[["761","17","מנחת יהודה על פרש\"י כאן."],["762","18","אבל לכאורה אינו, כי זה שבא בקפיצת הדרך מראה עוד יותר, דזה שנזדמנה לו רבקה בתפלתו הוא מפני שה' הצליח דרכו ו\"מה' יצא הדבר\". ולהעיר מדברי אליעזר לבתואל (כד, לח. וכן שם, ממא) \"אל בית אבי. . ואל משפחתי\" (אף שלא נזכר בדברי אברהם — לעיל כד, ד. שם, ז)."],["763","19","ראה גם יפה תואר לב\"ר פנ\"ט שם. וראה ב\"ר ובחיי שבהערה 10. ועוד. — וראה מלאכת הקדש על פרש\"י כאן \"דהאי קרא לאו יתר הוא דטובא קמ\"ל שקפצה לו הארץ כפרש\"י\"."],["764","20","כד, מו."],["765","21","אלא שאצל בתואל לא נתקבלה טענה זו, כי אפשר שזה הי' בכדי להקדים התחלת ההכנות די\"ב חדש כו', אבל לא לקחת אותה דוקא תיכף (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101068\" data-slug=\"likkutei-sichot\" data-id=\"1300101068\">לקו\"ש ח\"י ע' 68</a> הערה *17)."],["766","22","ובפרט בנדו\"ד, שי\"ל כהרשב\"ם כאן \"כל אריכות דברים להודיעם שמאת הקב\"ה יצא הדבר\". ועד\"ז כ' בחזקוני כאן \"ולפי הפשט נכפלה להודיעך כי הוא ספר להם כו' שאל\"כ תתמה היאך הסכימו לו מיד כו'\"."],["767","23","בראשית א, כז. שם ב, ז."],["768","24","פרש\"י שם, ח. — ולהעיר שג\"ז לא כתב רש\"י בתחילת ה\"חזרה\" שם (בפסוק ז)."]]],[1301410157,"כתבה התורה כל הסיפור בהמשך אחד)].\nהקושיא מתעוררת רק בפסוק \"ואבא היום\" שלמדים \"מכאן שקפצה לו הארץ\": הכתוב משמיענו אודות נס זה \"שקפצה לו הארץ\", לא לעיל במקומו — כשמספר גוף המאורעות של הליכת אליעזר לארם נהרים (\"ויקם וילך אל ארם נהרים גו'\"), אלא רק בסיפורו של אליעזר לבתואל אודותם.\nועכצ\"ל שטעם הדבר הוא: מכיון שבעיקר זה נוגע לדברי אליעזר לבתואל, שבזה רצה להוכיח לו שמהשם יצא הדבר ולא יעכב את השידוך (כנ\"ל), לכן כתוב ומודיע שקפצה הדרך דוקא בסיפורו כאן.\nאבל אם כן, מאחר שאנו רואים שהכתוב לא רצה לספר נס זה ב' פעמים, ועד כ\"כ שמשמיטו ממקומו (סיפור המאורע עצמו — כדי שלא תהי' הכפלה) ומספרו רק במקום שהוא מוכרח להבנת הענין — מתעוררת תמי' גדולה: מהו טעם האריכות בפרשה של אליעזר, שהיא כפולה בתורה על כל פרטי' שתי פעמים ולא מספיק לספרה רק פעם אחת (ובמכש\"כ מסיפור ע\"ד נס)?\nוזהו שפרש\"י: \"ואבא היום כו' מכאן שקפצה לו הארץ (ולא לעיל במקומו<sup data-n=\"769\">25</sup>)\" — ועל תמיהת הלומד, א\"כ מ\"ט הוכפל כללות הסיפור, ממשיך רש\"י בהתירוץ: אמר רבי אחא יפה שיחתן של עבדי אבות כו' שהרי פרשה של אליעזר כפולה בתורה והרבה גופי תורה לא נתנו אלא ברמיזה.\nה. אלא ש\"תלמיד ממולח\" יכול לשאול: הא גופא טעמא בעי — למה לא ניתנו הרבה גופי תורה אלא ברמיזה, ולא בפירוש ובאריכות (ובפרט שפשוט שע\"י נתינת גופי תורה ברמיזה יכולים לבוא לידי טעות בהבנת ההלכה כו')?\nוהתירוץ על שאלה זו מרמז רש\"י בציינו שם בעל המאמר — רבי אחא:\nעל הכתוב<sup data-n=\"770\">26</sup> \"ודברת בם\" (בדברי תורה) דרש רבי אחא<sup data-n=\"771\">27</sup> — \"ודברת בם, עשה אותן קבע ואל תעשם עראי\". וצריך ביאור: מאי קמ\"ל רבי אחא, הלא זו משנה מפורשת<sup data-n=\"772\">28</sup> \"שמאי אומר עשה תורתך קבע\"?\nויש לומר הביאור בזה:\nעיקר כוונת המשנה היא בנוגע לקביעות בזמן<sup data-n=\"773\">29</sup> וביחס למלאכה, שרוב היום צריך האדם להקדיש ללימוד התורה ולא למלאכה. וזהו \"תורתך קבע\", שמלאכת האדם צ\"ל \"עראי\", וכלשון הרמב\"ם<sup data-n=\"774\">30</sup> \"עשה תורתך קבע ומלאכתך עראי\";\nאמנם חידושו של ר\"א הוא: \"עשה אותן קבע ואל תעשם עראי\", הדגשת השלילה אינה ביחס למלאכה אלא בנוגע לדברי תורה עצמם — שאין לעשות דברי תורה ענין של \"עראי\"<sup data-n=\"775\">31</sup>. והיינו, כי",[["769","25","היינו שהדגשת רש\"י \"מכאן\" אינה משום שיש קס\"ד ללמוד ממק\"א, אלא להדגיש שדבר זה נרמז כאן דוקא, ולא לעיל במקומו."],["770","26","ואתחנן ו, ז."],["771","27","יומא יט, ב. ועד\"ז בספרי (ורש\"י) ואתחנן שם (לא בשם ר\"א)."],["772","28","אבות פ\"א מט\"ו."],["773","29","ראה רש\"י (ועוד) אבות שם. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171347\" data-slug=\"likkutei-sichot\" data-id=\"1300171347\">לקו\"ש חי\"ז ע' 347</a> ואילך ובהערות שם."],["774","30","הל' ת\"ת פ\"ג ה\"ז. וכן בטושו\"ע (ואדה\"ז) או\"ח ר\"ס קנו. הל' ת\"ת לאדה\"ז פ\"ג ס\"ב. — וראה ברכות לה, ב. אדר\"נ ספכ\"ח. ועוד."],["775","31","אלא שבהל' ת\"ת לאדה\"ז שם: ודברת בם. . שתעשם עיקר ולא טפלה ועל כן חייב לעשות תורתו קבע ומלאכתו עראי [ולאידך — ראה אדר\"נ (פי\"ג, ב): עשה תורתך קבע כיצד. . שאם שמע אדם דבר מפי חכם. . אל יעשה אותו עראי אלא יעשה אותו קבע]. ואכ\"מ."]]],[1301410158,"יש והאדם עוסק זמן רב בלימוד התורה, אבל התורה שהוא לומד היא אצלו \"עראי\", שעניני' אינם נקבעים בנפשו, ועד ששוכח עליהם במהרה. וזהו מה שמשמיענו ר\"א \"עשה אותן קבע ואל תעשם עראי\", שלימוד ד\"ת צ\"ל באופן שיהיו נקבעים במוחו של האדם, עי\"ז שלומד ומשנן כל דבר הלכה כמה פעמים עד שמבינו על בוריו ונקבע במוחו וזוכרו היטב כו'<sup data-n=\"776\">32</sup>.\nומזה מובן, שלשיטת ר\"א לא קשה מדוע ניתנו הרבה גופי תורה ברמיזה — כי לשיטתו, שיש חיוב ללמוד דברי תורה באופן של \"קבע\", די ברמיזה, כי ע\"י הלימוד והשינון בקביעות פעם אחר פעם בודאי ישיגם ויבינם על בורים ויכוין את ההלכה לאמיתתה של תורה<sup data-n=\"777\">33</sup> (משא\"כ כשיהיו דברי תורה — אף שלא ברמיזה — וילמדם עראי).\nו. אמנם ע\"פ הנ\"ל, ש\"פרשה של אליעזר כפולה\" כדי להורות על גודל החביבות שב\"שיחתן של עבדי אבות\" — אינו מובן לאידך גיסא: מדוע לא הוכפל גם פרט זה, הנס של קפיצת הדרך, ולא עוד אלא ש\"לא ניתן אלא ברמיזה\" (ביתור לישנא דקרא)?\nע\"ד הפשט אין זו קושיא, כי לבד זאת שאם הי' נכפל גם פרט זה, שוב לא הי' ניתן לדייק בטעם הכפלת הפרשה (כנ\"ל, שכל השאלה מתעוררת דוקא כאשר רואים שהכתוב מדייק להודיע פרט זה רק פעם אחת במקום שנוגע) — הנה עוד זאת: כשם שב\"גופי תורה\" ש\"לא ניתנו אלא ברמיזה\", אין הפירוש שכל גופי תורה ניתנו ברמיזה, אלא רק (כדיוק לשון רש\"י) \"הרבה גופי תורה\", ויש הרבה שאכן נאמרו בפירוש, וגם הוכפלו (וכמובן, שאין קושיא בלימוד ע\"ד הפשט מדוע אלה נתפרשו ואלה ניתנו ברמיזה) — כמו\"כ לאידך, ב\"שיחתן של עבדי אבות\", שאין הכוונה שהכתוב נחית לכפול כל הפרטים של \"פרשה של אליעזר\", כי אף הכפלת רובה של הפרשה די' להדגיש את החביבות שב\"שיחתן של עבדי אבות\" (וגם בזה אין קושיא בלימוד ע\"ד הפשט מדוע נבחרו פרטים אלה דוקא).\nאבל בפנימיות הענין יש מקום לדייק, מדוע דוקא נס זה שבפרשת אליעזר, שהוא הנס הכי גלוי בפרשה זו — לא זו בלבד שלא נכפל בתורה, אלא עוד זאת, ש\"לא ניתן אלא ברמיזה\" (ביתור לישנא דקרא)!\nויש לבאר טעם הדבר, משום שהנס ד\"קפצה לו הארץ\" שייך במיוחד ל\"תורתן של בנים\", ולכן בא ברמיזה דוקא.\nז. ויובן זה בהקדם משנ\"ת במק\"א<sup data-n=\"778\">34</sup> הטעם (הפנימי) בזה שגופי תורה לא ניתנו אלא ברמיזה, ע\"פ המבואר בכתבי הצ\"צ פרשתנו<sup data-n=\"779\">35</sup>, שישנו ענין ה\"שיחה\" גם למעלה כביכול, והוא דיבורו ית', שבו נברא העולם (\"בעשרה מאמרות נברא העולם\"<sup data-n=\"780\">36</sup>) וכמאמר<sup data-n=\"781\">37</sup> \"הוא שח ויהי\".\nוההבדל למעלה בין \"שיחה\" לתורה",[["776","32","ראה בארוכה הל' ת\"ת לאדה\"ז פ\"ב ס\"ג ואילך."],["777","33","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161476\" data-slug=\"likkutei-sichot\" data-id=\"1300161476\">לקו\"ש חט\"ז (ע' 463</a>) שממאמר זה של ר\"א (\"עשה אותן קבע\") יש ללמוד שיתכן שתהי' מעלה ב\"שיחה\" לגבי \"תורה\". ע\"ש."],["778","34","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201343\" data-slug=\"likkutei-sichot\" data-id=\"1300201343\">לקו\"ש ח\"כ ע' 330</a> ואילך."],["779","35","אוה\"ת קכט, סע\"א ואילך."],["780","36","אבות רפ\"ה."],["781","37","פיוט אתה הוא אלקינו (שחרית דימים נוראים)."]]],[1301410159,"הוא:\n\"שיחה\" מורה על מה שהקב\"ה משפיל כביכול ומצמצם את עצמו בעשרה מאמרות לברוא על ידם את העולם ולהחיותו, ומזה באה ההנהגה הטבעית;\nמשא\"כ תורה היא למעלה מן העולם, כמחז\"ל<sup data-n=\"782\">38</sup> שתורה קדמה לעולם, וממנה נמשכת ההנהגה הנסית של הקב\"ה לשדד מערכות הטבע [וכדיוק הלשון<sup data-n=\"783\">39</sup> \"אין כל חדש תחת השמש\", דרק \"תחת השמש\" אא\"פ להיות חידוש במעשה בראשית, משא\"כ ע\"י התורה, שהיא \"לעילא מן שמשא\"<sup data-n=\"784\">40</sup>, יכולים לעשות חידוש במעשה בראשית<sup data-n=\"785\">41</sup>], \"ולכן<sup data-n=\"786\">42</sup> התנאים ואמוראים היו עושים נסים מופלאים כמו גינאי<sup data-n=\"787\">43</sup> חלוק לי נהרא, וזוטרא<sup data-n=\"788\">44</sup> דבכו מחי' מתים\" — שזהו בכח התורה שלהם.\nוזהו הטעם שהרבה גופי תורה לא ניתנו אלא ברמיזה — כי<sup data-n=\"789\">45</sup> מכיון שהתורה ענינה להמשיך \"אור חדש\" שלמעלה מן העולם, לכן לא ניתנה למטה אלא ברמיזה דוקא, ע\"ד \"(די) לחכימא ברמיזא\"<sup data-n=\"790\">46</sup>, שענין עמוק ביותר נמסר ע\"י רמז דוקא<sup data-n=\"791\">47</sup>.\nועד\"ז מובן גם בעניננו, שהנס דקפיצת הדרך של אליעזר — שהי' באופן של שידוד מערכות הטבע, לא נתפרש בתורה (באריכות) אלא \"ברמיזה\" דוקא, כמו \"גופי תורה\" [משא\"כ שאר כל פרטי הסיפור של אליעזר המפורשים בתורה באריכות, אף שמהם נראה בעליל שהשם הצליח דרכו באופן ש\"אותה הוכחת לעבדך ליצחק\"<sup data-n=\"792\">48</sup>, מ\"מ, לא הי' בהם ענין של שידוד מערכות הטבע].\nויש לומר הטעם שב\"פרשה של אליעזר\" (\"שיחתן של עבדי אבות\") נכלל גם הנס דקפיצת הדרך השייך ל\"תורתן של בנים\": מבואר בכ\"מ<sup data-n=\"793\">49</sup> הטעם לגודל החביבות שב\"פרשה של אליעזר\" עד ש\"יפה כו' מתורתן של בנים\" — כי שליחותו של אליעזר בענין נישואי יצחק ורבקה היתה שייכת לכללות ענין נתינת התורה [וכנרמז גם בנתינת \"שני צמידים. . עשרה זהב משקלם\"<sup data-n=\"794\">50</sup> לרבקה, וכפרש\"י<sup data-n=\"795\">51</sup> שהם \"רמז לשני לוחות. . לעשרת הדברות\"]; שמזה מובן שגם ב\"פרשה של אליעזר\" עצמה צ\"ל מעין ה\"אור חדש\" שלמעלה מטבע העולם, המתגלה על ידי התורה — וזה הי' בנס דקפיצת הדרך<sup data-n=\"796\">52</sup>.",[["782","38","ב\"ר בתחלתה. ובכ\"מ."],["783","39","קהלת א, ט."],["784","40","זח\"א רכג, סע\"ב. וראה שבת ל, ב וברש\"י שם. פרש\"י קהלת שם. ועוד."],["785","41","אוה\"ת פרשתנו קכט, ב. ועוד."],["786","42","אוה\"ת שם. ומציין ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע (כג, א</a>). וראה מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תמג ואילך (ובהנסמן שם). שם ס\"ע תנו ואילך. ועוד."],["787","43","חולין ז, א. ושם (וכן בלקו\"ת שם): חלוק לי מימיך."],["788","44","ע\"ז י, ב."],["789","45","וראה אוה\"ת פרשתנו קכח, סע\"ב ואילך. קלג, ב."],["790","46","זח\"א כו, ב (ועוד) — הובא בלקו\"ת ויקרא ה, ריש ע\"ב (לענין תגין שבתורה), שצויין באוה\"ת פרשתנו שם (קלג, ב)."],["791","47","ומ\"מ יש מעלה ב\"שיחה\" לגבי \"תורה\" — כי תכלית הכוונה היא לתקן העולם כפי שנשאר בגדריו הטבעיים כו', כמשנ\"ת בארוכה בלקו\"ש ח\"כ שם.\n[באוה\"ת פרשתנו שם (קל, א ואילך) מבאר בארוכה המעלה שבשיחתן של עבדי אבות (שהיא למעלה מתורה, ואדרבה, זהו שורש כל התורה כולה. ע\"ש. וראה הנסמן בהערה 49); והמבואר בלקו\"ש שם, הוא המעלה שב\"שיחה\" עצמה לגבי \"תורה\". ע\"ש]."],["792","48","פרשתנו כד, יד. וכן שם, מד."],["793","49","מאמרי אדה\"ז — תקס\"ג ח\"א (ע' לו ואילך). תו\"ח פרשתנו קלה, א ואילך. אוה\"ת פרשתנו קכז, ב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381113\" data-slug=\"likkutei-torah\" data-id=\"4001381113\">לקו\"ת ברכה צו, סע\"ג</a> ואילך. ובכ\"מ."],["794","50","כד, כב."],["795","51","עה\"פ. וכ\"ה בתיב\"ע עה\"פ. ב\"ר פ\"ס, ו."],["796","52","וי\"ל הטעם דנס זה דוקא — כי \"קפיצת הדרך\" מרמז על כללות ענין הנסים, קפיצת דרך סדר ההשתלשלות, שההשפעה דלמעלה נמשכת למטה בלי עיכובים כו' בפרטי הדרגות דס' השתלשלות, ולכן יוצא מזה שידוד מערכות הטבע (ע\"ד המבואר (לקו\"ת ס\"פ קרח. ובכ\"מ) גבי המעלה שבברכת כהנים)."]]],[1301410160,"ח. ויש לקשר זה עם פירוש הבעש\"ט<sup data-n=\"797\">53</sup> עה\"פ, וז\"ל: \"מפסוק ואבוא היום אל העין יצא שם של קפיצת הארץ\", ומבואר בס' עבודת ישראל<sup data-n=\"798\">54</sup> (להמגיד מקאזניץ) ד\"זהו פירוש (לשון רש\"י) היום יצאתי והיום באתי מכאן שקפצה, פירוש מכאן גופא, מדברים אלה שבזה המאמר\", ד\"מפסוק זה גופא יוצא שם לקפיצת הארץ\"<sup data-n=\"799\">55</sup>.\nוע\"פ משנת\"ל שהנס דקפיצת הדרך שייך ל\"תורתן של בנים\", י\"ל, שלכן נרמז השם של קפיצת הארץ בפסוק זה דוקא (ולא לעיל בפסוק \"ויקם וילך\") — כי במ\"ש \"ואבא היום אל העין\" נרמז ענין התורה, כמבואר בזהר<sup data-n=\"800\">56</sup> ד\"עין המים\" שבסיפור זה רומז למעיין החכמה, מקור התורה, \"וז\"ש<sup data-n=\"801\">57</sup> ותרד העינה<sup data-n=\"802\">58</sup>, שירדה לשאוב מי החכמה דתורה, בכדה שעל שכמה כו' ותמלא כדה<sup data-n=\"803\">59</sup> הן כ\"ד ספרים<sup data-n=\"804\">60</sup> דאורייתא\";\nונמצא שהפסוק \"ואבוא היום אל העין\" שייך למקור ענין התורה, ולכן מפסוק זה יוצא השם של קפיצת הארץ, הנהגה נסית שלמעלה מן הטבע.\n<span data-k=\"q\">(משיחת ש\"פ ח\"ש תשל\"ו) </span>",[["797","53","כתר שם טוב סל\"ב (בהוצאת קה\"ת)."],["798","54","פרשתנו עה\"פ. וראה גם אור הגנוז (למהרי\"ל הכהן) פרשתנו."],["799","55","וראה בהנסמן בהערה הקודמת — שעפ\"ז מובן ההמשך בפרש\"י \"אר\"א יפה שיחתן של עבדי אבות כו'\". ע\"ש."],["800","56","ראה זהר פרשתנו קלב, א. שם וישב קפב, רע\"א."],["801","57","ל' התו\"ח פרשתנו קכח, רע\"א. וראה גם שם קלד, ב. ביאוה\"ז וישב כה, אב. ובכ\"מ."],["802","58","כד, טז."],["803","59","כד, טוטז."],["804","60","ראה תקו\"ז תכ\"א (מו, ב). וראה גם שם בהקדמה (יד, א). ועוד."]]],[1301410161,"<h3>שיחה ג</h3>\nא. בהפטורת פרשתנו (בריש ספר מלכים) מסופר<sup data-n=\"805\">1</sup> ע\"ד השתלשלות הדברים שהביאו לשבועת דוד לבת שבע \"כי כאשר נשבעתי לך בה' אלקי ישראל לאמר כי שלמה בנך ימלוך אחרי והוא ישב על כסאי תחתי כי כן אעשה היום הזה\"<sup data-n=\"806\">2</sup>.\nובהמשך הכתובים<sup data-n=\"807\">3</sup> מסופר שדוד צוה לצדוק הכהן ולנתן הנביא ובניהו בן יהוידע להרכיב את \"שלמה בני על הפרדה אשר לי\" (\"סימן לו שימלוך ותחלת הגדולה שאין הדיוט רוכב על סוסו של מלך\"), \"ומשח אותו שם צדוק הכהן ונתן הנביא למלך על ישראל גו' ואמרתם יחי המלך שלמה\"<sup data-n=\"808\">4</sup>, וכן עשו בפועל בחיי דוד, וכמ\"ש בהמשך הכתובים<sup data-n=\"809\">5</sup>, ועד שיונתן בן אביתר הכהן סיפר לאדוני' איך ששלמה מלך, \"וגם ישב שלמה על כסא המלוכה\", \"וגם ככה אמר המלך ברוך ה' אלקי ישראל אשר נתן היום יושב על כסאי ועיני רואות\"<sup data-n=\"810\">6</sup>, ואדוני' ירא את המלך שלמה ואחז בקרנות המזבח שלא יהרגהו שלמה ע\"ז שמורד במלכותו<sup data-n=\"811\">7</sup>.\nומזה נראה, שמה שאמר דוד \"כי כן אעשה היום הזה\" היינו (לא רק הבטחה ששלמה ימלוך לאחרי פטירת דוד, אלא) ששלמה הוכתר למלך בחיי דוד<sup data-n=\"812\">8</sup>.\nוצריך ביאור: א) הרי אמר לו הקב\"ה לדוד<sup data-n=\"813\">9</sup> \"כבר הגיעה מלכות שלמה בנך ואין מלכות נוגעת בחברתה אפילו כמלא נימא\", דמשמע מזה שמלכות שלמה לא הותחלה עד לאחרי פטירת דוד. ב) ובכלל הרי אי אפשר לשני מלכים שישתמשו בכתר אחד<sup data-n=\"814\">10</sup> (וכמאמר<sup data-n=\"815\">11</sup> דבר אחד לדור כו'), וכנ\"ל ש\"אין מלכות נוגעת בחברתה אפילו כמלא נימא\"<sup data-n=\"816\">12</sup>?\nמצינו אכן כמה שמלכו בחיי אבותיהם (כמו יהושפט שהמליך את יורם בחייו שנתיים<sup data-n=\"817\">13</sup>, אחזיהו שמלך בחיי יהורם אביו<sup data-n=\"818\">14</sup>, עוזי' בימי אביו אמציהו<sup data-n=\"819\">15</sup>, ועוד כיו\"ב), אבל שם עברה המלוכה מהאב אל הבן, ונתבטלה מלוכת האב",[["805","1","מ\"א א, ה ואילך."],["806","2","שם, ל."],["807","3","שלכמה מנהגים אומרים גם המשך הפסוקים דמ\"א בהפטורה, משא\"כ לפי מנהגנו מסיימים (כמנהג הרמב\"ם בסדר תפלות שלו בסוף ספר אהבה. ועוד) בפסוק לא — ראה בפרטיות <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251107\" data-slug=\"likkutei-sichot\" data-id=\"1300251107\">לקו\"ש חכ\"ה ע' 107</a>. וש\"נ."],["808","4","שם, לג-לד. ובפרש\"י."],["809","5","שם, לח ואילך."],["810","6","שם, מו. מח."],["811","7","ראה שם, נ ואילך. אלא שלפועל לא נהרג (ראה מ\"א שם, נב \"ויאמר שלמה אם יהי' לבן חיל גו'\". ולהעיר ממגילה יד, ריש ע\"ב). וראה לקמן סעיף ו והערה *47."],["812","8","ראה מלבי\"ם בפסוקים הנ\"ל (מו, מח. נא. ועוד). וראה מצו\"ד שם, ל.\nולהעיר שגם דוד נמשח בחיי שאול (ש\"א טז, יג). אבל עדיין לא מלך דוד אז. וראה ש\"ב (ב, ד. ה, ג) שנמשח עוה\"פ כשקבלוהו למלך בפועל, ובשו\"ת אבני נזר דלקמן הערה 16 (אות יב) שעד אז לא הי' לו דין מלך. וראה מגילה שם \"עדיין שאול קיים כו'\". ולהעיר מגבורת ארי ליומא כב, ב. ועוד. ואכ\"מ."],["813","9","שבת ל, סע\"א."],["814","10","ראה חולין ס, ב. פרש\"י בראשית א, טז. ועוד."],["815","11","סנהדרין ח, א. רש\"י וילך לא, ז."],["816","12","ראה חכמת מנוח לשבת שם."],["817","13","פרש\"י מ\"ב ח, טז."],["818","14","פרש\"י שם ט, כט."],["819","15","פרש\"י שם יד, כב; טו, ח."]]],[1301410162,"(כיון שלא הי' ראוי למלוך מחמת חולי וכיו\"ב), וכמבואר במפרשים<sup data-n=\"820\">16</sup>, שהוא ע\"ד מ\"ש בתשובת הרשב\"א<sup data-n=\"821\">17</sup> (והובא ברמ\"א<sup data-n=\"822\">18</sup>) ב\"ש\"ץ שהזקין ורוצה למנות בנו לסייעו לפרקים. . שאם ממלא מקומו בשאר דברים בנו קודם לכל אדם\", ועד\"ז הוא לענין ירושת המלוכה, דכאשר אין האב יכול למלוך מאיזו סיבה זוכה הבן במלוכה בתורת ירושה (בחיי האב); משא\"כ בנדו\"ד, אף שהי' זה בעת ש\"המלך דוד זקן\"<sup data-n=\"823\">19</sup>, מפורש בדברי הימים<sup data-n=\"824\">20</sup> שדוד מלך בפועל גם אחרי שנמשח שלמה למלך<sup data-n=\"825\">21</sup>.\nואין זה דומה להזמן שברח דוד מפני אבשלום בנו (באמצע ימי מלכותו), ואיתא בירושלמי<sup data-n=\"826\">22</sup> ד\"אותן ששה חדשים שהי' דוד בורח מפני אבשלום בשעירה הי' מתכפר כהדיוט\", שהרי זה הי' בעל כרחו (מחמת בריחתו מפני אבשלום), אבל אין מסתבר שיעביר המלוכה מידו ברצונו בחייו.\nובפרט שי\"א<sup data-n=\"827\">23</sup>, שגם באותן ששת החדשים הי' לו דין מלך<sup data-n=\"828\">24</sup>, אלא שבנוגע לשעיר יש דין מיוחד שאינו אלא במי \"שאין על גביו אלא ה' אלקיו\"<sup data-n=\"829\">25</sup>, וכיון שדוד הי' אז נרדף והי' ירא מפני אבשלום לא מקרי \"אין על גביו אלא ה' אלקיו\" בפועל.\nופשיטא שאין זה דומה כלל להא שמצינו מלכי בית דוד ומלכי ישראל בזמן אחד, ולדעת הרמב\"ם<sup data-n=\"830\">26</sup> \"נביא שהעמיד מלך משאר שבטי ישראל כו' הרי זה מלך וכל מצות המלכות נוהגות בו\" — כי שם שני המלכים הם בשני מקומות שונים, זה ביהודה וזה בישראל [נוסף על החילוק בסוג המלוכה שזה ממלכי בית דוד וזה ממלכי ישראל, ששונים במהותם, כדלקמן בארוכה].\nב. לכאורה הי' אפשר לבאר זה, ע\"פ דברי הגמ'<sup data-n=\"831\">27</sup> \"עתיד הקב\"ה להעמיד להם דוד אחר שנאמר<sup data-n=\"832\">28</sup> ועבדו את ה\"א ואת דוד מלכם אשר אקים להם, הקים לא נאמר אלא אקים א\"ל ר\"פ לאביי והכתיב<sup data-n=\"833\">29</sup> ודוד עבדי נשיא להם לעולם כגון קיסר ופלגי קיסר\", \"מלך ושני לו כן דוד החדש מלך כדכתיב ודוד מלכם אשר אקים ודוד המלך שני לו כדכתיב נשיא להם ולא כתוב מלך\" (פרש\"י)<sup data-n=\"834\">30</sup>. שמזה מובן, שגם במלכות בית דוד עצמה, יש אפשרות של שני גדרים במלכות,",[["820","16","ראה שו\"ת דברי נחמי' אה\"ע סמ\"ח בסופו. שו\"ת אבני נזר יו\"ד סשי\"ב אות פה ואילך (וע\"ש אות פז הראי' מיותם בן עוזי' ע\"פ הוריות י, א). וראה צפע\"נ להוריות יא, ב ד\"ה התם שבט."],["821","17","ח\"א סי' ש."],["822","18","או\"ח סנ\"ג סכ\"ה."],["823","19","מ\"א בתחלתו."],["824","20","דה\"א קאפיטל כחכט. וראה אברבנאל למלכים כאן."],["825","21","ראה מלבי\"ם שם כט, כוכח. ולכאורה גם זה ד\"וימליכו שנית לשלמה בן דויד וימשחו לה' לנגיד\" (דה\"א שם, כב), שנמלך לא רק ע\"י אנשי ירושלים, הי' גם בחיי דוד (ראה רד\"ק עה\"פ. אברבנאל כאן)."],["826","22","ר\"ה פ\"א ה\"א. הוריות פ\"ג ה\"ב."],["827","23","ראה שו\"ת אבני נזר שם בהגהה לאות כז. ועוד. אבל ראה מאירי הוריות יא, סע\"א. פרשת דרכים דרוש יא בסופו. ועוד."],["828","24","שלכן שמעי שקללו אז הי' לו דין מורד במלכות וחייב מיתה — ראה ש\"ב יט, כב. מ\"א ב, ח. שם, לו ואילך (ובמפרשים שם). צפע\"נ להוריות י, א ד\"ה פרט. אבל להעיר מרש\"י ש\"ב יט, כג."],["829","25","משנה הוריות י, א. וראה רמב\"ם הל' שגגות פט\"ו ה\"ו."],["830","26","הל' מלכים פ\"א ה\"ח."],["831","27","סנהדרין צח, סע\"ב."],["832","28","ירמי' ל, ט."],["833","29","יחזקאל לז, כה."],["834","30","וראה ראב\"ד שם ספ\"א. צפע\"נ עה\"ת ויחי מט, ט. לקו\"ש חל\"ה ע' 206 ואילך."]]],[1301410163,"קיסר ופלגי קיסר, ולפ\"ז אפשר לומר מעין זה גם בתחלת מלכות בית דוד, במלכות שלמה ודוד, ששניהם היו מלכים, אלא שהם ע\"ד קיסר ופלגי קיסר.\nאבל גם זה דוחק, כי פשוט ששני \"מלכים\" אלו אינם שוים בתוקף מלכותם, וכלשון הגמ' \"ופלגי קיסר\" (חצי קיסר), \"ושני לו\", ולא מצינו שבאותו הזמן הי' אחד משניהם (דוד או שלמה) באופן ד\"שני לו\".\nג. ויש לומר בזה, בהקדם ביאור דברי הרמב\"ם בנוגע לירושת המלכות, וז\"ל<sup data-n=\"835\">31</sup>: \"מאחר שמושחין המלך הרי זה זוכה לו ולבניו עד עולם שהמלכות ירושה שנאמר<sup data-n=\"836\">32</sup> למען יאריך ימים על ממלכתו הוא ובניו בקרב ישראל. . ולא המלכות בלבד אלא כל השררות וכל המינויין שבישראל ירושה לבנו ולבן בנו עד עולם, והוא שיהי' הבן ממלא מקום אבותיו בחכמה וביראה\", ואח\"כ ממשיך הרמב\"ם בנוגע למלכות בית דוד \"כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו הזכרים עד עולם שנאמר<sup data-n=\"837\">33</sup> כסאך יהי' נכון עד עולם ולא זכה אלא לכשרים כו' אע\"פ שלא זכה אלא לכשרים לא תכרת המלוכה מזרע דוד לעולם, הקב\"ה הבטיחו בכך כו'\".\nולכאורה דברי הרמב\"ם צריכים ביאור: מאי קמ\"ל הרמב\"ם באריכות דבריו אודות מלכות דוד, \"כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו הזכרים עד עולם כו' ולא זכה אלא לכשרים כו'\" — הרי הן הן הדברים שכתב לעיל בנוגע לכל מלך (ולא רק מלכות אלא כל שררה ומינוי שבישראל), ומהו החידוש בדוד המלך לגבי שאר המלכים?\nלכאורה יש לומר, דאף ש\"המלכות ירושה\", מ\"מ אפשר להיות שהמלכות תפסק מזרעו כי לא יהי' לו בן הראוי למלא מקום אבותיו בחכמה וביראה, וזהו החידוש במלכות בית דוד, שהקב\"ה הבטיחו ש\"לא תכרת המלוכה מזרע דוד לעולם\", משא\"כ בשאר מלכים (וכן בשאר שררות), שאף שהיא ירושה, אין הכרח והבטחה שלא תפסק מזרעו.\nאבל קשה לומר שזו בלבד היא כוונת הרמב\"ם — שהרי תוכן ענין זה כותב הרמב\"ם בהמשך הפרק<sup data-n=\"838\">34</sup>, וז\"ל \"מלכי בית דוד הם העומדים לעולם שנאמר כסאך יהי' נכון עד עולם אבל אם יעמוד מלך משאר ישראל תפסק המלכות מביתו\", ואמאי הכפיל את דבריו עוה\"פ אודות הבטחה זו לדוד, שמלכותו תכון לעולם?\nועוד זאת: מזה שהרמב\"ם כייל הך ענין ש\"לא תכרת המלוכה מזרע דוד לעולם\" עם פרטי דיני ירושת המלכות, משמע, שאין זה ענין צדדי (שהקב\"ה הבטיחו שבפועל תכון מלכותו לעולם), אלא זה נוגע לעצם גדר ירושת המלכות אצל מלכי בית דוד. והיינו שיש חילוק עיקרי בין ירושת מלכות בית דוד לירושת המלכות בשאר מלכים (ושאר עניני שררה ומינויין שבישראל).\nונת' בזה במ\"א<sup data-n=\"839\">35</sup> ע\"פ דיוק לשון הרמב\"ם \"כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו הזכרים עד עולם\", והיינו שדוד זכה לא רק",[["835","31","הל' מלכים שם ה\"ז."],["836","32","שופטים יז, כ."],["837","33","ש\"ב ז, טז."],["838","34","בה\"ט."],["839","35","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281109\" data-slug=\"likkutei-sichot\" data-id=\"1300281109\">לקו\"ש חכ\"ח ע' 109</a> ואילך. וש\"נ."]]],[1301410164,"ל\"מלכות\" אלא ל\"כתר מלכות\", ש\"כתר מלכות\" לא נמצא אלא במלכי בית דוד בלבד. ועד\"ז כותב הרמב\"ם אח\"כ<sup data-n=\"840\">36</sup> \"נביא שהעמיד מלך משאר שבטי ישראל כו' ה\"ז מלך וכל מצות המלכות נוהגות בו אע\"פ שעיקר המלכות לדוד כו'\" — הרי שאף שחלים כל דיני המלך על המלך משאר שבטי ישראל, מ\"מ אין בו \"עיקר המלכות\" שזה שייך לזרע דוד בלבד.\nולכן כותב הרמב\"ם בספר המצות<sup data-n=\"841\">37</sup> שכל מלך שאינו מ\"זה הזרע הנכבד, לענין מלכות נכרי קרינא בי' כמו שכל זרע אחר בלתי זרע אהרן לענין עבודה זר קרינא בי'\" — כי מלכות בית דוד היא חפצא אחרת בענין המלוכה.\nד. וההסברה בזה:\nענין המלכות יכול להיות בשני אופנים: א) התפקיד של מלוכה, שהן הפעולות והנהגות המלוכה (בלשון הכתוב<sup data-n=\"842\">38</sup> \"אשר יצא. . ואשר יבא לפניהם\", וכן הפרטים שביארם שמואל הנביא<sup data-n=\"843\">39</sup>). ב) מלך בעצם<sup data-n=\"844\">40</sup>, היינו שהוא איש מנושא בעצם (ובדרך ממילא הוא מתנהג כמלך).\nוזהו הענין ד\"כתר מלכות\" שזכה בו דוד, \"לו ולבניו הזכרים עד עולם\" — לא רק שהם ימלכו בפועל, אלא שהם יהיו מלכים בעצם. והוא \"עיקר המלכות\" השייך לזרע דוד בלבד, כי אינו רק הנהגת המלוכה, אלא ההתנשאות שבנפש, שניתן בדוד וזרעו עד עולם.\nועפ\"ז מובן קשר הדברים ברמב\"ם, שבהמשך לדיני ירושת המלכות (ושאר שררות ומינויין שבישראל), כותב ע\"ד ירושת מלכות בית דוד, ומדייק שהיא באופן ש\"לא תכרת המלוכה מזרע דוד לעולם\" — שאין זו הבטחה צדדית, אלא ענין המוכרח מצד עצם גדר דמלכות בית דוד:\nכאשר המלוכה היא רק באופן של מינוי למילוי תפקיד, הרי זה דבר נוסף על מציאות האדם, ובמילא שייך בזה הפסק; משא\"כ במלכות בית דוד, ה\"ז שהם מלכים בעצם, זה נעשה מהותם ועיקרם, שכח המלוכה וההתנשאות מוטבע בעצם נפשם, ובמילא אין שייך בזה הפסק, והוא עובר בדרך ממילא מאב לבנו.\nה. ע\"פ כל הנ\"ל מובן, שיש חילוק יסודי בגדר ירושת המלכות בין מלכי בית דוד ושאר מלכים (וכן כל השררות והמינויין) שבישראל:\nבשאר מלכים שאינו אלא ירושת תפקיד ה\"ז דומה לכל ירושת נחלה, שהמוריש יש לו \"בעלות\" על תפקיד פלוני (ע\"ד שאר רכושו ונכסיו שהוא הבעלים עליהם), שהוא מוריש לבניו (וכהדגשת הרמב\"ם כאן<sup data-n=\"845\">41</sup> \"כל הקודם בנחלה קודם לירושת המלוכה\");\nמשא\"כ אצל מלכות בית דוד אין זו כמו ירושת נכס, אלא הוא ענין הבא בדרך ממילא, שע\"י ש\"זכה דוד בכתר מלכות\", \"הרי המלכות לו ולבניו הזכרים עד עולם\", שבדרך ממילא נטבע בהם כח המלוכה עד עולם.\n[ועפ\"ז י\"ל, דמ\"ש הרמב\"ם<sup data-n=\"845\">41</sup> בנוגע למלכי בית דוד \"ולא זכה אלא לכשרים\" אינו ענין לתנאי ירושת המלכות",[["840","36","ה\"ח."],["841","37","מל\"ת שס\"ב. וראה השקו\"ט בביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג ח\"ג פרשה ז (קיח, ג). ואכ\"מ."],["842","38","פינחס כז, יז ובספרי (ורש\"י) שם."],["843","39","ש\"א ח, יא ואילך. רמב\"ם הל' מלכים ספ\"ד."],["844","40","ראה המשך תער\"ב פקכ\"ב. ובכ\"מ."],["845","41","בה\"ז שם."],["845","41","בה\"ז שם."]]],[1301410165,"שכתב לפנ\"ז \"והוא שיהי' הבן ממלא מקום אבותיו בחכמה וביראה\" — אלא הם שני דברים שונים: התנאי ד\"ממלא מקום אבותיו בחכמה וביראה\" נוגע לירושת תפקיד המלוכה, דרק מי שיש בו חכמה ויראה יכול להנהיג המלוכה כראוי; אבל כוונת הרמב\"ם \"ולא זכה אלא לכשרים\" היא לענין ירושת \"כתר מלכות\", שכח המלוכה המיוחד למלכי בית דוד אינו עובר אלא לזרעו הכשרים, ולא לזרעו שאינם כשרים, שהם אינם זוכים בכתר מלכות (\"שלא זכה אלא לכשרים\")].\nו. והנה ע\"פ הנ\"ל נחתינן לעוד הפרש יסודי בין מלכי ישראל ומלכי בית דוד — בנוגע למצב הבן בחיי האב:\nאצל שאר מלכים (וכל השררות) שגדר מלכותם אינו אלא התפקיד דמלוכה, מובן, שכל זמן שהאב חי וקיים, א\"א שיחול על הבן שום גדר של מלכות (כ\"ז שאביו עדיין מולך), כי תפקיד המלוכה לא יתכן אלא לאחד. וגם אם הוא בן הראוי למלא מקום אבותיו — הרי כל זמן שאביו מולך אין להבן כלום בענין המלכות (כמו בירושת נכסים, שכ\"ז שהמוריש בחיים אין להבן שום בעלות על נכסי האב), והוא רק בגדר ראוי ליורשו<sup data-n=\"847\">42</sup>.\nמשא\"כ אצל מלכי בית דוד, כיון שיש אצלם כתר מלכות, שכח המלוכה מוטבע בעצם נפשם, הרי זהו ענין הקיים גם בחיי אביו<sup data-n=\"848\">43</sup>.\nועפ\"ז י\"ל שזו היתה פעולתו של דוד בהמליכו את שלמה בחייו:\nאע\"פ שזכה שלמה בכתר מלכות תיכף משנולד, להיותו זרע כשר, והי' לו כח המלוכה בעצם, מ\"מ, כל זמן שדוד הי' בחיים ומלך בפועל, הרי כח המלוכה של שלמה הוא רק \"בכח\" ולא \"בפועל\", כי אין הכרח שימלוך בפועל [דלא מיבעי אצל שלמה שהיו לו עוד אחים ואין וודאות שהוא יהי' המלך, אלא גם אם הי' מדובר בבן יחיד, הרי אפשר שימות בן בחיי האב ולעולם לא ימלוך בפועל];\nאבל על ידי בחירת דוד בשלמה בנו וציוויו למושחו, חל עי\"ז על שלמה שם מלך, היינו לא רק שעתיד הוא לירש את המלוכה מדוד, אלא יש עליו שם מלך בפועל (כיון שזכה ב\"כתר מלכות\").\nואין זו סתירה להכלל שאין שני מלכים משתמשים בכתר אחד — כי הדיוק בזה הוא \"משתמשים בכתר אחד\", דהיינו הנהגת המלוכה בפועל, שזה אינו שייך להיות על ידי שנים בבת אחת (ובפרט שאין דיעותיהן שוות וכו'<sup data-n=\"849\">44</sup>), ואין מלכות אחת נוגעת בחברתה אפילו כמלא נימא; אבל עצם שם מלך, שתלוי ב\"כתר מלכות\" וכח המלוכה שניתן לדוד ולזרעו עד עולם, אפשר לחול על שנים בזמן אחד.\n[ובעומק יותר יש לומר, ש\"שם מלך\" החל על שלמה אינו בסתירה לשם מלך דדוד — כי היינו הך, ד\"כתר מלכות\" של שלמה אינו אלא \"כתר מלכות\" של דוד (וכן בכל מלכי בית דוד, ש\"כתר מלכות\"",[["847","42","אלא שבזה שינוי בין ירושת נחלה לירושת שררה (ראה בהנסמן בהערה 16), שירושת נחלה היא רק לאחר מיתה, וירושת שררה אפשרית גם בחיים, שממלא מקום אבותיו בשררה זו."],["848","43","וי\"ל שגם בשאר מלכי בית דוד הנ\"ל (ס\"א) לא נפקעה המלוכה מהאב כשנעשה הבן מלך, משא\"כ במלכי ישראל, דכאשר הבן ירש המלוכה בחיי האב נפקעה לגמרי מהאב. וראה צפע\"נ להוריות י, א ד\"ה פרט."],["849","44","ראה סנהדרין לח, א. ספרי (ורש\"י) פינחס כז, יח. ועוד. ובמילא אין גדר שררה והנהגת המלוכה של א' שווה לחבירו."]]],[1301410166,"שלהם הוא אותו הכתר, וכמרומז בחז\"ל<sup data-n=\"850\">45</sup> שהסימן למלכי בית דוד הוא שכתר דוד \"הולמתו\"), כי כתר מלכות של מלכי בית דוד הוא עצם אחד, וי\"ל שהוא עצם כח המלוכה, שלמעלה מהתחלקות].\nוכן בעניננו, שהנהגת המלוכה היתה בפועל (רק) על ידי דוד<sup data-n=\"851\">46</sup> (ואם מצינו ענינים של הנהגת המלכות אצל שלמה בחיי דוד, אין זה אלא בשליחותו של דוד אביו<sup data-n=\"852\">47</sup>, ולא כמלכות נפרדת)<sup data-n=\"853\">*47</sup>; אבל מ\"מ חל שם מלך על שלמה בחיי דוד (לאחרי שנמשח<sup data-n=\"854\">48</sup>), כיון שיש אצלו \"כתר מלכות\".\nז. ויש להוסיף ביאור בזה שמצינו ענין כזה — מלך בחיי האב (כשלא נפקע המלכות מן האב) — רק אצל דוד ושלמה:\nידועים דברי הרמב\"ם<sup data-n=\"855\">49</sup> \"אין מלך למי שמאמין תורת משה רבינו אלא מזרע דוד ומזרע שלמה דוקא\" (והוא בכלל העיקר הי\"ב מהי\"ג עיקרים<sup data-n=\"856\">50</sup>). ובזה מתורץ לשון הגמ'<sup data-n=\"857\">51</sup> \"דוד ושלמה שנמשחו בקרן נמשכה מלכותן\", דלכאורה איך מתאים להוסיף \"ושלמה\" (כאילו זוהי מלכות נפרדת), והרי מלכות שלמה היתה ירושה דמלכות דוד (ומשיחת שלמה היתה רק \"לסלק המחלוקת\" מפני אדוני')? אלא משום שמלכות שלמה (ומשיחתו) יש בה גם התחלת ענין חדש, כי הנצחיות דמלכות בית דוד \"עד עולם\" נפעלת דוקא ע\"י דוד ושלמה יחד<sup data-n=\"858\">52</sup>.\nועפ\"ז יש לומר, שמטעם זה היו שניהם מלכים בזמן אחד<sup data-n=\"859\">53</sup>, כי בזמן זה בא לידי ביטוי ענין זה שבמלכותם, שבגלל שניהם היא מלכות נצחית.\n<span data-k=\"q\">(משיחות י\"ב וט\"ו תמוז תשמ\"ה) </span>",[["850","45","ע\"ז מד, סע\"א. וראה גם סנהדרין כא, ב ובפרש\"י. וראה הנסמן בהערה 40."],["851","46","כדמוכח בדה\"א כחכט, כנ\"ל."],["852","47","אבל שליחות זו אינה אפשרית בכל אדם, אלא מי שהוא \"כמותו\" דהמשלח, היינו מלך כמותו, כמו שלמה שהי' מלך כמותו ד\"דוד\". וכמו שבשליחות בכלל צריך השליח (לכל לראש) להיות כמותו דהמשלח, וחש\"ו לאו בני שליחות נינהו, כמשנ\"ת במק\"א."],["853","*47","וי\"ל שלכן לא נהרג אדוני' מדין מורד במלך (ראה לעיל הערה 7). ואכ\"מ."],["854","48","שלדעת הרמב\"ם הוצרך לזה בנוגע לשלמה לסלק המחלוקת (הל' כלי המקדש פ\"א הי\"א. הל' מלכים ספ\"א)."],["855","49","סהמ\"צ שבהערה 37 — ע\"פ הוצאת קאפח (ועד\"ז בהוצאת העליר). ולפנינו — בשינוי קצת."],["856","50","ברמב\"ם פיהמ\"ש פ' חלק."],["857","51","מגילה יד, א. וש\"נ."],["858","52","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251108\" data-slug=\"likkutei-sichot\" data-id=\"1300251108\">לקו\"ש חכ\"ה ע' 108</a> ואילך."],["859","53","להעיר מזה שאמרו (זח\"א קנו, רע\"א. רכה, סע\"ב. ועוד) דבזמן שלמה קיימא סיהרא באשלמותא (וראה גם שמו\"ר פט\"ו, כו), והרי זה שייך בין לדוד (דור י\"ד) ובין לשלמה (דור ט\"ו), שהרי מילוי ושלימות הלבנה היא חצי כ\"ט י\"ב תשצ\"ג (ב\"י או\"ח סתכ\"ו) שהוא בין י\"ד לט\"ו, קודם לשלמות ט\"ו יום."]]],[1301410167,"<h3>שיחה א</h3>\nא. ואלה תולדות יצחק בן אברהם אברהם הוליד את יצחק. וביארו חז\"ל<sup data-n=\"860\">1</sup> שכפל לשון הכתוב בא ללמדנו, שנוסף על שהי' \"יצחק בן אברהם\", הי' מודגש אשר \"אברהם הוליד את יצחק\", כי הי' דומה לאברהם בקלסתר פניו — \"לפי<sup data-n=\"861\">2</sup> שהיו ליצני הדור אומרים מאבימלך נת­עברה שרה. . הקב\"ה צר קלסתר פניו של יצחק דומה לאברהם\".\nוכבר הקשו במפרשים<sup data-n=\"862\">3</sup>: ענין זה, ביטול דברי ליצני הדור \"מאבימלך נת­עברה שרה\", הי' מתאים להשמיענו ב­סמיכות לסיפור לידת יצחק<sup data-n=\"863\">4</sup> — ולמה חיכה הכתוב עד עתה — פרשת תולדות — לבטל אמירה זו?\nומשמע, דעם היות שסיבת יצירת \"קלסתר פניו של יצחק דומה לאברהם\" היתה כדי לבטל דברי ליצני הדור — זה נוגע (גם) לענין עקרי ולענין הקיים גם לאחרי ביטול דבריהם — נוגע לעצם ענינו ועבודתו של יצחק.\nולכן בא ענין זה דוקא ב(תחילת) פ' תולדות, לפי שעיקרה של פרשה זו — \"אלה\" — הוא סיפור \"תולדות יצחק\", קורותיו של יצחק<sup data-n=\"864\">5</sup>\n(בפ' חיי שרה המדובר הוא בהמשך לעניניו של אברהם; מפ' ויצא מתחיל הסיפור ע\"ד יעקב; ובפרשת תולדות הוא סיפור קורותיו של יצחק, ועד ש­אחד מהפירושים ב\"ואלה תולדות יצחק\" הוא — \"ילדי ימיו וקורותיו\"<sup data-n=\"865\">6</sup>)\nוזוהי הדגשת הכתוב, שבסיפור עניניו של יצחק (\"תולדות יצחק\") נוגע לדעת ש\"אברהם הוליד את יצחק\", שיצחק \"דומה\" לאברהם.\nב. בנוגע לענינו ועבודתו של יצחק מצינו דבר והיפוכו:\nידוע שמדתו של יצחק היא מדת היראה, \"ופחד יצחק\"<sup data-n=\"866\">7</sup>. שזהו ההפרש בין עבודתו של אברהם לשל יצחק: עבודת אברהם היא במדת האהבה והחסד, \"אברהם אוהבי\"<sup data-n=\"867\">8</sup>, ושל יצחק — במדת ה­יראה והפחד.\nאמנם לאידך — כמה ענינים ביצחק מורים על קשר ושייכות למדת האהבה והחסד:\nא) תחלתו, (זמן) לידתו: אמרו חז\"ל<sup data-n=\"868\">9</sup> \"בפסח נולד יצחק\", וידוע<sup data-n=\"869\">10</sup> אשר שלש",[["860","1","ב\"מ פז, א. תנחומא פרשתנו א. פרש\"י ריש פרשתנו."],["861","2","לשון רש\"י."],["862","3","ראה מפרשי רש\"י כאן. אלשיך ועוד כאן. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201101\" data-slug=\"likkutei-sichot\" data-id=\"1300201101\">לקו\"ש ח\"כ ע' 101</a> ואילך."],["863","4","וכפשטות לשון רש\"י שתחילת יצירתו של יצחק היתה דומה לאברהם, ודברי ליצני הדור היו רק בעת עיבורה של שרה (\"מאבימלך נתעברה שרה\"). וכן מפורש בתנחומא שם (הובא ברא\"ם כאן).\nולפי דברי הגמ' (ב\"מ שם) — הי' זה תיכף לאחרי עשיית המשתה גדול שאז \"היניקה בנים שרה\" (וירא כא, ז) — \"ועדיין היו מרננים כו' מיד נהפך קלסתר פנים כו'\". וראה חדא\"ג מהרש\"א שם."],["864","5","להעיר מפרש\"י ר\"פ נח \"ד\"א ללמדך כו'\"."],["865","6","ספורנו כאן."],["866","7","ויצא לא, מב. וראה ת\"א ותיב\"ע שם. ועוד."],["867","8","ישעי' מא, ח."],["868","9","ר\"ה יא, רע\"א (וראה תוס' שם). רש\"י וירא יח, י. ועוד."],["869","10","טאו\"ח סתי\"ז. וכ\"ה בזח\"ג רנז, ריש ע\"ב."]]],[1301410168,"הרגלים הם כנגד הג' אבות — פסח כנגד אברהם, שבועות כנגד יצחק וסוכות כנגד יעקב. ונמצא, שלידת יצחק היתה ברגל שכנגד אברהם. ומובן בפשטות שאין זה במקרה, אלא מפני שכן הוא הדבר מצד תוכן ענינה של לידת יצחק, דמכיון שמציאותו של יצחק \"דומה\" ל­אברהם (אהבה וחסד), לכן גם לידתו (כפשוטה) היתה ב\"רגל\" דאברהם<sup data-n=\"870\">11</sup>.\nב) שמו: \"יצחק\" הוא מלשון \"צחוק\"<sup data-n=\"871\">12</sup> — ע\"ש \"צחוק עשה לי אלקים\"<sup data-n=\"872\">13</sup>, ענין של שמחה<sup data-n=\"873\">14</sup>. והרי שמחה היא תנועה הפכית ממדת היראה והפחד<sup data-n=\"874\">15</sup> — ואעפ\"כ נקרא יצחק בשם המורה על שמחה.\nג) כללות ענינו — ויגדל האיש גו' עד כי גדל מאד<sup data-n=\"875\">16</sup> — תכלית החסד והגדלות.\nד) וארבה את זרעו (ע\"י אשר) ואתן לו את יצחק<sup data-n=\"876\">17</sup>.\nועוד.\nג. לכאורה הי' אפשר לבאר זה ע\"פ הידוע<sup data-n=\"877\">18</sup>, דזה שהעבודות של אברהם ו­יצחק היו בשני קוים שונים וגם הפכיים — הכוונה בזה שעיקר עבודתו של אבר­הם היתה במדת החסד, אבל לא שהיתה מוגבלת רק בה אלא היתה כלולה גם ממדת הגבורה והיראה, וכמפורש אצל אברהם<sup data-n=\"878\">19</sup> — \"עתה ידעתי כי ירא אלקים אתה\"; וכמו כן הוא ביצחק, שעבודתו היתה כלולה גם ממדת החסד, אלא שעבודתו העיקרית היתה במדת היראה.\nועפ\"ז יש לפרש<sup data-n=\"879\">20</sup> דזה שאמר הכתוב \"אברהם הוליד את יצחק\", שהקב\"ה \"צר קלסתר פניו של יצחק דומה לאברהם\" — הכוונה בזה לא רק לתואר פניו ה­גשמי, כ\"א גם ל\"קלסתר פניו\" הרוחני, כלומר — מדתו ועבודתו, ובא ללמדנו כי בעבודתו של יצחק ישנה עבודת ה­אהבה (דאברהם).\nאמנם, לכאורה אין זה ביאור מספיק, כי מאחר ששמו של יצחק בפי כל ותמיד הוא ע\"ש השמחה דוקא, עכצ\"ל שזהו עיקר ענינו של יצחק<sup data-n=\"880\">21</sup>.\nזאת ועוד: ידוע<sup data-n=\"881\">22</sup> החילוק בין גילה ושמחה — דגילה מורה על רגש של שמ­חה שאינו באופן גלוי כ\"כ [שלכן יכולה להיות ה\"גילה\" ביחד עם היראה ורעדה, וכמו שנאמר<sup data-n=\"882\">23</sup> \"עבדו את ה' ביראה וגילו ברעדה\"], משא\"כ שמחה היא —",[["870","11","בחדא\"ג מהרש\"א ר\"ה שם (י, ב) ש\"יצחק שהוא מדת הדין נברא בפסח שבו הי' שולט מדת הדין על המצריים כו'\". אבל בזהר שם (ועוד), שפסח כנגד אברהם והוא מסטרא דימין. וכן הוא לכאורה פשטות הענין, שעיקר ענינו של פסח הוא — גאולת ישראל (לא עונש המצרים), ענין של חסד."],["871","12","רש\"י לך יז, יט. — ולהעיר שנק' גם \"יש­חק\" (תהלים קה, ט. ועוד). וראה תו\"ח פרשתנו (ה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550705\" data-slug=\"torat-chaim\" data-id=\"2300550705\">שם ד</a>). ובכ\"מ."],["872","13","וירא כא, ו. — וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550694\" data-slug=\"torat-chaim\" data-id=\"2300550694\">תו\"ח (פרשתנו שם, א</a>; ויצא כה, א) ובכ\"מ, שזהו טעם קריאת שם יצחק. וראה פי' הר\"י בכור שור שם."],["873","14","רש\"י שם."],["874","15","ראה גם זהר ר\"פ אחרי: עבדו את ה' ביראה וגילו ברעדה וכתיב עבדו את ה' בשמחה. . הני קראי קשיין אהדדי. וראה בארוכה לקוטי לוי\"צ שם (ושם גם בנוגע ליצחק). ולהעיר משל\"ה פרשתנו (רפז, ב)."],["875","16","פרשתנו כו, יג. וראה לקמן הערה 42."],["876","17","יהושע כד, ג. וארז\"ל יצחק בגימ' ארבה (שעה\"פ להאריז\"ל ר\"פ בא. מ\"ח מס' סדר ליל פסח פ\"י מ\"א)."],["877","18","תניא אגה\"ק סי\"ג (קיט, ב). ובכ\"מ."],["878","19","וירא כב, יב."],["879","20","ראה גם ס' הליקוטים דא\"ח דהצ\"צ ערך יצחק ס\"ב. וש\"נ."],["880","21","ולהעיר ממחז\"ל (ב\"ר ריש פרשתנו — פס\"ג, ג) יצחק נקרא אברהם דכתיב אלה תולדות יצחק בן אברהם אברהם."],["881","22","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, רע\"א</a>."],["882","23","תהלים ב, יא. — וראה זהר שם: דאסיר לי' לב\"נ כו'."]]],[1301410169,"שמחה גלוי'<sup data-n=\"883\">24</sup>. ולפ\"ז מה שנקרא בשם יצחק ע\"ש הרגש (הגלוי) של \"צחוק\", מורה (לא על הגילה הכלולה במדת היראה, \"וגילו ברעדה\", כ\"א) על השמחה הגלוי' דוקא.\nומזה מובן, שזה שיצחק \"דומה\" ל­אברהם אינו רק מצד התכללות המדות זו בזו (שגם בעבודת יצחק כלולה מדת האהבה), אלא שהשמחה הוא ענין מיוחד ועיקרי ביצחק.\nד. וי\"ל ביאור הענין:\nמהחילוקים שבין אהבה (מדתו של אברהם) ליראה (מדתו של יצחק): ענינה של אהבה הוא קירוב האוהב אל הנאהב, שאין בזה תנועה של התבטלות האוהב כלפי הנאהב, אדרבה, באהבה מורגשת מציאות האוהב, שהוא נעשה קרוב<sup data-n=\"884\">25</sup>; משא\"כ יראה ענינה — שהאדם מתבטל ומאבד תוקפו ומציאותו כלפי זה שירא ממנו.\nדוגמא לדבר — החילוק בין בן ו­עבד:\nהיחס בין בן לאביו יסודו (בעיקר) ברגש האהבה שביניהם — והרי אהבת הבן אל אביו אינה מבטלת \"מציאותו\" של הבן, כ\"א כפי שהוא במציאותו יש לו קירוב (ואהבה) אל אביו; משא\"כ ה­יחס של העבד לאדונו קשור (בעיקר) במדת היראה (יראת העבד מאדונו), ש­ענינה ופעולתה הוא הביטול — שמקבל עליו את עול אדונו וכפוף ובטל אליו.\nוכן הוא בעבודת השם:\nידוע שבנ\"י הם \"אם כבנים אם כ­עבדים\"<sup data-n=\"885\">26</sup>: \"בנים אתם לה' אלקיכם\"<sup data-n=\"886\">27</sup>, \"עבדי הם\"<sup data-n=\"887\">28</sup>: ההתבוננות בקירובו של הקב\"ה לישראל, \"כי אתה אבינו\"<sup data-n=\"888\">29</sup>, מ­עוררת ומגלה האהבה לה'; וההתבוננות בזה שהקב\"ה הוא \"מלכנו\" מעוררת ו­מגלה היראה והביטול.\nוהחילוק בין שתי המדות הללו (אה­בת השם ויראתו) בפעולתן בנפש האדם הוא: האהבה מעוררת התקרבות האדם להקב\"ה; היראה פועלת בהאדם הרגש הביטול והשפלות לפניו ית'.\nה. והנה במדת ה\"ביטול\" והשפלות מצינו, שלא זו בלבד שצ\"ל הזהירות ש­האדם לא ייעשה עי\"ז כ\"אסקופה הנד­רסת\"<sup data-n=\"889\">30</sup> ח\"ו — אלא עוד זאת, שהביטול משמש ג\"כ הכנה והכשרה להתקרבות להקב\"ה. כלומר, אין מטרת היראה וה­ביטול שהאדם יבוא לידי מסקנה שהוא אינו כלום ותו לא, אלא אדרבה, שמכיון שהוא בטל, ביכלתו להתקרב להקב\"ה.\nואדרבה: מדת ההתקרבות להקב\"ה ע\"י הקדמת הביטול היא ביתר שאת מה­התקרבות שמצד האהבה לבדה. כי מ­אחר שמדת האהבה קשורה עם הרגש מציאות עצמו (שהוא מתקרב להשם), והרי האדם הוא נברא בעל גבול, לכן, גם מדת התקרבותו להקב\"ה היא בהג­בלה; דוקא כשהאדם מבטל את עצמו (על ידי שמעורר בנפשו מדת היראה), הרי הוא מכשיר א\"ע להיות כלי להת­",[["883","24","כמובן גם מזהר שם, ד\"עבדו את ה' ב­שמחה\" היא בסתירה ל\"עבדו את ה' ביראה\" (אף שאפ\"ל \"וגילו ברעדה\")."],["884","25","ראה בארוכה בזה — ספר הערכים­חב\"ד ח\"א ערך אהבה סעיף ב­ג. וש\"נ. שם ערך אהבת ה' סעיף ד. וש\"נ."],["885","26","פיוט \"היום הרת עולם\" בתפלת מוסף דר\"ה. וראה הפטורת פרשתנו (מלאכי א, ו) בן גו' ועבד גו' אי' כבודי גו' אי' מוראי גו'."],["886","27","פ' ראה יד, א."],["887","28","בהר כה, מב. שם, נה."],["888","29","ישעי' סג, טז."],["889","30","ל' הש\"ס — עירובין צח, א."]]],[1301410170,"גלות אלקות שלמעלה ממדידה והגבלה (בלשון הכתוב<sup data-n=\"890\">31</sup> \"מרום וקדוש אשכון ואת דכא ושפל רוח\", שרוממות השם וקדושתו שוכנת דוקא אצל \"דכא ושפל רוח\").\nוכמו שמצינו גם בדוגמא הנ\"ל (סעיף ד) דעבד ואדון, שאחז\"ל<sup data-n=\"891\">32</sup> \"עבד מלך — מלך\", כלומר: דוקא משום שהוא עבד, ה\"ה \"כלי\" שבו וע\"י מתגלה תוקפו של המלך; היות שכל מציאותו הוא עבד המלך, שאין לו שום מציאות ותוקף לעצמו כלל, הרי שכל תוקפו אינו אלא תוקפו של המלך המתגלה על ידו.\nו. זהו גם אחד מהביאורים בהב­קשה<sup data-n=\"892\">33</sup> \"ונפשי כעפר לכל תהי' פתח לבי בתורתך\" — דלכאורה, שני ענינים אלו הם הפכים זמ\"ז: \"ונפשי כעפר לכל תהי'\" הוא ביטול גמור, כעפר \"שהכל דשין בו\"<sup data-n=\"893\">34</sup>; ו\"פתח לבי בתורתך\" הוא, אדרבה, ענין של \"מציאות\" (לב המרגיש ומבין), ועוד יותר — פתיחת הלב, שהיא תנועה של התפשטות והתרחבות (היפך הביטול) — ואיך יתכן לומר, שהדרך לפתוח לבו בתורת השם היא ע\"י הקדמת \"ונפשי כעפר לכל תהי'\"?\nאלא שהיא הנותנת<sup data-n=\"894\">35</sup>: בלי הקדמה זו של \"ונפשי כעפר לכל תהי'\", כשהכשרת האדם לקליטת דברי תורה היא רק ב­יגיעת מוחו ושכלו ותו לא — אי אפשר לו להגיע לפתיחת לב אמיתית \"בתור­תך\". כי התורה היא חכמתו של הקב\"ה, שלמעלה באין ערוך משכלו (המוגבל) של נברא — והאדם בכח עצמו יכול להשיג רק חלק הכי מצומצם ביותר ממנה<sup data-n=\"895\">36</sup>.\nאמנם כשהאדם מבטל את עצמו, ועד שהוא מרגיש את עצמו כמו עפר — \"ו­נפשי כעפר לכל תהי'\" — הרי דוקא עי\"ז נעשה מוכשר לקבל תורתו של הקב\"ה ועד — בהבנה והשגה, ויתרה מזה באופן ד\"פתח לבי בתורתך\" — להגיע להרחבה אמיתית דפתיחת הלב, ולקלוט \"תורתך\" (— של השם, כפי שהיא למעלה משכל הנברא). והיינו משום שאין בפתיחת הלב הלזו הרגש של מציאות עצמו (המונעת קליטת תורתו של הקב\"ה שלמעלה ל­גמרי ממציאות הנבראים) — וכל ענינה היא פתיחת הלב של קדושה.\nז. ע\"פ כל הנ\"ל י\"ל גם בנוגע ל­יצחק:\nהיראה אצל יצחק, היתה הכנה והכ­שרה להשמחה ופתיחת הלב בעבודת ה­שם, הבאה ע\"י הקדמת הביטול. ולכן נקרא בשם יצחק — מלשון צחוק ושמחה, המורה על התרחבות והתפשטות (עד להתפשטות שאין בה הגבלה, כידוע<sup data-n=\"896\">37</sup> ששמחה פורצת כל הגדרים) — כי ב­יראה וביטול של יצחק מתגלה תגבורת החיות, הרחבות האמיתית דקדושה (\"פתח לבי בתורתך\").\nוזהו מה שמלמדנו הפסוק — \"ואלה תולדות יצחק בן אברהם אברהם הוליד את יצחק\", שיצחק הי' דומה לאברהם (ועד שלידתו היתה בפסח דוקא, הרגל",[["890","31","ישעי' נז, טו."],["891","32","רש\"י בהעלותך יב, ח. ספרי (ורש\"י) דברים א, ז. ועוד (ובשבועות מז, ב: כמלך)."],["892","33","תפלת אלקי נצור (ברכות יז, א)."],["893","34","עירובין נד, א."],["894","35","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151338\" data-slug=\"likkutei-sichot\" data-id=\"1300151338\">לקו\"ש חט\"ו ע' 326</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261340\" data-slug=\"likkutei-sichot\" data-id=\"1300261340\">חכ\"ו ס\"ע 250</a> ואילך."],["895","36","בחלקה שיש להאדם שייכות אליו (משא\"כ זה ששכל הנברא בו הוא כמו חוש המישוש בנוגע לשכל)."],["896","37","ד\"ה שמח תשמח תרנ\"ז (סה\"מ תרנ\"ז ע' רכג ואילך)."]]],[1301410171,"שכנגד אברהם) — מאחר שענינה של עבודת יצחק במדת היראה היא התקר­בות להקב\"ה; אלא שמכיון שהיא התקר­בות בלתי מוגבלת (שלמעלה ממציאות הנבראים) הרי היא באה ע\"י היראה וה­ביטול דוקא<sup data-n=\"897\">38</sup>.\nוענין זה, שעבודתו הרוחנית של יצחק היא שמחה ופתיחת הלב, המורה על תנועה של הרחבה, בא לידי ביטוי גם בחייו דנשמה בגוף, ועד לגשמיות ה­גוף, שמצינו ביצחק במיוחד הרחבה (גם) בגשמיות כפשוטה — ובזה מדובר ברוב הסדרה:\nתחילת הסיפור (אודות יצחק עצמו) היא ציווי השם אליו \"אל תרד מצרימה גו' גור בארץ הזאת גו'\"<sup data-n=\"898\">39</sup> שאינו אצל אברהם ויעקב, וטעם הדבר — מפני \"ש­אתה (דוקא) עולה תמימה\"<sup data-n=\"899\">40</sup>, דוקא יצחק נתקדש בקדושה כזו שבגללה \"אין חוצה לארץ כדאי לך\"<sup data-n=\"900\">41</sup> (בהתאם להנת\"ל שע\"י היראה וביטול של יצחק נעשה כלי לה­קדושה שלמעלה מן העולם).\nועי\"ז נמשך בו ריבוי ברכות השם, ו­כהמשך הסיפור ע\"ד הברכות שזכה בהן יצחק בהיותו בגרר, עד שכנ\"ל \"ויגדל האיש וילך הלוך וגדל עד כי גדל מאד\"<sup data-n=\"901\">42</sup>, גדלות שלמעלה ממדידה ו­הגבלה;\nאח\"כ בא הסיפור אודות הבארות ש­חפר יצחק, שסיומו וחותמו — \"ויקרא שמה רחובות גו' כי עתה הרחיב ה' לנו ופרינו בארץ\"<sup data-n=\"902\">43</sup>, רחבות דקדושה;\nואח\"כ<sup data-n=\"903\">44</sup> — אריכות הסיפור בנוגע לברכות יצחק, שהן ברכות נעלות ביותר ש\"לא מצינו ענין ברכות כאלה לא באב­רהם ולא ביעקב\"<sup data-n=\"904\">45</sup>, עד שאפילו ברכות משה אינן כברכות יצחק<sup data-n=\"904\">45</sup> — כי דוקא על ידי מדת היראה והביטול דיצחק נמשכת הרחבה, תגבורת החיות (והשפע) שלמעלה ממדידה והגבלה.\nח. הסברת השייכות בין מדת היראה דיצחק לענין ה\"הרחבה\" בעומק יותר י\"ל:\nאמרו חז\"ל<sup data-n=\"906\">46</sup> האבות הן הן המרכבה, כי כמו שהמרכבה בטלה לגבי הרוכב המנהיג את המרכבה כרצונו, כן הוא אצל האבות, שכל עניניהם ועשיותיהם היו \"מונהגים\" מרצון העליון.\nוכן הוא בנוגע למדות האבות — זה בחסד וזה בגבורה כו' — שאין כוונת הדברים שסיבת ומקור מדתם זו מפני שכן הי' טבע נפשם, אלא מפני שהיו \"מרכבה\" למדה זו שלמעלה<sup data-n=\"907\">47</sup>: אברהם הי' מרכבה למדת החסד דלמעלה וב­התאם למדה זו היתה כל הנהגתו, ולכן היתה (עיקר) עבודתו במדת האהבה;",[["897","38","ולהעיר שגם חסד דאברהם, מכיון שענינו הקירוב לה', יש בו ענין הביטול, \"ואנכי עפר ואפר\" (ראה תניא אגה\"ק ס\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380784\" data-slug=\"likkutei-torah\" data-id=\"4001380784\">לקו\"ת עקב יז, ג</a> ואילך. ובכ\"מ) — אלא שאינו כיצחק שעיקר ענינו יראה וביטול. ואכ\"מ."],["898","39","כו, ב­ג."],["899","40","רש\"י שם (מב\"ר פס\"ד, ג)."],["900","41","ל' רש\"י."],["901","42","כו, יג. וראה רש\"י שם (מב\"ר שם, ז): זבל פרדותיו כו'. וראה שם, יב ובפרש\"י."],["902","43","כו, כב. וראה רמב\"ן (ועוד) שם דקאי על ביהמ\"ק הג' (שאז ירחיב ה\"א את גבולך גו'). ו­להעיר, שלעתיד יאמרו ליצחק דוקא כי אתה אבינו (שבת פט, ב. נת' בתו\"א פרשתנו בארוכה)."],["903","44","כז, א ואילך (והוא חלק גדול דהסדרה)."],["904","45","סדור עם דא\"ח ש' התקיעות בסופו (רמז, ב)."],["904","45","סדור עם דא\"ח ש' התקיעות בסופו (רמז, ב)."],["906","46","ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["907","47","ראה בפרטיות ספר הערכים­חב\"ד ערך אבות בתחילתו וערך אברהם אבינו בתחילתו. וש\"נ."]]],[1301410172,"ועד\"ז ביצחק שהי' מרכבה למדת ה­גבורה דלמעלה, ולכן היתה (עיקר) עבו­דתו במדת היראה.\nט. והנה בנוגע למדת הגבורה של­מעלה מבואר<sup data-n=\"908\">48</sup>, שבשרשה ומקורה אין ענינה — דין וצמצום (מניעת ההשפעה), אלא אדרבה, גבורה מלשון תגבורת, תג­בורת החיות (ע\"ד גבורות גשמים<sup data-n=\"909\">49</sup>).\nוההפרש בין מדת החסד למדת ה­גבורה הוא, שמדת החסד, מכיון שענינה השפעה אל הזולת, לכן על ידה באה ה­השפעה באופן שיוכל המקבל לקבלה<sup data-n=\"910\">50</sup>; משא\"כ מדת הגבורה היא השפעה בהת­גברות רבה (השפעה שלפי ערך ה\"מש­פיע\") [אלא שמזה נמשך ונשתלשל אח\"כ ענין הצמצום והגבורה (מניעת השפע) כפשוטה, בפרט כשהמקבל אין ביכלתו להכיל שפע רב כזה].\nונמצא, שלא זו בלבד שענין הגבורה והדין שלמעלה אינו בשביל הדין עצמו ח\"ו, וכל מטרת הדין הוא רק חסד [כ­ידוע<sup data-n=\"911\">51</sup> בענין עונשי התורה, שאין מטר­תם העונש עצמו ח\"ו, אלא כדי למרק ולזכך את האדם עד שיתכפר לו החטא, שלכן כל התורה — כולל עניני העונש שבה — נקראת \"תורת חסד\"<sup data-n=\"912\">52</sup>] — אלא עוד זאת, שעצם מדת הגבורה שלמעלה בשרשה ומקורה אינה ענין של דין ומני­עת השפע, אלא אדרבה — תגבורת ה­השפעה דוקא<sup data-n=\"913\">53</sup>.\nי. ומשתי מדותיו יתברך, חסד וגבו­רה, נשתלשלו ונמשכו בהאדם שתי ה­מדות דאהבה ויראה בעבודתו יתברך:\nממדת החסד דלמעלה, שהיא השפעת חסדו ית' שלפי ערך הנבראים ואשר ב­יכלתם לקבל, נמשך באדם הרגש ה­אהבה, כי כאשר מרגיש חסדו של הקב\"ה, הנה כמים הפנים לפנים מתעורר האדם להתקרב אל השם;\nומדת הגבורה דלמעלה — תגבורת ההשפעה (שלמעלה ממדידה והגבלה של הנבראים) — מעוררת באדם את הרגש היראה והביטול, שעי\"ז ביכלתו לקבל גם תגבורת השפע (ע\"ד משנת\"ל, שהבי­טול ד\"ונפשי כעפר לכל תהי'\" הוא כלי ל\"פתח לבי בתורתך\").\nהרי מובן, שאין מדת היראה של יצחק ענין הפכי ממדת האהבה של אברהם — שהרי ענינה ותכליתה של היראה והביטול הוא כדי שתאיר אצלו תגבורת החסד שלמעלה<sup data-n=\"914\">54</sup>, ויתקרב אל השם ביתר שאת ויתר עז<sup data-n=\"915\">55</sup>.",[["908","48","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א ט, ג</a><sup data-n=\"e20\"><a class=\"ft-cite\" href=\"#/read/torah-or/3901370524\" data-slug=\"torah-or\" data-id=\"3901370524\">*</sup>. וראה שם קיז, ב</a>. ובכ\"מ."],["909","49","משנה ריש תענית."],["910","50","להעיר מתענית כג, א: רוב טובה. . אינן יכולין לעמוד."],["911","51","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380667\" data-slug=\"likkutei-torah\" data-id=\"4001380667\">לקו\"ת מטות פו, סע\"ב</a>. ובכ\"מ. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231098\" data-slug=\"likkutei-sichot\" data-id=\"1300231098\">לקו\"ש חכ\"ג ע' 98</a> ואילך, שכ\"ה גם ע\"ד הפשט. ע\"ש."],["912","52","משלי לא, כו."],["913","53","וראה זח\"ג (קכט, א) דבעתיקא \"כולא ימי­נא\" (היינו שיש שתי \"ידות\" (והנהגות), אלא ששתיהן \"ימינא\" וחסד). — ובכ\"מ מבואר שיצחק הוא גבורות דעתיק (תו\"א לט, ב. ס' הליקוטים דא\"ח דהצ\"צ ערך יצחק סעיף ג (וש\"נ). ועוד)."],["914","54","ולהעיר שדוקא זמן מנחה (דשבת) — שכ­נגד יצחק והוא תקנה והוא זמן גבורות (ראה זח\"ב סג, א. ועוד. ד\"ה ואני תפלתי, תרנ\"ד. ועוד) — נק' \"רעוא דרעוין\" (זח\"ג קכט, א), תכלית החסד, עוד יותר מחסד דאברהם (תפלת שחרית).\nאבל להעיר משבת (קיח, סע\"א) דאז נחלה בלי מצרים דיעקב."],["915","55","ולהעיר מד\"ה למען יחלצון תר\"פ (סה\"מ תר\"פ ע' קיד ואילך) בטעם שיצחק נק' \"ידיד\" (לרש\"י שבת קלז, ב. וכ\"ה בזח\"א צו, רע\"א), המורה על תוקף האהבה ביותר — כי אהבה דיצחק היא אהבה כרשפי אש (שלמעלה ממדוה\"ג), משא\"כ אהבת אברהם שהיא אהבה כמים, אהבת עולם. ע\"ש."],["e20","*","ומשמע שם שהכוונה גם לגבורה דאצילות. וראה לקמן הערה 53. וצ\"ע. ואכ\"מ."]]],[1301410173,"וזהו הטעם שדוקא אצל יצחק מצינו ענין הברכה בריבוי ש\"לא מצינו ענין ברכות כאלה לא באברהם ולא ביעקב\" כנ\"ל — כי דוקא על ידי מדת היראה דיצחק נמשכת תגבורת השפע שלמעלה ממדידה והגבלה<sup data-n=\"916\">56</sup> —\nברכת \"רב טוב לבית ישראל. . כרוב חסדיו\"<sup data-n=\"917\">57</sup>, רב טוב גשמי ורב טוב רוחני, ובגשמיות וברוחניות גם יחד,\nובטוב הנראה והנגלה דוקא, למטה מעשרה טפחים, כפשוטו ממש.\n<span data-k=\"q\">(משיחת ש\"פ אחרי תשמ\"א) </span>",[["916","56","וע\"פ הנ\"ל בפנים בטעם לידת יצחק בפסח דוקא (רגל דאברהם) מובנת השייכות דברכות יצחק לפסח דוקא (רש\"י פרשתנו כז, ט מפדר\"א פל\"ב).\nולהעיר מדעת הזהר אמור (רע\"מ צט, ב) שהי' בר\"ה. ומובן ע\"פ המבואר בסדור שם (הערה 45) השייכות דתק\"ש לתגבורת ההשפעה ע\"י גבורות דיצחק דוקא. ע\"ש."],["917","57","ישעי' סג, ז."]]],[1301410174,"<h3>שיחה ב</h3>\nא. \"וימלאו ימי' ללדת והנה תומם בבטנה\"<sup data-n=\"918\">1</sup>, ופרש\"י \"וימלאו ימי', אבל ב­תמר כתיב<sup data-n=\"919\">2</sup> ויהי בעת לדתה שלא מלאו ימי' כי לז' חדשים ילדתם\".\nוצריך ביאור:\nנתבאר כמ\"פ, שכאשר ישנה סתירה בין שני כתובים, דרכו של רש\"י ליישבה בכתוב השני, במקום שמתעוררת הסתי­רה. וא\"כ קשה בנדו\"ד — מה ראה רש\"י לעמוד כאן על השינוי בין לשון הכתוב כאן ולשון הכתוב לקמן בתמר?\nובפרט שעה\"פ (הנ\"ל) \"ויהי בעת ל­דתה\" (בפ' וישב) חוזר רש\"י ליישב שינוי זה (\"וברבקה הוא אומר וימלאו ימי' ל­לדת להלן למלאים וכאן לחסרים\") — וא\"כ יפלא ביותר אמאי הוזקק לפרשו גם כאן, לפני שמתעוררת שאלת השינוי בין שני הכתובים?\nגם יש לדייק בל' רש\"י כאן — ש­מבאר רק הכתוב דתמר \"שלא מלאו ימי' כי לז' חדשים ילדתם\", דלכאורה הו\"ל לפרש לכל לראש את הכתוב דידן, ש­רבקה ילדתם למלאים, ואח\"כ להוסיף \"אבל תמר לא מלאו ימי' כו'\".\nוביותר תמוה: מקורו של רש\"י הוא במדרש רבה על פסוק זה<sup data-n=\"920\">3</sup> — והרי שם הלשון \"להלן חסרים וכאן מלאים\", ואילו רש\"י מסביר רק לשון הכתוב דפ' וישב, ובנוגע לרבקה אינו מפרש כלום!\nלכאורה יש לומר בפשטות, שגבי רבקה א\"צ לפרש ש\"כאן מלאים\", שהרי מפורש בכתוב \"וימלאו ימי' ללדת\", וכל החידוש הוא רק בפירוש \"בעת לדתה\" דתמר, שמשנה הכתוב בלשונו מפני \"ש­לא מלאו ימי' (כי לז' חדשים ילדתם)\".\nאבל נוסף לכך, שעפ\"ז תוגדל ביותר התמי' דלעיל — מאי דוחקי' דרש\"י כאן לפרש הכתוב דתמר לקמן (מאחר שה­כתוב כאן אינו דורש שום ביאור ל­יישבו, כ\"א רק את צד השינוי דתמר) — הרי רש\"י עצמו נקט לקמן בפ' וישב (ע\"ד) לשון המדרש<sup data-n=\"920\">3</sup> \"להלן למלאים ו­כאן לחסרים\", וכיון שכאן לא נחית לפרט ש\"כאן למלאים\" (כי למותר הוא כנ\"ל), מאי שנא גבי תמר שמפרש \"ו­להלן למלאים\" (לאחר שמביא שם לשון הכתוב \"וימלאו ימי' וגו'\")?\nב. אח\"כ מעתיק רש\"י \"והנה תומם\" ומפרש \"חסר<sup data-n=\"922\">4</sup>, ובתמר<sup data-n=\"919\">2</sup> תאומים מלא לפי ששניהם צדיקים אבל כאן אחד צדיק ואחד רשע\".\nוגם בזה יל\"ע, ע\"ד הנ\"ל, מה ראה רש\"י לעמוד כאן על השינוי לקמן",[["918","1","פרשתנו כה, כד."],["919","2","וישב לח, כז."],["920","3","פס\"ג, ח. ועד\"ז בב\"ר לקמן בפ' וישב (פפ\"ה, יג)."],["920","3","פס\"ג, ח. ועד\"ז בב\"ר לקמן בפ' וישב (פפ\"ה, יג)."],["922","4","ראה ס' זכרון על פרש\"י כאן, שהכוונה לחסרון היו\"ד ולא האל\"ף<sup data-n=\"e21\">*</sup>. ע\"ש. וראה גם חזקוני ורד\"ק כאן. אבל בפי' המיוחס לרש\"י (לב\"ר פפ\"ה, יג): בלא אל\"ף (ובא' מכת\"י רש\"י שתח\"י הגירסא כאן \"חסר אלף\"). וכ\"ה בזח\"ב עח, ב. — וראה בעה\"ט ופענח רזא כאן, \"חסר א' וחסר י' כתיב\". ע\"ש. ואכ\"מ."],["919","2","וישב לח, כז."],["e21","*","ובגו\"א כאן (וראה גו\"א וישב שם), ש­\"תאומים\" מלא דתמר היינו מלא וי\"ו. ע\"ש."]]],[1301410175,"(\"תאומים מלא\") גבי תמר? ובפרט שבפ' וישב שם מיישב רש\"י (עוה\"פ) גם שינוי זה.\nגם צריך ביאור בעצם פירושו בזה שתיבת \"תאומים\" כאן היא \"חסר\":\nנתבאר כמ\"פ — וכ\"כ כמה מפרשי רש\"י<sup data-n=\"924\">5</sup> — שהשינויים ד\"מלא\" ו\"חסר\" כש­לעצמם אינם ענין המעורר קושי בפשוטו של מקרא (שלכן ע\"פ רוב אין רש\"י מבאר הטעם לחסרות כו' שבמקרא), וב­מקום שרש\"י מבאר טעמם, ה\"ז רק משום שעי\"ז מתבאר דבר הקשה בפשוטו של מקרא. ועפ\"ז יש להבין בנדו\"ד — מה קשה בל' הכתוב \"והנה תומם בבטנה\" שבגלל זה מדייק רש\"י ש\"תומם\" חסר כתיב?\nג. ויש לומר הביאור בכל זה:\nכוונת רש\"י בפירושו על \"וימלאו ימי'\" היא לתרץ (לא קושי השינוי בלי­מוד הפסוק דפ' וישב, אלא) שאלה המת­עוררת כאן, והיא — שהתיבות \"וימלאו ימי'\" נראות כמיותרות — דלכאורה מאי קמ\"ל? הלא מובן מאליו שהלידה (ע\"ד הרגיל) היא לאחר ש\"מלאו\" הימים ל­לדת — שלכן לא מצינו עד כאן, בכל המקומות שהוזכר ענין של לידה, שה­כתוב יקדים לזה \"וימלאו ימי'\" וכיו\"ב. ומה מחדש הכתוב כאן ש\"וימלאו ימי'\"?\n[בתרגום יונתן כאן איתא \"ושלימו מאתן ושובעין יומי עיבורהא למילד\", והיינו שט' חדשי העיבור היו ט' חדשים שלמים (ולא ילדה באמצע החודש הט').\nאבל מלבד זאת שפירוש זה תלוי בהפלוגתא<sup data-n=\"925\">6</sup> אם היולדת לט' יולדת ל­מקוטעין או לאו; ולמ\"ד שאינה יולדת למקוטעין, כל לידה (לתשעה חדשים) היא לט' חדשים שלמים<sup data-n=\"926\">7</sup> — הרי עדיין עיקר התמי' במקומו עומד: סוף­סוף ל­מאי נפק\"מ אם ילדה לט' חדשים שלמים או לא<sup data-n=\"927\">8</sup>?].\nועל זה מתרץ רש\"י — \"אבל בתמר כתיב ויהי בעת לדתה שלא מלאו ימי' כו'\", כלומר: התיבות \"וימלאו ימי'\" לא נכתבו כאן אלא ללמדנו כוונת השינוי גבי תמר, \"ויהי בעת לדתה\", ששם (ב­תמר) לא היתה הלידה באופן ד\"וימלאו ימי'\".\nכלומר: לולא הכתוב כאן \"וימלאו ימי'\" (ברבקה), לא היינו יודעים לדייק שהכוונה בתיבות \"בעת לדתה\" (בתמר) היא \"לחסרים\" (והיינו מפרשים הכתוב כפשוטו, שרק בעת לדתה נודע לתמר שתאומים בבטנה)<sup data-n=\"928\">9</sup>; אבל לאחר שנאמר ברבקה הלשון \"וימלאו ימי'\" משא\"כ",[["924","5","ראה דברי דוד ודבק טוב פרשתנו בפסוק שלפנ\"ז (כה, כג). גו\"א בראשית א, יד. משכיל לדוד שם ובפ' עקב ט, יא (ובכ\"מ). ועוד."],["925","6","נדה כז, א. ועוד."],["926","7","ומפרש\"י שמות (ב, ג) \"והם בדקו אחרי' לסוף ט'\" משמע שס\"ל לרש\"י שהיולדת לט' אינה יולדת למקוטעין (אף שהיולדת לשבעה יולדת ל­מקוטעין<sup data-n=\"e22\">*</sup>, כפרש\"י שם. וראה נדה לח, ריש ע\"ב. וש\"נ. רש\"י נדה כז, א ד\"ה כ\"ג) — ראה ס' זכרון, משכיל לדוד, באר בשדה ועוד על פרש\"י שם. וראה לקמן סעיף ה' ובהנסמן בהערה 22."],["927","8","ראה מעשה ה' פרשתנו (רפכ\"ז). נזר הקודש (השלם) לב\"ר פרשתנו שם. באר בשדה על פרש\"י כאן."],["928","9","ראה רא\"ם (ועוד מפרשים) לפרש\"י וישב לח, כה ד\"ה הכר נא."],["e22","*","ולהעיר, שבדפוס שני דפרש\"י כאן (וכן בפ' וישב שם) שתמר ילדה לו' חדשים וששה יום. וכן נעתק ביפה תואר השלם לב\"ר פרשתנו שם."]]],[1301410176,"בתמר כתיב \"ויהי בעת לדתה\" (במקום \"וימלאו ימי' ללדת\"), הרי שינוי זה שבין הכתובים מלמדנו, שבתמר \"לא מלאו ימי'\".\nומתורץ בפשטות טעם השינוי בלשון רש\"י — שכאן מפרש רק \"ויהי בעת לדתה\" דתמר ואילו בפ' וישב כותב \"להלן למלאים וכאן לחסרים\" — כי כאן בפרשתנו כוונת רש\"י היא לתרץ היתור ד\"וימלאו ימי'\", וע\"ז מפרש שבא להש­מיענו את הפירוש ד\"ויהי בעת לדתה\" שנאמר גבי תמר (ולכן אין צורך לכתוב מאומה בנוגע ל\"וימלאו ימי'\"), משא\"כ להלן בפ' וישב כוונת רש\"י היא ליישב את שינוי הלשונות בין שני המקומות — ובהתאם לזה כותב שם<sup data-n=\"929\">10</sup> \"להלן למלאים וכאן לחסרים\".\nד. אלא שעדיין אינו מובן:\nא) כיון שהתיבות ד\"וימלאו ימי'\" לא באו כאן אלא להורות על כוונת הכתוב בתמר — מדוע נאמרו דוקא בפרשתנו גבי רבקה, ולא בלידה הסמוכה ללידת פרץ וזרח (בלידת ער ואונן או בלידת שלה<sup data-n=\"930\">11</sup>), שאז הי' השינוי בולט יותר (שב­אותה פרשה עצמה משנה הכתוב בלשונו בין לידה ללידה)?\nב) בתוכן הענין אינו מובן — למאי נפק\"מ שתמר \"לא מלאו ימי' כי לז' חדשים ילדתם\"<sup data-n=\"927\">8</sup> (והרי התורה אינה מס­פרת את כל פרטי המאורעות של האבות והשבטים וכו', כ\"א רק אותם השייכים לתוכן הסיפורים).\nג) לאחר שפירש רש\"י שמדיוק הכתו­בים אנו למדים שיש לידה באופן ד\"מל­אים\" ובאופן ד\"חסרים\", יש מקום ל­תמוה: כיון שעיבורה של רבקה הי' מתוך צער גדול (יותר גם מהצער ה­כללי ד\"הרבה ארבה עצבונך והרונך\"<sup data-n=\"932\">12</sup>), וכמ\"ש<sup data-n=\"933\">13</sup> \"ויתרוצצו הבנים בקרבה (עד ש)ותאמר אם כן למה זה אנכי\", ובפרש\"י \"ותאמר אם כן גדול צער העבור, למה זה אנכי מתאוה ומתפללת על הריון\" — מדוע סיבב הקב\"ה שצדקת זו תסבול צער הריון משך זמן רב כ\"כ, ולא תלד לפני שמלאו ימי', לז' חדשים?\nוכדי ליישב שאלות אלו ממשיך רש\"י בד\"ה שלאח\"ז \"והנה תומם — חסר, וב­תמר תאומים מלא לפי ששניהם צדיקים, אבל כאן אחד צדיק ואחד רשע\". כלו­מר: לאחרי שרואים שהכתוב מחלק בין שתי הלידות דרבקה ותמר כדי ללמד שזו למלאים וזו לחסרים — מסתבר לומר שיש להשוות ולדייק גם בשאר ה­שינויים שביניהם, שכאן כתיב \"תומם חסר ובתמר תאומים מלא\" — כי בזה מודגש, שכל כוונת הכתוב כאן היא ל­השוות את שתי הלידות ולהדגיש את ה­שינויים ביניהן, דאף ששתיהן ילדו תאו­מים, מ\"מ הי' שינוי עיקרי ביניהן.\nובזה מתורצות השאלות דלעיל: ה­תמי' מדוע דוקא ברבקה נאמר היתור ד\"וימלאו ימי'\" (ללמדנו שגבי תמר היתה הלידה באופן ד\"לא מלאו ימי'\"), וגם הטעם וסיבת השינוי וההפרש ביניהן (ש­זו למלאים וזו לחסרים) — שכ\"ז מתיישב בשינוי השני שביניהן, שכאן \"תומם חסר, ובתמר תאומים מלא\" — \"לפי ש(שם, בתמר) שניהם צדיקים אבל כאן אחד צדיק ואחד רשע\", כלומר: כיון שבלידת תמר היו שניהם צדיקים, לכן זכתה<sup data-n=\"934\">14</sup>",[["929","10","והטעם שהוצרך רש\"י לפרשו עוה\"פ (אף שמובן מפירושו כאן) — ראה לקמן סעיף ו."],["930","11","וישב לח, ג­ה."],["927","8","ראה מעשה ה' פרשתנו (רפכ\"ז). נזר הקודש (השלם) לב\"ר פרשתנו שם. באר בשדה על פרש\"י כאן."],["932","12","בראשית ג, טז וברש\"י שם."],["933","13","פרשתנו כה, כב. וראה ראב\"ע שם."],["934","14","ובאמרי שפר כאן (וכן בצידה לדרך וישב שם), דכיון ששניהם צדיקים מיהר הקב\"ה להביא צדיקים לעולם, משא\"כ ברבקה שהי' אחד רשע."]]],[1301410177,"שיוקל לה צער הריון וילדתם לז', משא\"כ רבקה שאחד מבני' הי' רשע — לא זכתה<sup data-n=\"934\">14</sup> לכך, ולכן \"וימלאו ימי' ל­לדת\".\nועפ\"ז מיושב ג\"כ — קרא זה ד­\"וימלאו ימי' גו' והנה תומם בבטנה\" למה לי? הרי כבר ידעה רבקה מזה, כמפורש לפנ\"ז \"ויתרוצצו הבנים גו' ויאמר ה' לה שני גוים בבטנך ושני לאומים גו'\"<sup data-n=\"936\">15</sup>, ומה מחדש כאן הכתוב<sup data-n=\"937\">16</sup>? וע\"פ הנ\"ל מובן, כי מ\"ש \"והנה תומם בבטנה\" הוא רק נתינת טעם<sup data-n=\"938\">17</sup> על \"וימלאו ימי' ללדת\", דמה שילדה למלאים ולא לז' כמו תמר הוא מפני ש\"תומם — חסר — בבטנה\"<sup data-n=\"939\">18</sup>.\nה. ע\"פ הנ\"ל יומתק עוד דיוק בלשון רש\"י כאן, שמסיים \"אבל בתמר. . כי לז' חדשים ילדתם\", ולא כתב בקיצור (ע\"ד לשון המדרש כאן, וכן הוא לשון רש\"י עצמו בפ' וישב, כנ\"ל) \"כי לחסרים ילדתם\"?\nבפשטות יש לומר, שרש\"י לא נקט כאן \"לחסרים\" היות שאין זו לשון ברו­רה (ל\"בן חמש למקרא\"), ולכן מפרש כאן שילדה לז'<sup data-n=\"940\">19</sup>, ובפ' וישב מקצר וכ' \"לחסרים\" — כי סומך על פירושו כאן<sup data-n=\"941\">20</sup>.\nאבל עדיין אינו מיושב כל צרכו, כי בתיבת \"חסרים\" מצינו (במפרשים) שני פירושים: א) כפרש\"י — לידה לז' חד­שים<sup data-n=\"942\">21</sup>, ב) שלא היו ט' חדשים שלמים (ו­כמ\"ד שגם היולדת לט' יולדת למקו­טעין)<sup data-n=\"943\">22</sup>. וא\"כ מהו הטעם שרש\"י מכריע כאן שהכוונה היא ללידה לז' חדשים?\nוגם אם יש איזה הכרח לזה (ממק\"א) — למה לו לרש\"י להכריע ולהכנס כאן לפרטי החילוקים שבדבר, אם החסרון הי' בימים בלבד, או חסרון בחדשים — \"לז' חדשים ילדתם\"?\nאמנם ע\"פ משנת\"ל בביאור המשך שני פירושי רש\"י י\"ל, שזוהי הקדמה לדבור השני בפרש\"י, שבו מדייק \"תומם חסר\", שההכרח לדייק כן הוא מפני ה­קושי ב\"וימלאו ימי'\", שרבקה לא ילדה",[["934","14","ובאמרי שפר כאן (וכן בצידה לדרך וישב שם), דכיון ששניהם צדיקים מיהר הקב\"ה להביא צדיקים לעולם, משא\"כ ברבקה שהי' אחד רשע."],["936","15","כה, כב­כג.\nוגם זה ש\"תומם חסר. . אחד צדיק ואחד רשע\" אינו חידוש, כמובן מפרש\"י עה\"פ \"ויתרוצצו הבנים גו'\", וכן מדברי ה' \"שני גוים גו' ושני לאומים גו' ולאום מלאום גו'\"."],["937","16","ובפרט שהכתוב מדייק \"והנה תומם\" ש­משמעו חידוש (רשב\"ם כאן)."],["938","17","ואולי זהו טעמו של רש\"י שמעתיק בהד\"ה גם תיבת \"והנה\" (וכן הד\"ה בפרש\"י וישב שם \"והנה תאומים\") — להדגיש שפירוש \"תומם חסר\" הוא המשך (ונתינת טעם) ל\"וימלאו ימי'\"."],["939","18","ועפ\"ז מובן טעם הוספת תיבת \"בבטנה\" (ש­לכאורה מיותרת היא. וראה ספורנו כאן) — להדגיש, שהחסרון (ד\"אחד רשע\") נגע גם ברבקה עצמה (שלכן סבלה צער העיבור כו'), כיון ש\"הנה תומם בבטנה\"."],["940","19","ולהעיר שהענין דלידה לז' הובא ברש\"י ישן לעיל (וירא כא, ב)."],["941","20","וי\"ל שסמיך גם על פירושו בפ' וישב שם (לח, כד) ד\"ה כמשלש חדשים — וע\"פ פי' הרא\"ם שם, דמ\"ש רש\"י \"רובו של ראשון ורובו של אחרון ואמצעי שלם\" (ולא פי' ג' חדשים ממש) היינו משום שתמר ילדה לז', וזהו שליש ימי עיבורה. ע\"ש. וכבר האריכו המפרשים בדברי הרא\"ם. ואכ\"מ."],["942","21","וחסרים היינו \"לחדשים חסרים\" (פי' ה­מיוחס לרש\"י לב\"ר פפ\"ה שם). וראה מדרש לקח טוב כאן \"וימלאו ימי' ללדת — לעיבור תשעה\"."],["943","22","ראה נזר הקודש (השלם) לב\"ר פפ\"ה, יא (סד\"ה לא סוף). מהרז\"וו ורש\"ש לב\"ר פרשתנו שם. — ולכאורה כ\"ה להתיב\"ע כאן, שמפרש \"וימלאו\" מאתים ושבעים יום — דהיינו מלאים בימים (ולא רק לחדשים), שמזה מובן לכאורה, שחסרים דתמר היינו בימים, ט' מקוטעין."]]],[1301410178,"לז' כמו תמר, וסבלה צער עיבור שני חדשים יתרים, ועכצ\"ל שזהו לפי שהי' כאן \"חסר\" וחסרון — \"כאן אחד צדיק ואחד רשע\".\nו. אבל עדיין צ\"ב בפרש\"י בפ' וישב:\nלאחרי שכבר פירש בפרשתנו ה­הפרש בין שתי הלידות [ובשני הפרטים: זמן הלידה — מלאים או חסרים; ההפרש בהנולדים — \"תומם חסר\" לפי שאחד רשע, או תאומים מלא לפי ששניהם צדיקים] — מדוע חזר רש\"י ופירש כ\"ז עוה\"פ בפ' וישב?\nויש לומר הביאור בזה: כשלומדים בפ' וישב פרטי הסיפור אודות עיבורה של תמר — מתעוררת תמי' גדולה: ה­עיבור דרבקה הי' בתכלית הצניעות (ונוסף לזה שבא כתוצאה מתפלתם של צדיקים<sup data-n=\"944\">23</sup>), ואילו עיבורה של תמר הי' באופן הפכי<sup data-n=\"945\">24</sup> — וכיצד יתכן שרבקה סבלה בצער העיבור ימים (וחדשים) מלאים, ותמר ילדתם \"לחסרים\", לז' חד­שים?\nולכן הוצרך רש\"י לחזור ולהדגיש בפ' וישב, שלמרות אופן עיבורה של תמר, הפירוש ד\"ויהי בעת לדתה\" הוא \"לחסרים\" (בניגוד לרבקה שהי' \"ל­מלאים\") — וטעם הדבר, שזהו מצד ה­נולדים, כהמשך הכתוב \"והנה תאומים בבטנה\" — \"מלא ולהלן תומם חסר לפי שהאחד רשע אבל אלו שניהם צדיקים\".\nז. אמנם לכאורה ענין זה דורש בי­אור — איך יתכן, שדוקא מהריון ד­רבקה, שהי' בתכלית הצניעות והקדושה, נולדו \"תומם חסר\", \"אחד צדיק ואחד רשע\"?\nויש לומר בזה (ע\"פ פנימיות הענינים) ע\"פ משנ\"ת במק\"א<sup data-n=\"946\">25</sup> בביאור מחז\"ל<sup data-n=\"947\">26</sup> (והובא בפרש\"י) עה\"פ<sup data-n=\"948\">27</sup> \"ויתרוצצו ה­בנים בקרבה\", שכבר במעי אמו הי' עשו \"רץ\" לעבודה זרה — דלכאורה תמוה, כיצד יתכן שבנו של יצחק ורבקה, ש­נולד בתכלית הקדושה והטהרה, תהי' לו משיכה בטבע לעבודה זרה, באופן שזה הי' טבע נפשו עוד קודם שנולד, גם בהיותו במעי אמו (\"תחומה\" של רבקה)?\nונת' בזה, שזה שנולד עשו בטבע כזה הי' כדי שיוכל להגיע למעלת \"הכובש את יצרו\", וכמבואר בארוכה בשמונה פרקים להרמב\"ם<sup data-n=\"949\">28</sup> אודות שני הסוגים בעובדי ה' — \"החסיד המעולה\" שמלכת­חילה אין בו נטיות לרע כו' ומתאווה רק לטוב, ו\"הכובש את יצרו\" ש\"מתאווה אל הפעולות הרעות. . ויכבוש את יצרו\". וכן הוא בנוגע לעשו, שזה שנולד בטבע להיות \"רץ\" לעבודה זרה, היינו משום שהיו לו הכחות הרוחניים הדרושים להיות \"כובש את יצרו\", ואם הי' ממלא כוונה זו הרי לא זו בלבד שהי' שווה ליעקב, אלא אדרבה, כמבואר ברמב\"ם שם, \"הכובש את יצרו\" הוא \"יותר חשוב ויותר שלם\" מ\"החסיד המעולה\".\nומזה מובן גם בנוגע ללשון רש\"י עה\"פ \"והנה תומם בבטנה\" — ש\"כאן אחד צדיק ואחד רשע\", שאין הכוונה רשע",[["944","23","פרשתנו כה, כא וברש\"י."],["945","24","ואף שתמר לש\"ש נתכוונה (ראה רש\"י וישב לח, יד. וברש\"י שם, טו (וכן שם, כו) \"בבית חמי' היתה צנועה\") — מ\"מ, באופן גלוי \"הפקירה עצמה\" (ל' רש\"י שם לח, יד)."],["946","25","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201109\" data-slug=\"likkutei-sichot\" data-id=\"1300201109\">לקו\"ש ח\"כ ע' 109</a> ואילך."],["947","26","ב\"ר פס\"ג, ו. זהר פרשתנו קלט, רע\"א."],["948","27","כה, כב."],["949","28","פ\"ו."]]],[1301410179,"בפועל, אלא שנולד בטבע של נטי' ל­רע<sup data-n=\"950\">29</sup>, אבל ביחד עם זה ניתנו לו הכחות הדרושים לכבוש את יצרו.\nוזהו גם הקשר הפנימי בין שני הענינים שבכתוב זה — (א) \"וימלאו ימי' ללדת\", לידה למלאים (ולא לז' חדשים כבתמר), (ב) \"תומם חסר\" לפי ש\"אחד צדיק ואחד רשע\" (ולא כתמר ששניהם צדיקים) — ששניהם תלויים זב\"ז למעל­יותא: \"וימלאו ימי'\" מורה בפשטות על ענין של שלימות (היפך לידה \"לחס­רים\"), וענין השלימות הוא בכך<sup data-n=\"951\">30</sup> שמ­הריון זה היו \"תומם חסר. . אחד צדיק ואחד רשע\", שזוהי תכלית השלימות, האיחוד דשתי המעלות ד\"החסיד המ­עולה\" ו\"הכובש את יצרו\".\n[ובעומק יותר יש לומר, שזה ש\"תומם חסר\" (שיש כאן ענין של חסרון) היינו רק מצד הנולדים, יעקב ועשו, שאצל עשו הי' טבע של רע, משא\"כ מצד רבקה אין כאן שום חסרון, ואצלה יש רק ענין של \"מלאים\" ושלימות (\"וימלאו ימי'\"), כי מצדה אין כאן שום ענין של רע (ב­פועל), אלא רק המעלה והעילוי<sup data-n=\"952\">31</sup> הבא על ידי העבודה ד\"כובש את יצרו\"].\nויש לומר, שזהו גם הטעם (הפנימי) שכבר אצל רבקה מרמז הכתוב ע\"ד לידת תמר \"ששניהם צדיקים\" — כי ביטול הרע של עשו (שזהו תיקונו של עשו) יבוא בפועל על ידי \"תולדות פרץ\" (בן תמר), משיח צדקנו, כשיקויים ה­יעוד<sup data-n=\"953\">32</sup> \"ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה\"<sup data-n=\"954\">33</sup>, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ תולדות תשד\"מ, ש\"פ ראה תשמ\"ג) </span>",[["950","29","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יח, סע\"א</a>). פכ\"ז (לד, א)."],["951","30","להעיר מנזר הקודש (השלם) לב\"ר פרשתנו שם, שזה שהיו מלאים בא להורות שהי' הבירור והזיכוך (דימי העיבור) בשלימות, שעשו קלט כל הזוהמא כו', ועי\"ז יצא יעקב נקי וברור בלא עירוב הפסולת כו'. ע\"ש."],["952","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201112\" data-slug=\"likkutei-sichot\" data-id=\"1300201112\">לקו\"ש שם ע' 112</a>."],["953","32","עובדי' א, כא."],["954","33","ולהעיר שמשיח אתא לאתבא צדיקייא בתיובתא (לקו\"ת שמע\"צ צב, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">שה\"ש נ, סע\"ב</a>. ועוד. וראה זח\"ג קנג, ב). — וראה לקמן ע' 188."]]],[1301410180,"<h3>שיחה ג</h3>\nא. ברמב\"ן על התורה<sup data-n=\"955\">1</sup> כ' ע\"ד ה­בארות דיצחק: \"יספר הכתוב ויאריך בענין הבארות ואין בפשוטי הספור תוע­לת ולא כבוד גדול ליצחק, והוא ואביו עשו אותם בשוה, אבל יש בדבר ענין נסתר בתוכו כי בא<sup data-n=\"956\">2</sup> להודיע דבר ה­עתיד, כי באר מים חיים<sup data-n=\"957\">3</sup> ירמוז לבית אלקים אשר יעשו בניו של יצחק ולכן הזכיר<sup data-n=\"957\">3</sup> באר מ\"ח כמו שאמר<sup data-n=\"959\">4</sup> מקור מים חיים את ה', וקרא הראשון עשק ירמוז לבית הראשון. . והשני קרא שמה שטנה. . והוא הבית השני. . והשלישי קרא רחובות הוא הבית העתיד שיבנה במהרה בימינו והוא יעשה בלא ריב ומצה והא­ל ירחיב את גבולנו. . וכתיב בבית ה­שלישי<sup data-n=\"960\">5</sup> ורחבה ונסבה למעלה למעלה ופרינו<sup data-n=\"961\">6</sup> בארץ\".\nוהנה הרמזים ע\"ד ג' בתי המקדש אצל האבות מצינו גם במ\"א, כדאיתא ב­ספרי<sup data-n=\"962\">7</sup> (ובמדרש<sup data-n=\"963\">8</sup>) ש\"כן אתה מוצא באב­רהם שראה אותו בנוי וראה אותו חרב וראה אותו. . בנוי ומשוכלל לעת\"ל (כמש\"נ<sup data-n=\"964\">9</sup> \"ויקרא אברהם שם המקום ה­הוא ה' יראה. . יראה\"), וכן אתה מוצא ביצחק שראה אותו בנוי [וראה אותו חרב וראה אותו בנוי] ומשוכלל לעתיד לבוא (כמש\"נ<sup data-n=\"965\">10</sup> \"ראה ריח בני כריח שדה אשר ברכו ה'\"). . וכן אתה מוצא ביעקב שראה אותו בנוי וראה אותו חרב וראה אותו בנוי ומשוכלל לעולם הבא (כ­מש\"נ<sup data-n=\"966\">11</sup> \"מה נורא המקום הזה אין זה כי אם בית אלקים\")\"<sup data-n=\"967\">12</sup>.\nאולם י\"ל שברמז הבארות המבואר ברמב\"ן יש חידוש לגבי הראי' דבתי ה­מקדש של האבות המרומזת בכתוב (כדרשת הספרי כו') [בנוסף לעצם הענין, שבפירושו של הרמב\"ן מוסבר סיפור ארוך בתורה ש\"אין בפשוטי הספור תוע­לת\"]:\nא) הרמז שבספרי (ומדרש) משמיענו זה רק באופן כללי \"ראה אותו בנוי וחרב ובנוי וכו'\", מבלי לפרש ולפרט שראו את ביהמ\"ק הא' הב'<sup data-n=\"968\">13</sup> והג'<sup data-n=\"969\">14</sup>;",[["955","1","פרשתנו כז, כ. הובא ברבינו בחיי (שם, יט) בשינוי לשון קצת. ובדרשות ר\"י אבן שועיב פרשתנו שם — הובא עד\"ז בשם מדרש. וראה גם בארוכה כלי יקר שם."],["956","2","בבחיי כאן: אבל טעם הספור לפי שהם רמז על העתיד. ובדרשות אבן שועיב שם \"כי כל ענייני האבות וספורים ומעשיהם הכל רמז לבנים\"."],["957","3","פרשתנו שם, יט."],["957","3","פרשתנו שם, יט."],["959","4","ירמי' יז, יג."],["960","5","יחזקאל מא, ז."],["961","6","פרשתנו כו, כב."],["962","7","ברכה לג, יב."],["963","8","ב\"ר פנ\"ו, יו\"ד (באברהם). ספס\"ה (ביצחק). פס\"ט, ז (ביעקב)."],["964","9","וירא כב, יד."],["965","10","פרשתנו כז, כז."],["966","11","ויצא כח, יז."],["967","12","וראה השינויים והגירסאות בדפוסים שונים דהספרי ובב\"ר שם."],["968","13","בב\"ר פנ\"ו שם לפנינו (באברהם): חרב ובנוי חרב ובנוי. . בנוי ומשוכלל לעת\"ל. אבל במת\"כ ויפ\"ת שם, שהגירסא הנכונה היא \"בנוי וחרב ובנוי (. . ומשוכלל לעת\"ל)\" — כמ\"ש ספס\"ה ופס\"ט שם."],["969","14","ובפשטות מפרשים (במפרשי המדרש שם) שקאי על בית הא' ובית הג'. אבל ראה נזר הקדש ספס\"ה ופס\"ט שם. אלשיך שבהערה 57. וראה לקמן הערה 58."]]],[1301410181,"משא\"כ ברמז הבארות מפורטים כל ג' בתי המקדש (המרומזים בתוכן שמותיהם של הבארות — עשק, שטנה ורחובות, כמבואר ברמב\"ן<sup data-n=\"970\">15</sup>).\nב) בספרי (ומדרש) הרמז הוא רק שה­אבות ראו את בתי המקדש, משא\"כ בהך דהבארות ה\"ז בבחי' \"מעשה אבות סימן לבנים\"<sup data-n=\"971\">16</sup>, שמעשה יצחק בחפירת ג' ה­בארות הי' סימן וגרם<sup data-n=\"972\">17</sup> — נתינת כח<sup data-n=\"973\">18</sup> — לעבודת הבנים, הבנין דג' בתי מקדש.\nב. ויש לבאר זה ע\"פ הידוע שכל מעשי האבות, ובפרט המפורשים בתורה, ה\"ה (ככל עניני התורה) בתכלית הדיוק. וא\"כ מובן שזה שג' המקדשות נרמזים במעשי אבות גבי יצחק דוקא, אף ש­מצינו (כנ\"ל) שכל האבות ראו ביהמ\"ק בנוי וחרב ובנוי, הוא לפי שמדובר כאן בענין מיוחד שבביהמ\"ק השייך ליצחק דוקא.\nויש לומר, שענין זה מודגש בזה שב­מעשה יצחק יש רמז פרטי לכל בית מקדש בפ\"ע, ולא באופן כללי \"בנוי וחרב ובנוי\" (כמו בזה שהאבות ראו ה­ביהמ\"ק), כי המדובר כאן אינו בענין ה­שווה בכל בתי המקדש אלא בענינם ותוכנם המיוחד של כל אחד מהם, הבא כתוצאה מזה שכל אחד נעשה ונבנה באופן שונה מהשנים, ולכן נרמז דוקא (לא בזה שראו את ביהמ\"ק, אלא) ב­מעשה האבות — ובמעשה אבות גופא — בחפירת הבארות דיצחק.\nג. ויובן זה בהקדם תוס' ביאור בה­שייכות בין בתי המקדש לחפירת בארות דוקא:\nבמקוואות מצינו<sup data-n=\"974\">19</sup> (בכללות) שני אופ­נים: מקוה מים — הנעשה בידי אדם, ומעין שהוא בידי שמים, ואין בו תפיסת ידי אדם.\nבנוגע לבארות הנ\"ל מצינו בזה: הם נעשו על ידי חפירת האדם בעבודה ויגיעה, ולאידך — נביעת המים בהבאר (שזהו עיקר ענינו) אינה באה ע\"י פעולת האדם, אלא שעל ידי עבודתו בחפירת והסרת העפר פורצים המים הנמצאים תחת האדמה בתוך הבאר<sup data-n=\"975\">20</sup>.\nולהעיר שזה נוגע להלכה — \"ד­בארות העשויים בידי אדם שמים נובעים מהם אף ע\"פ שאין מימיהם יוצאין לחוץ",[["970","15","וראה של\"ה רפז, א."],["971","16","ראה תנחומא לך ט. ועד\"ז בב\"ר פ\"מ, ו. וראה רמב\"ן לך יב, ו. יב, י. יד, א. פרשתנו כו, א. וישלח לב, ד."],["972","17","וע\"ד שמצינו בנוגע לסימני טהרה וטומאה, דלדעת הרמב\"ם \"הסימנים (בבהמה) הם הגורמים הטהרה והטומאה כו' (אבל סימני עופות וסימני חי'. . רק הוי סימן (המברר) איזהו הטהור כו')\" — צפע\"נ על הרמב\"ם הל' מאכלות אסורות פ\"א ה\"א.\nבמו\"נ ח\"ג פמ\"ח: דאלו הסימנים (בבהמות ודגים) אין מציאותם סבת ההיתר כו' אמנם הם סימן יוודע בו המין המשובח מן המין המגונה (וכ\"כ שו\"ת מהרי\"ט ח\"א סנ\"א). אבל (נוסף ע\"ז שאין הכרח שטעם המצוה כפי שהוא במו\"נ הוא בהתאם לשיטת הרמב\"ם בהלכה בספר היד (וכיו\"ב), וכפי שמצינו בכ\"מ — הרי) תוכן הענין במו\"נ אינו שייך לכאורה לנדו\"ד. ואכ\"מ."],["973","18","כמבואר ברמב\"ן שבהערה 16."],["974","19","ראה מקואות פ\"א. טושו\"ע יו\"ד סר\"א."],["975","20","ראה בביאור מעלת באר וחפירת באר (והשייכות ליצחק דוקא) — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א פרשתנו (כ, ב</a>. שם, ד). דרושי אז ישיר גו' עלי באר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380567\" data-slug=\"likkutei-torah\" data-id=\"4001380567\">לקו\"ת חקת (סב, ד</a> ואילך), <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830132\" data-slug=\"or-hatorah-hb\" data-id=\"8158830132\">אוה\"ת שם</a> (ראה ס' הליקוטים דא\"ח — דהצ\"צ — ערך באר (ושם אות ח)), ד\"ה ואלה תול­דות תרח\"ץ (נאמר לפני יובל שנים<sup data-n=\"e23\">*</sup>). סה\"מ תש\"ב ע' 129 וע' 132 ואילך."],["e23","*","משנת הופעת השיחה — תשמ\"ח. המו\"ל."]]],[1301410182,"דין מעין גמור יש לו\"<sup data-n=\"976\">21</sup>, כי \"אין<sup data-n=\"977\">22</sup> ב­הווית המים שום תפיסת ידי אדם אלא שחפר בקרקע כדי לגלות המים (אע\"ג דע\"י אדם נתגלו המים) פשיטא דדין מעיין גמור יש לו\"<sup data-n=\"978\">23</sup>.\nוי\"ל שאותו הדבר הוא בנוגע לבית המקדש ובנינו: תכליתה של מצות ע­שיית המשכן וביהמ\"ק הוא — \"ועשו לי מקדש ושכנתי בתוכם\"<sup data-n=\"979\">24</sup> — תוכנם הוא השכינה של הוי' שבהם (שבאה מ­שמיא)<sup data-n=\"980\">25</sup>, ויחד עם זה נצטווינו \"ועשו לי מקדש\", וצ\"ל לפני ה\"ושכנתי\" עשיית ופעולת האדם — \"ועשו\"; וי\"ל יתירה מזו: חיוב זה של מעשה האדם אינו רק על הבני', והוי (רק) הכנה לקדושה החלה לאחרי זה בדרך ממילא, אלא נצטווינו \"ועשו לי מקדש\", שגם חלות הקדושה על המשכן והביהמ\"ק באה ע\"י מעשה בנ\"י (כדלקמן) —\nע\"ד חפירת הבארות, שאף שהתהוות עיקר הבאר (המים) הוא בידי שמים<sup data-n=\"981\">26</sup>, מ\"מ הכתוב מקשר זה עם פעולת ה­חפירה של האדם<sup data-n=\"982\">27</sup>. והחפירה עושה ה­בעלות של החופר על המים, \"לנו המים\"<sup data-n=\"957\">3</sup>.\nד. ויש לומר, שגדר זה במצות בנין \"מקדש\" — שבנינו וקדושתו צ\"ל ע\"י מעשה בנ\"י דוקא — נוגע גם להלכה:\nא) פסק הרמב\"ם<sup data-n=\"984\">28</sup> \"הכל חייבין לב­נות ולסעד בעצמן ובממונם אנשים ו­נשים כמקדש המדבר\". ויש לעיין ב­תוכנו של חיוב זה, שהרי מצות בנין \"מקדש\" היא מהמצוות שהן חובת הצבור — ולא חובתו של כל איש ואיש<sup data-n=\"985\">29</sup> — ומה הפירוש ד\"הכל חייבין לבנות כו'\"? ועוד — ידועה השקו\"ט<sup data-n=\"986\">30</sup> בהא דנשים חייבות",[["976","21","ב\"י יו\"ד שם (קרוב לתחלתו) ד\"ה כתב מהרי\"ק. וש\"נ. וכ\"ה להלכה בלבוש שם סוס\"ב. ש\"ך שם סק\"א. ועוד."],["977","22","שו\"ת מהרי\"ק<sup data-n=\"e24\">*</sup> סנ\"ו. ע\"ש בארוכה."],["978","23","ע\"ש במהרי\"ק (וכ\"ה בלבוש שם) שבאר יש לו דין (לא רק כמעין סתם שמימיו מועטין כו' — ראה מקואות שם מ\"ו — אלא) כמים חיים, שגם זב כו' טובל בו.\nבשו\"ת משכנות יעקב יו\"ד סמ\"ה — בהמשך ל­דברי מהרי\"ק: ומקרא מלא הוא ויחפרו עבדי יצחק כו' וימצאו שם באר מים חיים, הרי להדיא דבאר חפורה מקרי מים חיים<sup data-n=\"e25\">*</sup>. וראה חי' הצ\"צ למשניות מקואות פ\"א מ\"ו."],["979","24","תרומה כה, ח."],["980","25","ראה רמב\"ן עה\"ת ר\"פ תרומה."],["981","26","ולפני החפירה (משא\"כ בועשו לי מקדש). ולהעיר ממשנ\"ת שכששואבים מים מן המעין, ה­שאיבה ממשיכה מים מן המעין, ובמילא נתוספו מים במקור המעין."],["982","27","ראה סה\"מ תש\"ב שם (וכן ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780186\" data-slug=\"or-hatorah-hb\" data-id=\"8159780186\">אוה\"ת דברים (כרך ו) ע' ב'קפד</a><sup data-n=\"e26\">*</sup>. וראה גם בשאר מקומות שב­הערה 20) \"ההפרש בין מעין ובאר דמעין הוא בידי שמים ואין בו תפיסת ידי אדם כלל. . ובאר הוא שיש בו תפיסת ידי אדם והיינו שנמשך ע\"י עבודה דוקא. . וזהו שגבי באר דוקא נאמר מים חיים\", ע\"ש ענינו ברוחניות."],["957","3","פרשתנו שם, יט."],["984","28","הל' בית הבחירה פ\"א הי\"ב."],["985","29","סהמ\"צ להרמב\"ם בסוף חלק המ\"ע. ועד\"ז בחינוך מצוה צה (בסופה): וזו מן המצות שאינן מוטלות על יחיד כ\"א על הצבור כולן."],["986","30","צפע\"נ הפלאה בהשמטות (נד, א. וראה גם צפע\"נ מהד\"ת ג, ג). וראה גם שו\"ת בית יצחק או\"ח ס\"ג אות ה; ז ואילך. ועוד. וראה לקו\"ש חט\"ז ע' 454. וש\"נ."],["e24","*","הובא ונתבאר (ע\"ד החסידות) ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830193\" data-slug=\"or-hatorah-hb\" data-id=\"8158830193\">אוה\"ת חקת ע' תתעט</a> ואילך."],["e25","*","במשכנות יעקב שם (הובא בפתחי תשובה שם סקכ\"ח) דאא\"פ לומר כן בכל בארות דלא בכל הבארות נמצאים מים חיים ויש כמה בארות שהמים שבהם נובעים מן הנהר שקרוב להם דרך גידי הארץ. וראה חי' הצ\"צ למקואות שם. שו\"ת הצ\"צ יו\"ד סקס\"ז. ובהנסמן בדרכי תשובה שם ס\"ק רטו. ואכ\"מ."],["e26","*","ושם, ש\"לכן נק' השראת השכינה למטה במשכן ובתי מקדשות ודירה בתחתונים לעתיד בשם באר מים חיים ע\"י אתעדל\"ת דוקא\"."]]],[1301410183,"לבנות ולסעד בעצמם כו' (דכתיב<sup data-n=\"987\">31</sup> וי­באו האנשים על הנשים וכתיב<sup data-n=\"988\">32</sup> וכל אשה חכמת לב בידי' טוו<sup data-n=\"989\">33</sup>) — הרי בנין המקדש הוא מ\"ע שהזמן גרמא, ד\"אין<sup data-n=\"990\">34</sup> בונין את המקדש בלילה שנאמר<sup data-n=\"991\">35</sup> וביום הקים את המשכן, ביום מקימין לא ב­לילה\".\nוי\"ל שב\"הכל חייבין כו'\" אין כוונתו של הרמב\"ם לומר שזהו חובת גברא, אלא שהוא דין בחפצא דהמקדש, וכעין דין הסמוך באותה ההלכה: \"אין מבטלין תינוקות של בית רבן לבנין\", דאף ש­כתבו כבר בהל' ת\"ת<sup data-n=\"992\">36</sup>, חזר וכפל הדין כאן ללמדנו, דמה שאין מבטלין תינוקות של בית רבן הוא לא רק מחמת חיוב ת\"ת שאינה נדחה אפילו בשביל בנין בית המקדש, אלא שזהו דין בבנין ביהמ\"ק<sup data-n=\"993\">*36</sup>, שגם מצד ביהמ\"ק אין מקום לבטל תשב\"ר לבנין (ובפרט את\"ל — שהלימוד של תשב\"ר מסייע בקיום בנין הבית) — עד\"ז הוא בהדין ד\"הכל חייבין לבנות ולסעד בעצמן ובממונם אנשים ונשים\", שאינו חובת גברא לקיים מצות ועשו לי מקדש (שעל הציבור), אלא שהוא חיוב מצד המקדש, שגדר בנין ה­מקדש מחייב שבנינו יהי' על ידי הצי­בור \"ועשו\" עשיית כלל ישראל (ולכן שייך זה לכל ישראל, אנשים ונשים).\nב) כשם שהוא בנוגע למעשה הבנין, כן הוא גם בשייכות למקום הבנין וצו­רתו וכו', שבזה תלוי' קדושתו — דאף ש\"ושכנתי\" דהקדושה במקום זה באה משמיא, צ\"ל בזה מקודם קיום מצות \"ועשו\", הכנה ע\"י האדם,\nוי\"ל שכולל יתרה מזה \"שידרוש\", יתייגע למצוא את המקום וכו'. וכדאיתא בספרי<sup data-n=\"994\">37</sup> \"יכול תמתין עד שיאמר לך נביא ת\"ל לשכנו תדרשו ובאת שמה, דרוש ומוצא<sup data-n=\"995\">38</sup> ואח\"כ יאמר לך הנביא\". והיינו לפי שהמכוון והמטרה של הציווי \"ועשו לי מקדש\" הוא, שהמקדש (לא יהי' מתנת חנם מלמעלה, אלא) יבא ע\"י עשי' ויגיעת האדם, באופן של \"דרוש\"<sup data-n=\"996\">39</sup> — בדוגמת \"באר\", שבא ע\"י תפיסת ידי אדם באופן של עבודה ויגיעה, חפירת בארות.\nה. עפ\"ז מובן החידוש בבתי המקדש על המשכן שעשה משה במדבר, וכן החילוק בין בתי המקדש עצמם:\nבמשכן נאמר<sup data-n=\"997\">40</sup> \"והקמות את המשכן",[["987","31","ויקהל לה, כב."],["988","32","שם, כה."],["989","33","כס\"מ לרמב\"ם שם."],["990","34","רמב\"ם הל' בית הבחירה שם."],["991","35","בהעלותך ט, טו."],["992","36","פ\"ב סה\"ב."],["993","*36","ועד\"ז הוא תוכן שאר הדינים שבהלכה זו ברמב\"ם, לא כ\"כ בחיובי ואיסורי גברא, כ\"א מצד החפצא דמקדש: \"אין בונין את המקדש בלילה שנא' וביום הקים את המשכן ביום מקימין ולא בלילה\" — שלכמה מפרשים (ראה ביאור הרי\"פ פערלא ל­סהמ\"צ רס\"ג עשה יג — קיג, סע\"ב ואילך), אינו מצד האיסור שבדבר, אלא משום הביהמ\"ק, דהקמת לילה פסולה להקרבת היום (ירושלמי יומא פ\"א ה\"א); \"ועוסקין בבנין מעלות השחר עד צאת ה­כוכבים\" — אינו לפי שאז הוא זמן מלאכה של הגברא \"דזמן מלאכה הוא מהנץ ולא מעמוד השחר\" כ\"א הוא \"משום כבוד ביהמ\"ק הוי מקדמי טפי\" (תוד\"ה פועל — ב\"מ פג, ב); \"ואין בנין ב\"ה דוחה יו\"ט\" ג\"כ אינו (רק) משום האיסור שעל הגברא במעשי הבנין, כ\"א מצד החפצא דביהמ\"ק עצמו, שהרי למדוהו מהכ' (קדושים יט, ל) \"את שבתותי תשמרו ומקדשי תיראו (אני ה' כולכם חייבים בכבודי אתם) והמקדש חייבין בכבודי כו'\" (פרש\"י שבועות טו, ב מיבמות ו, א). ואכ\"מ."],["994","37","ראה יב, ה. וראה מלבי\"ם שם."],["995","38","ביל\"ש עה\"פ: דרוש ואתה מוצא."],["996","39","ראה לקו\"ש חל\"ד ע' 203 (וש\"נ) בענין ה\"דרישה\"."],["997","40","תרומה כו, ל."]]],[1301410184,"כמשפטו אשר הראת בהר\", שהקב\"ה הראה למשה סדר הקמתו<sup data-n=\"998\">41</sup>; ונמצא שה­עשי' (\"ועשו\") שבמשכן לא היתה באופן של \"דרוש\", כי הקמתו באה ע\"י מה ש­(למדו ו)הראהו הקב\"ה, ובמילא לא נת­קיים בזה \"ועשו\" בשלימות — עשי' ב­אופן של יגיעה ו\"דרוש\" (ע\"ד חפירת בארות)<sup data-n=\"999\">42</sup>.\nאבל בבית המקדש הא', אף שנאמר בזה \"הכל בכתב מיד ה' עלי השכיל\"<sup data-n=\"1000\">43</sup>, הרי בנין הבית נעשה ע\"י בנ\"א ובריבוי עצום (במספרם ובאריכות הזמן), ועוד זאת — שהבנין נעשה על ידי שלמה ולא על ידי דוד (שאליו היתה הנבואה), וגם בשייכות לדוד שאמר \"הכל בכתב מיד ה' עלי השכיל\", איתא בספרי שם ב­המשך להדרשה הנ\"ל \"לשכנו תדרשו. . דרוש ומוצא ואח\"כ יאמר לך הנביא\" — \"וכן אתה מוצא בדוד<sup data-n=\"1001\">44</sup> זכור ה' לדוד את כל ענותו אשר נשבע לה' נדר ל­אביר יעקב אם אבא באהל ביתי וגו' אם אתן שנת לעיני וגו' עד אמצא מקום לה' משכנות לאביר יעקב\", היינו שדוד הש­תדל והתייגע למצוא את מקום המקדש, ורק אח\"כ נאמר לו מהנביא (כבהמשך הספרי).\nויש לומר, שזהו אחד מהטעמים שה­משכן הי' דירת עראי, כמ\"ש<sup data-n=\"1002\">45</sup> \"לא ישבתי בבית גו' ואהי' מתהלך באהל וב­משכן\", וכלשון הרמב\"ם<sup data-n=\"1003\">46</sup> \"וכבר נתפרש בתורה משכן שעשה משה רבינו והי' לפי שעה\", משא\"כ בית המקדש הי' דירת קבע<sup data-n=\"1004\">47</sup>, וכלשון הרמב\"ם<sup data-n=\"1005\">48</sup> \"כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן כו' ואין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המורי'\" — כי ענין הקביעות דמקדש תלוי בעשיית בנ\"י, באופן ד\"דרוש\" — באופן הכשרת הקדושה כנ\"ל, ובהבנין גדול מאוד בפו­על, וזה הי' (בעיקר) במקדש לא במשכן.\nו. והנה בגדר זה דמקדש, פעולת ועשיית האדם, ישנו עילוי במקדש הב' לגבי המקדש הא':\nא) מעשה הבנין לא בא על ידי הת­גלות (ו\"הראת\" ע\"י) ה' (כבמשכן) או על ידי הוראת נביא (כבבית ראשון) כ\"א על ידי ציווי של כורש<sup data-n=\"1006\">49</sup> (וגם הוא השתתף בהבנין<sup data-n=\"1007\">50</sup>).\nב) גם צורת הבנין לא היתה ברורה כמו בבית הא', וכמ\"ש הרמב\"ם<sup data-n=\"1008\">51</sup> \"(בנין שבנה שלמה כבר מפורש במלכים, וכן) בנין העתיד להבנות אע\"פ שהוא כתוב ביחזקאל אינו מפורש ומבואר, ואנשי בית שני כשבנו בימי עזרא בנוהו כבנין שלמה ומעין דברים המפורשים ב­יחזקאל\"<sup data-n=\"1009\">52</sup>.",[["998","41","ראה פרש\"י ומפרשיו שם. וראה מנחות כט, א. פסיקתא רבתי פ\"כ, ג. זח\"ב קנט, א."],["999","42","ויתרה מזה ע\"פ פרש\"י (פקודי לט, לג — מתנחומא שם יא (בשינויים)) — דעשיית משה היתה בזה ש\"עסוק אתה בידך נראה כמקימו\", והקמת ה­משכן היתה \"מאליו\"."],["1000","43","דה\"א כח, יט. ד\"כל מלאכת התבנית (ש)­הודיעו הקב\"ה כו'\" (פרש\"י סוכה נא, סע\"ב. וראה גם ירושלמי מגילה פ\"א ה\"א ובמפרשים שם)."],["1001","44","תהלים קלב, א­ה. וראה פרש\"י שם: טרח ועמל למצוא לך מקום. . עד שיודע היכן יהי' מקום מקדש."],["1002","45","ש\"ב ז, ו. וראה שהש\"ר פ\"א, טז (ג). תו\"א ר\"פ ויגש."],["1003","46","ריש הל' בית הבחירה."],["1004","47","ראה שהש\"ר שם. תו\"א שם."],["1005","48","הל' ביהב\"ח שם ה\"ג."],["1006","49","עזרא א, א ואילך."],["1007","50","ראה עזרא ו, ד. ר\"ה ד, א — אבל עד\"ז הי' גם בבית שלמה (חירום מלך צור, שבעים אלף נושא סבל וגו' — מ\"א ה, כט. לב. ז, מ. ועוד)."],["1008","51","הל' ביהב\"ח שם ה\"ד."],["1009","52","וראה בארוכה תוי\"ט בפתיחתו למס' מדות."]]],[1301410185,"ונמצא, שבבית שני הרי הדרישה (\"דרוש ומוצא\") של פרטי הבנין היתה יותר מבבית הא' (וי\"ל דשם הי' ה\"דרוש ומוצא\" רק בנוגע למקומו, משא\"כ בבית שני) שהוצרכו לדרוש וכו' בנוגע לפרטי הבנין וצורתו<sup data-n=\"1010\">53</sup>.\nוכיון שענין הקביעות במקדש תלוי במעשה ופעולת בנ\"י, \"ועשו לי מקדש\", באופן של עבודה ויגיעה כנ\"ל, שזה הי' בבית שני יותר מבית ראשון, לכן גם \"גדול יהי' כבוד הבית הזה האחרון מן הראשון\"<sup data-n=\"1011\">54</sup> שהי' גדול בבנין ובשנים<sup data-n=\"1012\">55</sup>, קביעות יותר מבית הראשון.\nועפ\"ז מובן זה שה\"סימן לבנים\" על ג' בתי המקדש הוא במעשה יצחק דוקא (אף שחפירת בארות היתה לפנ\"ז על ידי אברהם, וכמפורש בהכתובים, וכלשון הרמב\"ן \"הוא ואביו עשו אותם בשוה\") — כי עיקר ענין העשי' והיגיעה והעבודה הוא חידושו וענינו של יצחק דוקא, כ­ידוע<sup data-n=\"1013\">56</sup> שענינם של ג' האבות הם ג' ה­עמודים דתורה עבודה וגמ\"ח, אברהם מדתו מדת החסד, יצחק — עבודה, ו­יעקב — תורה, וחסד ותורה הם (בכלל) השפעה מלמעלה, ועבודה היא העלאת והתקרבות האדם לקדושה.\nוי\"ל שמטעם זה (כמבואר ברז\"ל) ה­בית הא' הוא כנגד אברהם והבית הב' כנגד יצחק<sup data-n=\"1014\">57</sup>, כי עיקר הענין ד\"ועשו\", עשיית ועבודת האדם, הי' בבית השני<sup data-n=\"1015\">58</sup> דוקא<sup data-n=\"1016\">59</sup>.\nז. אמנם צריך להבין:\nאיך מתאים משנת\"ל, שעיקר ענין הקביעות שבמקדש קשור ותלוי ב\"ועשו לי מקדש\", מעשה ופעולת האדם דוקא — עם המבואר ברמב\"ן שם, שבאר הג' שלא רבו עלי' היא נגד ביהמ\"ק השלי­שי, שרק עליו נאמר \"ורחבה ונסבה\", שיהי' קיים בקיום נצחי (שזוהי אמיתית ושלימות ענין ה\"קביעות\") — והרי ה­נצחיות של ביהמ\"ק הג' היא לפי שהוא (בלשון הזהר<sup data-n=\"1017\">60</sup>) \"בניינא דקוב\"ה\", וכ­מבואר בבחיי כאן: ומה שהזכיר את ה' בבאר השלישי ולא עשה כן בשתים ה­ראשונות, יתכן לומר טעם מפני שה­ראשונים היו בנין בשר ודם על ידי שלמה וכורש אבל השלישי יהי' מעשה ה' ובנין שמים ולא ישלוט בו חורבן לכך הזכיר בו הש\"י.\nוהיינו, שביהמ\"ק הא' והב', שהם \"בנין בשר ודם\" (\"בניינא דבר נש\") אין בהם ענין הנצחיות, ודוקא ביהמ\"ק הג' שלא יהי' \"בנין בשר ודם\" יהי' בו ענין ה­קביעות והנצחיות בשלימות.",[["1010","53","בשו\"ת חת\"ס יו\"ד סרל\"ו (ועד\"ז באו\"ח סר\"ח ד\"ה עד כאן) שכל השינויים בבית שני היו הכל ע\"פ נביא, ע\"ש (וראה גם אוה\"ח תרומה כה, ט). אבל עפמ\"ש בתוי\"ט שם (ובארוכה בהקדמתו לספר צורת הבית) משמע דלמדו ודרשו כו\"כ, כל מה שיכלו ללמוד ולדרוש מיחזקאל ולא הי' הכל ע\"פ נביא במפורש. וראה גם רד\"ק יחזקאל מ, יג. וראה יומא נא, ב ואילך (רמב\"ם הל' ביהב\"ח פ\"ד ה\"ב) — מה שנסתפק להם בבית שני."],["1011","54","חגי ב, ט."],["1012","55","ב\"ב ג, סע\"א ואילך."],["1013","56","מגלה עמוקות אופן רנ (בסופו). מגלה עמוקות עה\"ת ר\"פ לך. ועוד. ס' הלקוטים — דא\"ח צ\"צ מע' יצחק אות ו'. וש\"נ."],["1014","57","ראה נזר הקודש לב\"ר פס\"ט שם בשם \"מדרשות\". צרור המור פרשתנו כו, יח. אלשיך ויצא כח, יח. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780185\" data-slug=\"or-hatorah-hb\" data-id=\"8159780185\">אוה\"ת דברים (כרך ו) ע' ב'קפג</a>. וש\"נ."],["1015","58","ועפ\"ז יומתק הא דפי' בנזר הקודש (השלם) לב\"ר ספס\"ה שביצחק מרומז גם שהראהו ביהמ\"ק הב'. ע\"ש. וראה תולדות אדם לספרי ברכה שם."],["1016","59","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091026\" data-slug=\"likkutei-sichot\" data-id=\"1300091026\">לקו\"ש ח\"ט ע' 26</a> ואילך. ע' 67 ואילך."],["1017","60","ח\"ג רכא, א. ח\"א כח, א."]]],[1301410186,"בפשטות הטעם בזה הוא: מכיון ש­אדם יש לו תכלה (ובפרט שמשעה שנו­לד מתחיל להתייבש<sup data-n=\"1018\">61</sup>), אין מעשי ידיו נצחיים; ומעשה ה', שהקב\"ה לא שייך בו שום ענין של שינוי ח\"ו, כמ\"ש<sup data-n=\"1019\">62</sup> אני ה' לא שניתי, כן מעשי ידיו הם נצחיים.\nאבל עדיין חסר ביאור: כיצד יתכן, שביהמ\"ק הא' והב' שהי' בהם יותר ענין העשי' וקיום מצוה של ישראל (\"ועשו לי מקדש\") — אין בו עילוי זה (דנצחיות), ובבית הג', שחסר בו לכאורה שלימות קיום מצות \"ועשו לי מקדש\", יהי' בו עילוי זה?\nויש לומר הביאור בזה<sup data-n=\"1020\">63</sup>:\nזה שביהמ\"ק הג' \"יהי' מעשה ה' ובנין שמים ו(לכן) לא ישלוט בו חורבן\" הוא לפי שבא ע\"י מעשה ועבודת בנ\"י ש­לפנ\"ז, במשך (אריכות) זמן הגלות, שזוהי השלימות הנעלית ביותר בענין העשי' ועבודה (וי\"ל — עוד למעלה מהעבודה והעשי' שבבנין ביהמ\"ק הא' והב'). ולכן דוקא עבודה זו גורמת ומביאה לכך שהמקדש יהי' מעשה ה' הקיים בקיום נצחי.\nוע\"ד מחז\"ל<sup data-n=\"1021\">64</sup> (בנוגע לכללות ענין הגאולה העתידה) \"זכו — אחישנה\", דכאשר עבודת ישראל היא בשלימות, \"זכו\", אזי באה הגאולה באופן שונה לגמרי, \"אחישנה\", למעלה מדרך הטבע.\nועד\"ז בנוגע לבנין המקדש דלעתיד — דכיון שבא לאחרי עבודת ישראל במשך אריכות הגלות הזה האחרון<sup data-n=\"1022\">65</sup>, שעי\"ז נזדככו בנ\"י בזיכוך אחר זיכוך, וכפי שרואים שבנ\"י לומדים תורה ומ­קיימים מצוות מתוך מסנ\"פ כפשוטה<sup data-n=\"1023\">66</sup>, וגם במקומות שזיכה הקב\"ה והצליח ש­אין בהם גזירות על בנ\"י, ישנם מניעות ועיכובים מהמלעיגים וצריכים לעמוד בתוקף גדול לא לבוש מפני המלעיגים, ולהתחזק באמונתם ותורתם, גם לעיני העמים — הרי מסירת נפש זו מביאה לידי כך שהקב\"ה בעצמו יבנה את ביהמ\"ק הג'.\nהיינו זה שעשיית האדם (\"ועשו\") פועלת הקביעות בהמקדש הוא מפני שככל שתגדל עשיית האדם — שורה בזה יותר השכינה<sup data-n=\"1024\">67</sup>.\nח. וליתר ביאור:\nשלימות עבודת האדם היא כאשר",[["1018","61","ראה בחיי בראשית א, כח. סה\"מ תשי\"א ע' 142. ובכ\"מ."],["1019","62","מלאכי ג, ו."],["1020","63","תיווך ב' השיטות בבנין הג' אם משיח בונה (כמ\"ש ברמב\"ם הל' מלכים רפי\"א וסופו) או שיגלה ויבוא מן שמים (כדעת רש\"י ר\"ה ל, סע\"א. סוכה מא, סע\"א. תוס' סוכה שם. שבועות טו, ריש ע\"ב ד\"ה אין. ועוד) — ראה לקו\"ש חי\"ח ע' 418 ואילך. חידושים וביאורים בהל' ביהב\"ח סי\"ט. וש\"נ."],["1021","64","סנהדרין צח, א."],["1022","65","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>, שכל תכלית השלימות של ימות המשיח כו' תלוי במעשינו ועבודתינו כל זמן משך הגלות."],["1023","66","ראה ד\"ה אין הקב\"ה בא בטרוניא תרמ\"ח (סה\"מ תרמ\"ח ע' קפו ואילך), תרפ\"ה (סה\"מ תרפ\"ה ע' רנז ואילך); ד\"ה אני ישנה תש\"ט (ובכ\"מ) — המעלה דעבודת בנ\"י בדרא דעקבתא דמשיחא.\nובבי' הענין דמשה הי' עניו מכל האדם גו' ובפרט — מדרא דעקבתא דמשיחא (סה\"מ עטר\"ת ע' תסד ואילך. תש\"ט ע' ה. תש\"י ע' 236 ואילך. ועוד. וראה תו\"א נב, א. מאמרי אדה\"ז — תקס\"ב ח\"א ע' נא)."],["1024","67","עיין גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091028\" data-slug=\"likkutei-sichot\" data-id=\"1300091028\">לקו\"ש ח\"ט ע' 28</a> הערה 26 (ע\"פ לקו\"ת ויקרא ב, ריש ע\"ד) — שב' הענינים תלויים זב\"ז."]]],[1301410187,"עבודתו היא באופן שאינו מחשיב עצמו למציאות בפ\"ע, וכל מעשיו הם מעשיו של הקב\"ה, ושכינה שורה בשלימותה ב­מעשה ידיו. וע\"ד דאיתא בגמ'<sup data-n=\"1025\">68</sup> \"גדולים מעשה צדיקים יותר ממעשה שמים וארץ כו' במעשה ידיהם של צדיקים כתיב<sup data-n=\"1026\">69</sup> מכון לשבתך פעלת ה' מקדש אדנ­י כוננו ידיך\", ופרש\"י<sup data-n=\"1027\">70</sup> \"מקדש מעשה ידי צדיקים הוא\" — ומ\"מ הובא ע\"ז הכתוב \"מקדש אדנ­י כוננו ידיך\", ומבואר בשטה מקובצת<sup data-n=\"1027\">70</sup> שאי\"ז סתירה, כי \"מעשה צדיקים קרי מעשיו של הקב\"ה\"<sup data-n=\"1029\">71</sup>. די\"ל הביאור בזה, שצדיק אינו מציאות בפ\"ע ולכן מעשה ידיו של הצדיק הם הם מעשי ידיו של הקב\"ה<sup data-n=\"1030\">72</sup>.\nויש לומר, שענין זה (שמעשה ידיו של האדם (צדיק) נחשבת מעשה ידיו של הקב\"ה) הוא בעיקר כאשר עבודת האדם היא כעבודת עבד, שע\"פ תורה (תורת אמת) אינו מציאות בפני עצמו, וכל שקנה עבד קנה רבו<sup data-n=\"1031\">73</sup>, עד שכל עבודת העבד נקראת על שם האדון; וכן עבודת העבד — צד השווה בה בכל זמן ובכל מקום (שמזה מוכח שזהו מקורה וכו') היא קבלת עול, לא מפני השגתו במעלת האדון ובתועלת העבודה, או מפני ההרגש בלב אל העבודה, אלא מפני ש­קיבל עליו עול האדון, ועבודתו היא כדי למלאות רצון האדון<sup data-n=\"1032\">74</sup>.\nוזהו החידוש שבבית המקדש הג' לגבי בתי המקדש שלפניו (שלכן דוקא הוא יהי' מעשה ה') — כי אף שגם בבית המקדש הא' והב' הי' עבודה ועשי', מ\"מ, כיון שעבודת השם אז היתה מתוך הבנה והשגה עמוקה בגדלות השם, שמביאה לאהבתו ויראתו ית' כו'<sup data-n=\"1033\">75</sup> ושכל מכסה ומלביש את העצם — הרי היתה העבודה בגלוי עבודה שכליית, מעורבת בזה מציאות האדם (שכלו והרגש לבו), ולכן לא הי' בגלוי \"בניינא דקב\"ה\"; ודוקא על ידי העבודה במשך זמן הגלות, ש­עיקר העבודה היא בדרך קבלת עול מלכות שמים, כעבודת עבד<sup data-n=\"1034\">76</sup>, ה\"ז שלי­מות ואמיתית \"מעשה צדיקים\" שהם מעשה ידיו של הקב\"ה, ולכן ה\"ז פועל בגילוי שהקב\"ה יבנה בית זה, \"ה' יבנה בית\"<sup data-n=\"1035\">77</sup>.\nט. פ' תולדות קוראים בכל שנה ב­סמיכות לראש חודש כסלו (בשבת מבר­כים חודש כסלו (כבשנה זו<sup data-n=\"1036\">*77</sup>) או בימים ראשונים של החודש) — שסיומו וחותמו של חודש זה הוא ימי חנוכה — וגם בהם רואים תוכן ענין הנ\"ל:\nידועים דברי הרמב\"ן<sup data-n=\"1037\">78</sup> במ\"ש הקב\"ה לאהרן<sup data-n=\"1038\">79</sup> \"שלך גדולה משלהם שאתה מדליק ומטיב את הנרות\", שזה קאי על נרות חנוכה, \"שאין בטלים לעולם\", ד­",[["1025","68","כתובות ה, סע\"א."],["1026","69","בשלח טו, יז."],["1027","70","כתובות שם."],["1027","70","כתובות שם."],["1029","71","ומסיים שם \"ורש\"י ז\"ל פי' כפי' בתרא\". היינו לא שקאי על ביהמ\"ק שלמעלה כפי' הא' שם אלא שקאי על ביהמ\"ק שלמטה. וראה בארוכה ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג עשה יג (קיג, א ואילך)."],["1030","72","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161482\" data-slug=\"likkutei-sichot\" data-id=\"1300161482\">לקו\"ש חט\"ז ע' 469</a> ואילך, שזהו הטעם שיש ענין הנצחיות במעשה ידי משה (משכן) ובמעשה ידי דוד (מקדש)."],["1031","73","פסחים פח, ב. קדושין כג, ב."],["1032","74","ראה בארוכה המשך תרס\"ו ע' שכו ואילך."],["1033","75","ראה רמב\"ם הל' יסודי התורה רפ\"ב."],["1034","76","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091073\" data-slug=\"likkutei-sichot\" data-id=\"1300091073\">לקו\"ש ח\"ט ע' 73</a> ואילך. וש\"נ."],["1035","77","ע\"פ תהלים קכז, א (הובא בזח\"א וזח\"ג שם)."],["1036","*77","תשמ\"ח — שנת הדפסת השיחה."],["1037","78","ר\"פ בהעלותך."],["1038","79","תנחומא ופרש\"י שם."]]],[1301410188,"קרבנות הם רק בזמן שבית המקדש קיים, ואילו נרות חנוכה הם גם בזמן גלותנו.\nוהטעם שנרות חנוכה יש בהם ענין הנצחיות, מבואר בכ\"מ, משום שנרות אלו באו על ידי מסירת נפשם דבנ\"י בז­מן החשמונאים, דאף שמלכות יון \"גזרו גזירות על ישראל ובטלו דתם ולא הניחו אותם לעסוק בתורה ובמצות\"<sup data-n=\"1039\">80</sup> מ\"מ מסרו ישראל נפשם<sup data-n=\"1040\">81</sup>.\nוכיון שהנרות באו על ידי שלימות עבודת ישראל, מסירת נפש, לכן אין נרות חנוכה בטלים לעולם, שקיימים הם גם בזמן הגלות.\nאלא שבימי חנוכה נפעלה הנצחיות רק בענין נרות המקדש, אבל לאחרי העבודה באריכות גלות זה האחרון, יהי' כן בנוגע לכללות המקדש, שבנין בית השלישי יהי' בתכלית השלימות, באופן שכולו נק' על שם הקב\"ה, \"ה' יבנה בית\", ויהי' בנין נצחי לעולם, \"מקדש אדנ­י כוננו ידיך\".\n<span data-k=\"q\">(משיחות ש\"פ חיי שרה תש\"ל, תשמ\"ז) </span>",[["1039","80","ל' הרמב\"ם ריש הל' חנוכה."],["1040","81","ראה בארוכה שערי אורה ד\"ה בכ\"ה ב­כסלו פנ\"ג. ושם פנ\"ט, שזוהי עבודה שמלמטה למעלה בבחי' אור חוזר."]]],[1301410189,"<h3>שיחה א</h3>\nא. בסוף הלכות שבת כתב הרמב\"ם: וכל השומר<sup data-n=\"1041\">1</sup> את השבת כהלכתה ומ­כבדה ומענגה כפי כחו כבר מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא, שנאמר<sup data-n=\"1042\">2</sup> אז תתענג על ה' והרכבתיך על במותי ארץ וה­אכלתיך נחלת יעקב אביך כי פי ה' דבר.\nבמפרשים<sup data-n=\"1043\">3</sup> מציינים שמקור דברי ה­רמב\"ם הוא מאמר ר' יוחנן משום רבי יוסי במס' שבת<sup data-n=\"1044\">4</sup> \"כל המענג את השבת נותנין לו נחלה בלי מצרים שנאמר אז תתענג על ה' והרכבתיך על במותי ארץ והאכלתיך נחלת יעקב אביך וגו' (ומ­פרש בגמ') לא כאברהם שכתוב בו<sup data-n=\"1045\">5</sup> קום התהלך בארץ לארכה וגו' ולא כיצחק שכתוב בו<sup data-n=\"1046\">6</sup> כי לך ולזרעך אתן את כל הארצות האל אלא כיעקב שכתוב בו<sup data-n=\"1047\">7</sup> ופרצת ימה וקדמה וצפונה ונגבה\".\nאבל לפי זה אינו מובן מדוע שינה הרמב\"ם מדרשת רז\"ל:\nא) בהגדרת מעשה האדם שעבורו מקבל שכר זה — בגמ' נאמר \"כל המענג את השבת\", והרמב\"ם כתב \"כל השומר את השבת כהלכתה<sup data-n=\"1048\">8</sup> ומכבדה ומענגה כפי כחו\". והיינו שהשכר לפי הרמב\"ם אינו עבור זה שמענג (את השבת) בלבד, אלא ע\"ז שמקיים כל מצות שבת כ­הלכתה<sup data-n=\"1049\">9</sup>.\nב) בהגדרת השכר — כתב רק \"מפו­",[["1041","1","כ\"ה ברמב\"ם לפנינו. ובכת\"י (הובא ב­מהדורת פרענקל \"ילקוט שינויי נוסחאות\") \"כל המשמר\". וראה שבת קיח, ב \"כל המשמר שבת כהלכתו כו'\". וראה לקמן הערה 8."],["1042","2","ישעי' נח, יד."],["1043","3","מגדל עוז כאן. וכן משמע בסמ\"ג סוף מ\"ע ל, שכ' \"אמר רבי יוחנן משום רבי יוסי בפ' כל כתבי כל השומר כו'\", ומעתיק לשון הרמב\"ם כאן! והרי לא מצינו גירסא כזו בגמ' (לפנינו), ועכצ\"ל שמפרש שדברי הרמב\"ם מיוסדים על מרז\"ל זה."],["1044","4","קיח, סע\"א ואילך."],["1045","5","לך יג, יז."],["1046","6","תולדות כו, ג."],["1047","7","פרשתנו כח, יד."],["1048","8","והוא הלשון דר' חייא בר אבא א\"ר יוחנן דלהלן בגמ' שם: כל המשמר שבת כהלכתו אפי' עובד ע\"ז [כדור] אנוש כו'. וראה לקמן הערה 38."],["1049","9","ואף שגם בדברי הגמ' \"כל המענג את ה­שבת\" הכוונה בפשטות ששומר שבת כהלכתה וגם מענג את השבת (קיום מצות שבת כהלכתה בשלי­מות)<sup data-n=\"e27\">*</sup> — הרי מפורש בגמ' \"כל המענג את השבת\", שהשכר (נחלה בלי מצרים) הוא על הפרט של עונג שבת (ולא עבור כללות קיום מצות שבת). וראה ב\"י או\"ח ר\"ס רמב בשם הרי\"א \"דנותנין לו נחלה בלי מצרים הוא מדה כנגד מדה שכשם שהוא מפזר מעות בלא שיעור לצורך שבת כן יתנו לו נחלה בלא שיעור\". וראה גם ב\"ח שם."],["e27","*","וכן משמע בשו\"ע אדה\"ז או\"ח סרמ\"ב סוס\"א שכ' \"כל המענג את השבת שכרו מפורש בקבלה אז תתענג על ה' וגו' ובדברי רז\"ל שמוחלין לו על כל עונותיו וניצול מדינה של גיהנום\", והרי בדברי רז\"ל (שבת קיח, ב) זה שמוחלין לו על כל עונותיו נאמר על \"כל המשמר שבת כהלכתו\", וזה דניצול מדינה של גיהנום מפורש (שם קיח, א) לענין \"כל המקיים שלש סעודות בשבת\". ומשמע דהמענג את השבת כולל הכל. וכן משמע בלבוש שם שמעתיק כל דרשות רז\"ל בשבת שם \"המענג את השבת. . (ומסיים) לגלות שכר השומר שבת כהלכתו בכלליו ובפרטיו\". ע\"ש. אבל מובן, שפרטי השכר תלויים בפרטי העשי', כבפנים ההערה."]]],[1301410190,"רש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא\", אבל השמיט אופן השכר — \"נותנין לו נחלה בלי מצרים\", וכמפורט אח\"כ שהיא נחלת יעקב (לא כאברהם וכיצחק).\nולכאורה משמע מזה, שאין כוונת הרמב\"ם כאן לדרשת הגמרא, אלא לפי­רוש הכתוב כפשוטו<sup data-n=\"1050\">10</sup> [דפירוש הגמרא \"כל המענג כו' נותנין לו נחלה בלי מצרים\" י\"ל שהוא דרש, ואילו כוונת ה­רמב\"ם שכתב \"מפורש\" היא שזהו פשט הכתוב, וכמו שמצינו בכ\"מ שהרמב\"ם מפרש כתוב לפי פשוטו, ולא כפי שדר­שוהו חז\"ל<sup data-n=\"1051\">11</sup>].\nוי\"ל שלכן כתב \"כל השומר את ה­שבת כהלכתה ומכבדה ומענגה כפי כחו\" (ולא (בקיצור) \"כל המענג את ה­שבת\") — כי הכתוב \"אז תתענג על ה'\" בא בהמשך להפסוק שלפניו<sup data-n=\"1052\">12</sup>, \"אם תשיב משבת רגליך עשות חפציך ביום קדשי וקראת לשבת עונג לקדוש ה' מכובד וכבדתו מעשות דרכיך ממצוא חפצך ודבר דבר (וע\"ז ממשיך) אז תת­ענג גו'\", שההבטחה ד\"אז תתענג על ה' גו'\" באה בהמשך לכל הנאמר לפנ\"ז<sup data-n=\"1053\">13</sup> (ובפרט שהבבא ד\"וקראת לשבת עונג\" הוא לא בסיום הכתוב), והיינו (כדברי ה­רמב\"ם) \"השומר את השבת כהלכתה ומכבדה ומענגה כפי כחו\"<sup data-n=\"1054\">14</sup>.\nולכאורה יש לעיין, מדוע נטה ה­רמב\"ם מדרשת הגמרא והביא פירוש הכתוב (רק) לפי פשוטו.\nב. ויש לבאר זה בהקדם ביאור לשון הרמב\"ם \"מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא\" — שדורש ביאור: הרי כבר כתב הרמב\"ם בהלכות תשובה<sup data-n=\"1055\">15</sup> שעיקר שכר המצוות הוא בעוה\"ב, ואמאי הוצרך להדגיש ענין זה כאן?\nוהנה במדרש<sup data-n=\"1056\">16</sup> איתא (בהמשך לכמה מעלות בשמירת שבת) \"ולא עוד אלא כל מה שאתה אוכל בעולם הזה אינו אלא מן הפירות אבל הקרן קיימת לך לעוה\"ב שנאמר והאכלתיך נחלת יעקב אביך כי פי ה' דבר\". ומבואר במפרשים<sup data-n=\"1057\">17</sup>, שכוו­נת המדרש ששבת היא בכלל הדברים שאדם אוכל פירותיהן גם בעוה\"ז (והא שלא נזכר במשנת<sup data-n=\"1058\">18</sup> \"אלו דברים שאדם",[["1050","10","וכן משמע משינוי הלשון בשו\"ע אדה\"ז או\"ח שם \"שכרו מפורש בקבלה כו' ובדברי רז\"ל כו'\". אלא שאדה\"ז לא העתיק לשון הרמב\"ם, כי אם \"כל המענג את השבת\" כבגמ'. ושם עה\"ג נסמן \"שבת קיח, ע\"ב (ע\"ש)\". ואכ\"מ."],["1051","11","להעיר ממה שמצינו בכללי הרמב\"ם שה­רמב\"ם נוקט הדרשה היותר פשוטה אף שלא נאמרה בגמ' (ראה יד מלאכי כללי הרמב\"ם אות ד')."],["1052","12","ישעי' נח, יג. וראה רד\"ק שם."],["1053","13","פסוק שכבר הובא ברמב\"ם לפנ\"ז במצות ודיני שבת — הל' שבת פכ\"א הכ\"ט. פכ\"ד ה\"א. שם ה\"ה. פ\"ל ה\"א. וראה גם להלן הל' שביתת יו\"ט פ\"ו הט\"ז."],["1054","14","ועוד: בדברי הרמב\"ם \"וכל השומר את ה­שבת כו' כבר מפורש בקבלה שכרו בעולם הזה כו' שנאמר אז תתענג על ה' גו'\" מוכח, שכל הכתוב, גם (תחלתו) \"אז תתענג על ה'\", קאי על השכר של שמירת וכבוד ועונג שבת, כפשטות הכתוב ד\"אז תתענג גו'\" הוא השכר על הפעולות והמעשים שבפסוק שלפנ\"ז; אבל בדרשת הגמרא יש מפרשים (ראה הרי\"ף לע\"י שבת שם), שהתיבות \"אז תתענג על ה'\" הן חלק מהגדרת מעשה האדם — \"המענג את השבת\", והשכר הוא בהמשך וסיום הפסוק — \"והאכלתיך נחלת יעקב אביך\" (\"נותנין לו נחלה בלי מצרים\"). ודוחק."],["1055","15","פ\"ח ורפ\"ט."],["1056","16","שמו\"ר ספכ\"ה."],["1057","17","יפה תואר שם."],["1058","18","ריש פאה."]]],[1301410191,"אוכל פירותיהן כו'\" הוא משום דתנא ושייר).\nולכאורה י\"ל שזהו מקור דברי ה­רמב\"ם כאן<sup data-n=\"1059\">19</sup>, וכוונתו, ששבת הוי בכלל מצות שאדם אוכל פירותיהן בעולם הזה. ולפ\"ז, הפירוש בדברי הרמב\"ם \"מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא שנאמר כו'\" הוא, ש­בפסוק \"אז תתענג גו'\" נכללים שני ה­ענינים, השכר בעולם הזה והשכר הצפון לעולם הבא: \"אז תתענג על ה' והרכב­תיך על במתי ארץ\" — \"שכרו בעוה\"ז\"; \"והאכלתיך נחלת יעקב אביך\" — \"השכר הצפון לעולם הבא\"<sup data-n=\"1060\">20</sup>.\nאבל קשה לומר שזוהי כוונת הרמב\"ם כאן — כי [מלבד זאת שאינו מיושב (היטב) מה שהוצרך להוסיף \"יתר על השכר הצפון לעולם הבא\", דפשיטא ש­עיקר השכר הוא בעוה\"ב, כמבואר ב­ארוכה בהלכות תשובה<sup data-n=\"1055\">15</sup>, והחידוש הוא רק שישנו שכר פירותיהן גם בעוה\"ז, וא\"כ הול\"ל \"שכרו בעולם הזה\" (ואנא ידענא שזהו \"יתר על השכר הצפון ל­עולם הבא\") — הרי]:\nא) את\"ל שכוונת הרמב\"ם היא לדברי המדרש הנ\"ל, הרי העיקר חסר מן הס­פר, דהו\"ל להרמב\"ם להדגיש את החי­לוק דשני סוגי השכר, שהשכר בעולם הזה הוא (רק) בגדר \"אכילת פירות\" ו­אילו השכר בעוה\"ב הוא ה\"קרן\" (שזהו חילוק עיקרי ויסודי); אבל הרמב\"ם כתב רק באופן סתמי \"מפורש. . שכרו בעו­לם הזה יתר על השכר הצפון לעולם הבא\", שאין במשמעות לשון זו שיש הפרש ביניהם במהות השכר.\nב) ועיקר: בפירוש המשניות לה­רמב\"ם<sup data-n=\"1062\">21</sup> מבואר הטעם שבמשנת \"אלו דברים שאדם אוכל פירותיהן בעוה\"ז כו'\" נקט התנא דוגמאות ד\"כבוד אב ואם וגמילות חסדים כו'\", כי רק ב\"חלק השני במצות התלויות בתועלת בני אדם\" אומ­רים שאדם אוכל פירותיהן בעוה\"ז (כיון שעל ידן \"ימצא טובה בעוה\"ז\"), והרי ש­מירת שבת אינה בכללן (וכמפורש ב­רמב\"ם שם, ששבת היא מ\"חלק האחד במצות. . שיש בינו ובין הקב\"ה\"). ודו­חק לומר שהרמב\"ם נקט כאן להלכה כדברי המדרש (שגם בשבת אדם אוכל פירותיהן בעוה\"ז) נגד משנה מפורשת<sup data-n=\"1063\">22</sup>.\nג. ויש לומר הביאור בזה:\nבדיוק לשונו \"שכרו בעולם הזה יתר על השכר הצפון לעולם הבא\" בא ה­רמב\"ם להשמיענו, שיש חידוש עיקרי בשכרה של מצות שבת, שלא מצינו דוגמתו בשכרן של כל מצוות התורה.\nדהנה בענין שכר מצוות ביאר ה­",[["1059","19","ידועה השקו\"ט האם ראה הרמב\"ם השמו\"ר (וראה הקדמת מהר\"ץ חיות למד\"ר), אבל מ\"מ י\"ל שמקור הרמב\"ם הוא מהמדרש שממנו שאב בעל ה­שמו\"ר כו'. ואכ\"מ."],["1060","20","וכן הוא לפי מפרשי המדרש, דתחלת הכתוב \"אז תתענג על ה'\" קאי בהפירות שאוכל בעוה\"ז, ו\"והאכלתיך נחלת יעקב אביך\" — הקרן קיימת לעוה\"ב (וראה גם במפרשים לישעי' עה\"פ. מפרשי הע\"י שבת שם. ובענף יוסף שם בשם עוללות אפרים).\nבפי' מהרז\"וו ש\"דורש שהנחלה היא הקרן והאכלתיך הפירות מן הנחלה. . כאילו כתיב והנחלתיך נחלת יעקב אביך והאכלתיך הפירות\". אבל פשיטא שא\"א לפרש כן בלשון הרמב\"ם \"שכרו מפורש בעוה\"ז יתר על השכר הצפון לעולם הבא\"."],["1055","15","פ\"ח ורפ\"ט."],["1062","21","פאה שם."],["1063","22","וכבר נת' במ\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191217\" data-slug=\"likkutei-sichot\" data-id=\"1300191217\">לקו\"ש חי\"ט ע' 204</a> ואילך. וש\"נ) דגם לדעת הרמב\"ם בספר היד שכתב (בהל' תשובה שם) ש\"מתן שכרן של מצות. . היא חיי ה­עוה\"ב\", י\"ל שס\"ל כסתם משנה דריש פאה דבמצות שבין אדם לחבירו אדם אוכל פירותיהן בעוה\"ז."]]],[1301410192,"רמב\"ם בארוכה (בהלכות תשובה<sup data-n=\"1064\">23</sup>), שיש שני סוגי שכר: (א) \"סוף מתן שכרן של מצות\" הוא \"חיי העולם הבא\", שרק חיים אלה ראויים הם להיות תכלית השכר על קיום התורה ומצוות<sup data-n=\"1065\">24</sup>. (ב) יעודים גש­מיים, שאין הם סוף מתן שכרן של מצוות, וכל ענינם הוא רק כדי לאפשר לאדם לקיים את המצוות כדבעי (בלי בלבולים), \"שלא נעסוק כל ימינו ב­דברים שהגוף צריך להן אלא נשב פנויים ללמוד בחכמה ולעשות המצוה כדי שנזכה לחיי העולם הבא\".\nוי\"ל שבזה שונה מצות שבת משאר כל המצוות: \"מפורש בקבלה שכרו ב­עולם הזה יתר על השכר הצפון לעולם הבא\", והיינו שהשכר בעוה\"ז אינו כמו היעודים הגשמיים (שאינם אלא הסרת המניעה כדי לאפשר את קיום המצות וכו' כדבעי)<sup data-n=\"1066\">25</sup>, אלא השכר בעוה\"ז הוא באותו האופן והגדר דהשכר הצפון לעו­לם הבא, והיינו שכר ממש<sup data-n=\"1067\">26</sup>.\nוזהו מה שכתב הרמב\"ם \"כבר מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא שנאמר אז תתענג על ה' גו'\", שבפסוק זה מודגש, שהשכר על שמירת שבת בעוה\"ז (אינו שכר הדומה ליעודים גשמיים שמצינו בכל התורה כולה<sup data-n=\"1068\">27</sup>, אלא) הוא שכר שגדרו הוא מעין עוה\"ב, וכמפורש \"אז תתענג על ה'\", שזהו בדוגמת ומעין שכר דעוה\"ב, ש­\"נהנין מזיו השכינה\" (וכמ\"ש הרמב\"ם אודות \"הטובה הצפונה לצדיקים. . חיי העולם הבא\"<sup data-n=\"1069\">28</sup>, שהיא<sup data-n=\"1070\">*28</sup> מה ש\"צדיקים יושבים כו' ונהנין מזיו השכינה\", וכ­מבואר שם בארוכה)<sup data-n=\"1071\">29</sup>.\nוגם בהמשך הכתוב \"והרכבתיך על במותי ארץ\", מבואר ומודגש שאין ה­כוונה כאן ליעודים גשמיים — \"שיסיר ממנו כל הדברים המונעים אותנו מל­עשותה (את התורה) כגון חולי ומלחמה ורעב וכיוצא בהן וישפיע לנו כל ה­טובות המחזיקות את ידינו לעשות התורה כגון שובע ושלום וריבוי כסף וזהב\"<sup data-n=\"1072\">30</sup>, כי יעודים אלה הרי הם בגדר \"ארץ\", היינו דברים דארץ הלזו ה­",[["1064","23","פ\"ט."],["1065","24","כמו שהאריך בפ\"ח שם."],["1066","25","וגם לא בגדר אכילת פירות (כהמצות שבין אדם לחבירו)."],["1067","26","ועפ\"ז יומתק מ\"ש בכתבי האריז\"ל (ס' הליקוטים פ' תצא, הובא בנחל קדומים תצא כד, טו) ש\"ביומו תתן שכרו\" ר\"ת שבת, כי זהו החידוש ב­שבת ושייך לעצם גדר שבת, כדלקמן בפנים (סעיף ד)."],["1068","27","וי\"ל שלכן דייק הרמב\"ם וכתב \"כבר מפורש בקבלה שכרו\", כי ה\"שכר\" ש\"כתוב בכל התורה כולה\" (היינו בחמשה חומשי תורה) כבר ביאר בהל' תשובה שאי\"ז בתור שכר, אלא להסיר המניעות וכו' — משא\"כ השכר המבואר ב\"קבלה\", שבו אפשר לפרש שהכוונה לשכר מצות ממש."],["1069","28","הל' תשובה רפ\"ח."],["1070","*28","שם ה\"ב."],["1071","29","ע\"פ המבואר במ\"א (לקמן ע' 177 ואילך) במרז\"ל (ל' רש\"י ר\"פ וישב) \"ביקש יעקב לישב בשלוה כו' אומר הקב\"ה לא דיין לצדיקים מה שמתוקן להם לעוה\"ב אלא שמבקשים לישב בשלוה בעוה\"ז\", שבקשת יעקב היתה לשלוה רוחנית, ע\"ד השלוה דעוה\"ב שיושבין ונהנין מזיו השכינה (וע\"ש שסוף­סוף נתקיימה בקשתו, וישב בשלוה אמיתית דעוה\"ב גם בעוה\"ז (ראה זח\"א קפ, סע\"א. ועוד), אלא שבא לאחרי שקפץ עליו רוגזו של יוסף. ע\"ש בארוכה) —\nיובן ויומתק זה שמייחסים שכר זה ליעקב דוקא, נחלת יעקב אביך (אף שבנוגע לכל האבות אמרו (ב\"ב טז, סע\"ב ואילך) שהטעימן מעין עוה\"ב. וראה ברכות יז, א), כי ענין זה, שלימות התענוג על ה' (דעוה\"ב) בעוה\"ז, הי' אצל יעקב דוקא. וראה לקמן הערה *42. 43."],["1072","30","שם פ\"ט."]]],[1301410193,"גשמית, אלא שהם השלימות דארץ ועני­ני עוה\"ז; משא\"כ תוכן השכר ד\"הרכב­תיך על במותי ארץ\" היינו למעלה גם מהשלימות דעוה\"ז (במתי ארץ), והוא ה­תענוג \"על ה'\", הנאה מזיו השכינה, ש­הוא למעלה מגדרי ארץ ותענוגי עוה\"ז, כפי שהאריך בהל' תשובה שם<sup data-n=\"1073\">31</sup>.\nד. וע\"פ הנ\"ל יבואר היטב הטעם ש­פירש כאן הרמב\"ם את הכתוב לפי פשו­טו, ולא הביא דרשת רז\"ל הנ\"ל:\nבמס' שבת בא המאמר \"כל המענג את השבת\" בהמשך הסוגיא העוסקת (לא ב­מעלת כללות הענין דשמירת שבת, אלא) במעלות בענינים פרטיים דשבת: \"כל ה­מקיים שלש סעודות בשבת ניצול כו'\", \"כל המענג את השבת נותנין לו משאלות לבו\", \"כל המשמר שבת כהלכתו אפי' עובד ע\"ז כו' מוחלין לו\", ועוד כיו\"ב — ולכן הובאה שם דרשה דידן המבארת שכר מסויים (\"נחלה בלי מצרים\") על פרט מסויים בשבת (\"המענג את השבת\");\nאבל הרמב\"ם הביא כתוב זה בסיום וחותם כל הלכות שבת, כי כוונתו לענין כללי במצות שבת. ולכן נקט הרמב\"ם ב­מעשה הגברא (שעבורו מקבלים השכר) \"כל השומר את השבת כהלכתה ומכבדה ומענגה כו'\" (ולא רק \"המענג את ה­שבת\"), כיון שכוונתו לתוכן הכללי ד­שמירת שבת, לכל פרטי'. וכן סתם וכתב \"מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא\" (ולא נקט השכר ד\"נותנין לו נחלה בלי מצרים\") — כי כוונתו כאן (לא לשכר פרטי, אלא) להחידוש הכללי בשכר מצות שבת, ל­גבי שכר שאר כל המצות כולן, שעל ידי שמירת שבת מקבל האדם שכר ב­עוה\"ז מעין השכר דעוה\"ב.\nויש לומר, שלכן מדייק הרמב\"ם \"וכל השומר את השבת כו' ומכבדה ומענגה כפי כחו\" (דלכאורה, היכן מרומז פרט זה בכתוב?): הטעם שמצות שבת מיוחדת מכל מצות התורה בזה ששכרה (האמיתי) הוא (גם) בעוה\"ז, הוא מפני שעצם השבת (וקדושת שבת) הוי מעין עוה\"ב<sup data-n=\"1074\">32</sup>. והיינו, ששכר זה הוא בגדר תוצאה טבעית, שכ­אשר האדם מתאחד עם השבת, זוכה ב­דרך ממילא ל\"מעין עולם הבא\" בעוה\"ז. ולכן מדייק הרמב\"ם, ששכרו בעוה\"ז ת­לוי בזה שהאדם \"שומר את השבת כהל­כתה ומכבדה ומענגה כפי כחו\", שבזה מודגש שיש אצל האדם שלימות קדושת שבת, הן מצד החפצא דשבת, שיש אצלו כל פרטי קיום מצות השבת, \"שומר את השבת כהלכתה ומכבדה ומענגה\", והן מצד הגברא — שמכניס בזה כל חיי נפשו (\"כפי כחו\")<sup data-n=\"1075\">33</sup>, שאז השבת והאדם מתאחדים ביחוד גמור.\nה. בדרך זו יש לבאר גם המשך ה­ענינים בהלכה זו ברמב\"ם:",[["1073","31","פ\"ח ה\"ו."],["1074","32","ראה מכילתא (ומדרש הגדול) תשא (לא, יג) \"כי אני ה' מקדשכם לעולם הבא כגון קדושת שבת בעולם הזה נמצינו למדין שהוא מעין קדושת העולם הבא כו'\". וראה ברכות נז, ב. ר\"ה לא, א. מדרש לקח טוב תשא שם. אוה\"ח שם. ועוד."],["1075","33","דדוחק לומר שכוונת הרמב\"ם ב\"כפי כחו\" היא להגביל החיוב, שאינו חייב יותר מדי (וע\"ד לשון הסמ\"ג (מ\"ע ל) \"ומענגה לפי כחו אבל אינו חייב לעשות יותר מדי\". וראה רמב\"ם שם פ\"ל ה\"ז וה\"י)<sup data-n=\"e28\">*</sup> — כי למאי נפק\"מ כאן הגבלה זו? ולכן מסתבר שכוונת הרמב\"ם היא להיפך, כבפנים. וע\"ד משנ\"ת במ\"א (הדרן על הרמב\"ם — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271255\" data-slug=\"likkutei-sichot\" data-id=\"1300271255\">לקו\"ש חכ\"ז ע' 241</a>) בפירוש דברי הרמב\"ם סוף הל' מלכים \"כפי כח האדם\"."],["e28","*","אבל בב\"י או\"ח שם (סרמ\"ב), שלפי הטור אע\"פ שהשעה דחוקה לו יכין צרכי שבת יותר מכדי יכולתו. וראה ב\"ח שם. קו\"א לשו\"ע אדה\"ז שם סק\"ג. ואכ\"מ."]]],[1301410194,"תחילת ההלכה היא \"השבת ועבודה זרה כל אחת משתיהן שקולה כנגד שאר כל מצות התורה והשבת היא האות שבין הקב\"ה ובינינו לעולם לפיכך כל העובר על שאר המצות הרי הוא בכלל רשעי ישראל אבל המחלל שבת בפרהסיא הרי הוא כעובד ע\"ז ושניהם כגויים<sup data-n=\"1076\">34</sup> לכל דבריהם לפיכך משבח הנביא ואומר<sup data-n=\"1077\">35</sup> אשרי אנוש כו'\", וע\"ז מסיים \"וכל ה­שומר את השבת כהלכתה כו' כי פי ה' דבר\".\nבהלכה זו משמיענו הרמב\"ם עיקר גדול בגדר מצות שבת, והוא, שהשבת אינה כשאר מצות התורה שקיומן הוי רק תוספת קדושה, נוסף לקדושת ישראל שבו, ובמילא בהעדר קיומם הרי הוא (\"רשעי ישראל\" —) עדיין בכלל ישראל, לא כן הוא אלא דהוי כמו ע\"ז, שנוגע לגוף קדושת ישראל<sup data-n=\"1078\">36</sup>, ולכן המחלל שבת הוא כעובד עבודה זרה, \"ושניהם כגויים לכל דבריהם\"<sup data-n=\"1079\">37</sup>.\nוע\"ז ממשיך, דכשם שהוא בהשלילה, שהמחלל שבת הרי הוא כגוי<sup data-n=\"1080\">38</sup>, כן הוא גם בצד החיוב, ששמירת שבת אינה כדבר נוסף על גדר ישראל שבו, אלא ששייכת לעצם קדושת ישראל<sup data-n=\"1081\">39</sup>. וזהו",[["1076","34","כ\"ה במהדורת פרענקל, ע\"פ דפוסים ה­ראשונים כו'. ולפנינו \"כעובדי כוכבים ומזלות\", והוא שינוי הצענזור, כבכ\"מ."],["1077","35","ישעי' נו, ב."],["1078","36","ראה גם זח\"ב רה, ריש ע\"ב."],["1079","37","עפ\"ז יומתק לשון הרמב\"ם \"ושניהם כגויים לכל דבריהם\", דלכאורה אין כאן מקום ההלכה שעובד ע\"ז הוי כגוי כ\"א רק דמחלל שבת בפרהסיא הוי כגוי, והול\"ל \"הרי הוא כעובד ע\"ז וכגוי לכל דבר\",\nאלא שאז יש מקום לפרש דזה שמחלל שבת בפרהסיא הוא כעובד ע\"ז וכגוי לכל דבר, היינו ב­עונשו, אבל במהותו אין מחלל שבת שווה לעובד ע\"ז, ולכן כתב הרמב\"ם \"ושניהם כגויים לכל דברי­הם\", שגדר אחד לשניהם."],["1080","38","וי\"ל שזהו ההמשך \"לפיכך משבח הנביא ואומר אשרי אנוש יעשה זאת ובן אדם יחזיק בה שומר שבת מחללו וגו'\", דלכאורה אינו מובן מהו ההמשך כאן, ומהו \"לפיכך\"? והרי מצינו בכ\"מ שהנביאים משבחים עושי מצות? אלא שיש בפסוק זה הדגשה מיוחדת על מעלת האדם עצמו, שב­תחילה כותב \"אשרי אנוש גו' ובן אדם גו'\" ורק אח\"כ מבאר הכתוב מהות המצוה, שרק בשבילה משבחו \"יעשה זאת\" (\"שומר שבת גו'\") — שלא כברוב המקומות (א) שמפרש השבח על המעשה בלבד, (ב) בלי ההדגשה (כבפסוק הנ\"ל) שהוא רק בשביל זאת (כמו אשרי כל חוכי לו (ישעי' ל, יח), אשרי האיש אשר לא הלך (תהלים בתחלתו), אשרי כל חוסי בו (שם ב, יב) וכיו\"ב) — כי המעשה דשמירת שבת נוגע בעצם האדם.\nויתירה מזו: מזה שמדגיש בכתוב \"אשרי אנוש. . ובן אדם\", מוכח שאין המדובר באיש המעלה מצ\"ע (כי שם \"אנוש\" מורה על חלישות ופחיתות בדרגת האדם<sup data-n=\"e29\">*</sup>, וכן \"בן אדם\" המדגיש שכל מעלתו היא רק בזה שהוא בן אדם הראשון<sup data-n=\"e30\">**</sup>), ומזה שמשבח איש כזה שאין בו מעלה ושלימות רק מצד זה ש\"שומר שבת מחללו וגו'\", מובן, ששמירת שבת אינה רק הוספה במעלות ותוארים פרטיים של איש ישראל, אלא נוגעת לעצם מציאותו בתור אדם מישראל. ועצ\"ע."],["1081","39","ראה מכילתא (ומדרש לקח טוב ומדרש הגדול) תשא לא, יד: \"כי קודש היא לכם מגיד שהשבת מוספת קדושה על ישראל כו'\"."],["e29","*","כמובא בכ\"מ הראי' לזה מהכתוב (ירמי' יז, ט) \"עקוב הלב מכל ואנוש הוא\". וראה גם ישעי' כד, ו. נא, ז. תהלים ח, ה. קמד, ג (ובכ\"מ) ובמפרשים שם."],["e30","**","וגם שם \"אנוש\" י\"א שנקרא כן ע\"ש אנוש בן בנו של אדה\"ר. וראה שבת (קיח, ב) \"כל המשמר שבת כהלכתו אפי' עובד ע\"ז [כדור] אנוש מוחלין לו שנאמר אשרי אנוש יעשה זאת וגו' מחללו כו'\". אבל דוחק לומר שלזה מרמז הרמב\"ם כאן, וע\"פ מ\"ש בריש הל' ע\"ז דטעות ע\"ז הותחלה מדור אנוש (וכמבואר בארוכה בחדא\"ג ומפרשי הע\"י שבת שם. לבוש ונ\"כ שו\"ע או\"ח שם), וע\"י שמירת שבת יבוא לאמונת ההשגחה ויחזור מטעותו. וראה ט\"ז או\"ח שם (בריש הסימן). אהבת איתן לע\"י שם. ועוד."]]],[1301410195,"מ\"ש אודות השכר דשמירת שבת, \"כבר מפורש בקבלה שכרו בעולם הזה יתר על השכר הצפון לעולם הבא שנאמר אז תתענג על ה' גו'\", שכוונתו בזה (כנ\"ל) שיש לו שכר בעוה\"ז מעין השכר ד­עוה\"ב — כי גדר שכר עוה\"ב (כמבואר ברמב\"ם הל' תשובה) הוא גמר ושלימות הקשר ודביקות ישראל בבורא (שלכן \"כמה דוד והתאוה לחיי העולם הבא\"<sup data-n=\"1082\">40</sup> (וכן נתאוו לזה כל ישראל, נביאיהם וחכמיהם כו'<sup data-n=\"1083\">41</sup>)) — וע\"י שמירת שבת מקבל שכר זה<sup data-n=\"1084\">42</sup>, היינו שמוסיף תוקף ב­עצם קדושת ישראל שבו<sup data-n=\"1085\">*42</sup> (דביקות ב­בורא מעין שלימות הדביקות בעוה\"ב)<sup data-n=\"1086\">43</sup>.\nו. ע\"פ כ\"ז יש להוסיף ביאור במה שהביא הרמב\"ם גם סיום הכתוב \"כי פי ה' דבר\", שלא הובא בגמרא. בפשטות י\"ל שתיבות אלו (\"כי פי ה' דבר\") באו להורות שכיון שזוהי הבטחה מפורשת מאת ה' בדיבור, הרי בודאי תתקיים<sup data-n=\"1087\">44</sup>, וכמ\"ש הרמב\"ם בהל' יסודי התורה<sup data-n=\"1088\">45</sup> דכל דבר טובה שיגזור הא­ל אפילו על תנאי אינו חוזר. אבל צ\"ב מדוע הודגש זה דוקא בשכר זה, דבר שלא מצינו ב­שאר עניני שכר?\nוע\"פ הנ\"ל מובן: בשאר עניני שכר",[["1082","40","ל' הרמב\"ם שם פ\"ח ה\"ז."],["1083","41","רמב\"ם שם פ\"ט ה\"ב. ואף ש\"אל יאמר אדם הריני עושה מצות התורה כו' כדי שאקבל כל הברכות כו' או כדי שאזכה לחיי העולם הבא כו' אין ראוי לעבוד את ה' על הדרך הזה\" (רמב\"ם שם רפ\"י) — כבר נתבאר במ\"א, שזה שנתאוו החכמים והנביאים הוא לא לעוה\"ב בתור שכר אלא בתור גמר דביקות בבורא (ראה בארוכה לקו\"ש חל\"ג ס\"ע 87 ואילך)."],["1084","42","ויש לומר, דבזה שהוסיף הרמב\"ם \"ומכבדה ומענגה כפי כחו\" ולא הסתפק בלשון כללי \"שומר את השבת כהלכתה\", קמ\"ל, דאף שכבוד ועונג אינם מן התורה אלא מדברי סופרים (— שנתפרשו ע\"י הנביאים), כמ\"ש בתחילת הפרק (פ\"ל), הרי קיומם הוא חלק מגוף ועצם קיום מצות שבת שמדאורייתא<sup data-n=\"e31\">*</sup>, ועד שעי\"ז נתוסף בעצם גדר קדושת ישראל שבשבת. ומזה מובן גם לאידך, שכאשר חסר בכבוד או עונג שבת<sup data-n=\"e32\">**</sup>, אין זה רק חסרון במצוה ופרט דשבת (שמד\"ס), או הידור המצוה, אלא חסר בגוף ועצם קדושת ישראל הנעשה על ידי השבת, שהיא אות ביני וביניכם. אף שמובן שלהלכה הא ד­מחלל שבת הוא כע\"ז הוא רק במחלל שבת כפשוטו וזה גופא דוקא \"בפרהסיא\"."],["1085","*42","ועפ\"ז יומתק ל' הכתוב \"נחלת יעקב אביך\", כי גמר קדושת ישראל אצל האבות באופן של נחלה, שקדושת ישראל נמשכת לבניהם אחרי­הם עד עולם, הוא ביעקב (דלכן יעקב מטתו שלימה — ויק\"ר פל\"ו, ה. רש\"י ויחי מז, לא. ובכ\"מ)."],["1086","43","ע\"פ הנ\"ל יש לומר עוד (באו\"א), שלפי הרמב\"ם זהו פירוש דברי הגמ' \"נותנין לו נחלה בלי מצרים\", כי שכר זה ד\"תתענג על ה'\" שהאדם זוכה בעוה\"ז, אינו במצרים וגבול כעניני ותענוגי עוה\"ז אלא בלי מיצרים וגבול (ראה בארוכה חדא\"ג מהרש\"א שבת שם. ובעוד מפרשי הע\"י שם), שהוא תענוג על ה' [ומ\"ש בגמ' \"לא כאברהם כו' ולא כיצחק כו' אלא כיעקב\" כו', י\"ל שהרמב\"ם מפרש שאין הכוונה לשכר גשמי או אפילו ירושת הארץ, אלא כדוגמא שנחלת יעקב היא נחלה בלי מצרים (שלא כנחלת אברהם ויצחק), אבל ענין השכר הוא שכר ותענוג של עוה\"ב (וראה חדא\"ג שם)], וכיון שעוה\"ב הוא השכר האמיתי עבור קיום כל התורה ומצוות, צ\"ל דמ\"ש בגמ' שעבור עונג שבת (דוקא) נותנין לו נחלה בלי מצרים, הכוונה בזה היא שנותנין לו שכר זה גם בעוה\"ז. וראה לעיל הערה 29."],["1087","44","כמ\"ש ברד\"ק ומצו\"ד ישעי' עה\"פ."],["1088","45","פ\"י ה\"ד."],["e31","*","וראה שו\"ת חת\"ס או\"ח סקס\"ח, דס\"ל של­דעת הרמב\"ם הוי דאורייתא. וכ\"ה לכמה דיעות. אבל ראה שו\"ע אדה\"ז ר\"ס רמ\"ב ובקו\"א שם."],["e32","**","להעיר מדיוק לשון הרמב\"ם בפ\"ל שם \"ארבעה דברים נאמרו בשבת\" (ורק אח\"כ מפרט: שנים כו' ושנים כו').\n‑"]]],[1301410196,"ויעודים גשמיים שהקב\"ה משפיע בעולם הזה, ה\"ה דברים שבגדר עולם ומנהגו של עולם, ואפילו שלימות הטובות וה­מעלות שתהי' בעולם הזה לימות המשיח, הרי כ' הרמב\"ם<sup data-n=\"1089\">46</sup> שלא יבוטל דבר מ­מנהגו של עולם.\nאבל שכר שמירת שבת, להתענג על ה', שהוא שכר הצפון לעולם הבא, אינו דבר בסוג גדר העולם, כפי שהאריך הרמב\"ם בהל' תשובה<sup data-n=\"1090\">47</sup> (\"אותה הטובה גדולה עד מאד. . עד אין חקר ואין לה ערך ודמיון. . אין כח באדם להשיגה על בורי' כו', ושכל הטובות שמתנבאים בהם הנביאים לישראל אינן אלא ל­דברים שבגוף שנהנין בהן ישראל כו' אבל טובת חיי העוה\"ב אין לה ערך ודמיון ולא דמוה הנביאים כו'\"), ולכן מוסיף ומדגיש בזה \"כי פי ה' דבר\", ד­דבר זה שלא השיגוהו \"ולא דמוה הנבי­אים\", ניתן לשומר שבת כהלכתה ומ­כבדה ומענגה כפי כחו.\nז. ומזה הוראה לכאו\"א מישראל, בלשון הרמב\"ם<sup data-n=\"1091\">*47</sup> \"לתקן הדעות וליישר כל המעשים\" — ע\"ד הוספה והתחזקות בלימוד פנימיות התורה, שענינה \"דע את אלקי אביך\"<sup data-n=\"1092\">48</sup>, שעי\"ז דוקא בא לדביקות בבורא ולהתענג על ה', וכמ\"ש הרמב\"ם בסוף הלכות תשובה \"לפיכך צריך ה­אדם ליחד עצמו להבין ולהשכיל ב­חכמות ובתבונות המודיעים לו את קונו כפי כח שיש באדם להבין ולהשיג\",\nובפרט בעבודת התפלה, כדאיתא ב­שו\"ע<sup data-n=\"1093\">49</sup> בנוגע לחסידים הראשונים שהיו שוהין<sup data-n=\"1094\">50</sup> שעה אחת שלימה בכל תפלה משלש התפלות, ש\"לא היו חוששין ל­ביטול תורה אף שת\"ת כנגד כולם מפני שהיו מקשרים דעתם לאדון הכל ב\"ה ביראה ואהבה עזה ודביקות אמיתית עד שהיו מגיעים להתפשטות הגשמיות ו­מצות הדביקות האמיתית ביראה ואהבה היא גדולה ממצות ת\"ת וקודמת אלי'\".\nובאמת ה\"ז שייך לגוף ענין השבת, וכמובא במגיד משנה כאן<sup data-n=\"1095\">51</sup> \"וטעם ה­שבת לפי שהוא מורה על החדוש וכופר בחדוש כופר בכל התורה כולה ולפיכך צריך להאמין ולקבוע בנפשו אמונת ה­חדוש ולשמור השבת שהוא אות נאמן עליו\".\nוהרי פרטי אמונת החידוש ועומקה באים על ידי לימוד והתבוננות בפנימיות התורה, שבה מבוארים הדברים בהרחבת הביאור ולכל פרטי'.\nוקביעותה היא על ידי עבודת ה­תפלה, וכמפורש ברמ\"א<sup data-n=\"1096\">52</sup> \"ויחשוב קודם התפלה מרוממות הא­ל יתעלה ובשפלות האדם ויסיר כל תענוגי האדם מלבו\", ודוקא עי\"ז יכול לבוא בתפלה לדביקות בבורא,\nוידוע<sup data-n=\"1097\">53</sup> שהתפלה היא (ע\"ד) בחי' שבת,\nועי\"ז שבנ\"י שומרים את השבת כ­הלכתה הן בפנימיות והן בחיצוניות ה­שבת<sup data-n=\"1098\">54</sup>, הרי מיד הן נגאלין<sup data-n=\"1099\">55</sup>, ואז יתגלה",[["1089","46","ספ\"ט מהל' תשובה. רפי\"ב מהל' מלכים."],["1090","47","פ\"ח ה\"ו­ז. ועוד."],["1091","*47","סוף הל' תמורה."],["1092","48","דה\"א כח, ט."],["1093","49","הל' ת\"ת לאדה\"ז פ\"ד ס\"ה. וש\"נ. וראה טושו\"ע ודאדה\"ז או\"ח סצ\"ח."],["1094","50","ברכות לב, ב."],["1095","51","וראה חינוך מצוה לא­לב. רמב\"ן עה\"ת יתרו כ, ח. ועוד. וראה בארוכה לבוש או\"ח סרמ\"ב."],["1096","52","או\"ח סצ\"ח ס\"א."],["1097","53","ראה כוזרי מאמר ג אות ה. וראה תו\"א נח ט, ריש ע\"ב. ויקהל פח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381013\" data-slug=\"likkutei-torah\" data-id=\"4001381013\">האזינו עב, ג</a>. ועוד."],["1098","54","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא בסופו</a>."],["1099","55","בבבלי שבת שם (קיח, ב) \"שתי שבתות\". ובירושלמי (תענית פ\"א סה\"א. וכ\"ה בשמו\"ר שם — פכ\"ה, יב) שבת אחת. וראה לקו\"ת בהר <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">שם (מא, א</a> ואילך) ועוד, דאין סתירה בין שני מרז\"ל אלו. ע\"ש."]]],[1301410197,"לעין כל איך ש\"מאתך היא מנוחתם ועל מנוחתם יקדישו את שמך\"<sup data-n=\"1100\">56</sup>, \"מאתך ממש\"<sup data-n=\"1101\">57</sup>, בגאולה האמיתית והשלימה על ידי משיח צדקנו.\n<span data-k=\"q\">(משיחת ש\"פ ויק\"פ תשמ\"ז) </span>",[["1100","56","נוסח תפלת עמידה דמנחת שבת."],["1101","57","ראה בארוכה ד\"ה אתה אחד לאדמו\"ר ה­אמצעי — בעל הגאולה והשמחה דשבת זו (יו\"ד כסלו) ויום ההולדת והסתלקות דעש\"ק (ט' כסלו) — ע' 8 ואילך (מאמרי אדהאמ\"צ — קונטרסים ע' יו\"ד ואילך), החילוק בין מנוחת שבת לשאר המצות. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151239\" data-slug=\"likkutei-sichot\" data-id=\"1300151239\">לקו\"ש חט\"ו (ע' 227</a> ואילך) הביאור עפ\"ז במרז\"ל כל המענג את השבת כו'."]]],[1301410198,"<h3>שיחה ב</h3>\nא. בטעם קריאת שם \"זבולון\" נאמר<sup data-n=\"1102\">1</sup> \"ותאמר לאה גו' הפעם יזבלני אישי כי ילדתי לו ששה בנים ותקרא את שמו זבולון\", ופרש\"י \"לשון בית זבול<sup data-n=\"1103\">2</sup>. . בית מדור, מעתה לא תהא עיקר דירתו אלא עמי שיש לי בנים כנגד כל נשיו\".\nוהנה אף ששם \"זבולון\" (\"לשון בית זבול\") בפשטות מורה על ענין הנפעל בלאה, \"יזבלני אישי\" — מ\"מ, ע\"פ הידוע שהשם שנקרא בו אדם שייך לנפשו ומהותו\n[כמבואר בספרים<sup data-n=\"1104\">3</sup> ששמות בני אדם \"אינם<sup data-n=\"1105\">4</sup> דרך מקרה או רצון האב ואם לקרותו כך\", אלא \"הקב\"ה<sup data-n=\"1105\">4</sup> הוא הנותן שכל חכמה ודעת בלב אביו ואמו ל­קרותו בשם שהוא משורש נשמתו של הבן\"; ועאכו\"כ השמות שניתנו על ידי האמהות שנביאות היו<sup data-n=\"1107\">5</sup>, שודאי הכירו (בנבואתן ורוח קדשן) מהות נשמות בניהן ובהתאם לזה קראו להם שמות],\nנ\"ל שהתוכן דשם \"זבולון\" שייך ל­מהותו של זבולון עצמו, שהרי הוא ה­נקרא בשם זה. ואין זה סתירה למש\"נ \"הפעם יזבלני אישי\" (דקאי על לאה) — כי י\"ל דהא בהא תליא<sup data-n=\"1108\">6</sup>: זה גופא שב­לידת זבולון צ\"ל \"עיקר דירתו\" של יעקב באהל לאה, אינו רק מפני שבו נשלם מספר \"ששה בנים\", אלא זה שייך גם לענינו ומעלתו של זבולון (שנתוסף אז ב\"אהל לאה\").\nולפי זה מקום לתמוה: ענינו של יעקב הוא — לימוד התורה, כמש\"נ<sup data-n=\"1109\">7</sup> \"ו­יעקב איש תם יושב אהלים\", \"אהלו של שם ואהלו של עבר\"<sup data-n=\"1110\">8</sup>, ואילו ענינו של זבולון הוא (כברכת יעקב לזבולון<sup data-n=\"1111\">9</sup>) \"זבולון לחוף ימים ישכון גו'\", \"שהי' זבולון עוסק בפרקמטיא\"<sup data-n=\"1112\">10</sup> — וא\"כ, כיצד אפשר לומר, שדוקא ענינו של \"זבולון\" הוא הקובע \"עיקר דירתו\" של יעקב?\nב. לכאורה הי' אפשר לבאר זה ע\"פ מחז\"ל<sup data-n=\"1113\">11</sup> עה\"פ<sup data-n=\"1114\">12</sup> \"שמח זבולון בצאתך ויששכר באהלך\" — \"זבולון<sup data-n=\"1115\">13</sup> ויששכר עשו שותפות, זבולון. . יוצא לפרקמטיא",[["1102","1","פרשתנו ל, כ."],["1103","2","מ\"א ח, יג."],["1104","3","ש' הגלגולים הקדמה כג. ש' מרז\"ל בסופו. עמה\"מ ש\"א ספ\"ד. או\"ת להה\"מ פ' בראשית (ד, ד). וראה ג\"כ חפץ ה' לברכות (יג, א). אוה\"ח וישלח לה, י. ר\"פ וילך. ועוד. ס' חסידים סרמ\"ד."],["1105","4","ל' האו\"ת שם."],["1105","4","ל' האו\"ת שם."],["1107","5","רש\"י פרשתנו כט, לד (וראה גם רש\"י ל, כד). ב\"ר פרשתנו (ספע\"ב)."],["1108","6","וראה או\"ת (שם, סע\"ג), \"ראשונים קראו בניהם ע\"ש המאורע. . כי שורש נשמת הבן הוא מעין שורש דבר המאורע\"."],["1109","7","תולדות כה, כז."],["1110","8","רש\"י שם, מב\"ר עה\"פ (פס\"ג, י). וראה גם פרש\"י פרשתנו כח, יא ד\"ה וישכב. — וראה לקמן בפנים רס\"ה."],["1111","9","ויחי מט, יג. — וכן בברכת משה (ברכה לג, יח) \"שמח זבולון בצאתך\"."],["1112","10","רש\"י ויחי שם (מב\"ר פצ\"ט, ט. וכן בב\"ר שבהערה הבאה). ועד\"ז בפ' ברכה שם."],["1113","11","ב\"ר פרשתנו (פע\"ב, ה). תנחומא ויחי יא. ועוד. פרש\"י ברכה שם. וראה ויק\"ר פכ\"ה, ב (הובא להלכה בהל' ת\"ת לאדה\"ז פ\"ג ס\"ד)."],["1114","12","ברכה שם."],["1115","13","ל' רש\"י ברכה שם. וראה גם רש\"י ויחי שם."]]],[1301410199,"בספינות ומשתכר ונותן לתוך פיו של יששכר והם יושבים ועוסקים בתורה לפיכך הקדים זבולון ליששכר כו'\" — והרי מובן שקדימה בתורה היא קדימה במעלה, והיינו שבזה שזבולון עוסק בתמיכת התורה יש בו מעלה על יששכר<sup data-n=\"1116\">14</sup>.\nאבל קשה לומר שמעלה זו (של תמכין דאורייתא) תכריע בקביעת מקום דירתו של יעקב, שעיקר המעלה והחשי­בות אצלו הוא ענין התורה — דאיך תהי' \"דירתו\" של יעקב תלוי' ב\"מקום\" העוסק בפרקמטיא (לו יהא שכוונת העסק היא רק בשביל תמיכת התורה) ולא במקום אהלה של תורה עצמו<sup data-n=\"1117\">15</sup>?\nובפרט ע\"פ דיוק לשונו של רש\"י \"עיקר דירתו\" (כיון שהוא \"בית זבול\") — שי\"ל שזהו החידוש ב\"בית זבול\" לגבי \"דירה\": סתם דירה יש במשמעה גם דירת עראי, משא\"כ \"זבול\" מורה על בית קבוע<sup data-n=\"1118\">*15</sup> [וע\"ד הלשון \"בית זבול\" בנוגע לבית המקדש — \"בנה<sup data-n=\"1103\">2</sup> בניתי בית זבול לך מכון לשבתך עולמים\", שנקרא \"בית זבול\" להיותו דירת קבע של הקב\"ה, באופן של \"מכון לשבתך עול­מים\", דירה נצחית] — כלומר: חשיבות ענינו של זבולון אינה רק כדירה סתם, דירת עראי וכו', אלא היא קשורה עם \"עיקר דירתו\", דירת קבע של יעקב<sup data-n=\"1120\">16</sup>.\nג. אמנם, מצינו דוגמת ענין זה גם בחיי יעקב עצמו:\nבפרשתנו מסופר בארוכה על דבר שהייתו של יעקב בבית לבן כ' שנה, ש­במשך זמן זה לכאורה, לא הי' נמצא באהלה של תורה, אלא הי' עסוק במרעה צאן של לבן, ומתאים לדיני התורה הי' עסוק באופן של \"בכל כחי עבדתי גו' ביום גו' בלילה\"<sup data-n=\"1121\">17</sup> [שלמדים מהנהגת יעקב בבית לבן כיצד צריכה להיות עבודת הפועל, כמבואר ברמב\"ם וכו'<sup data-n=\"1122\">18</sup>].\nומ\"מ, לא זו בלבד שדוקא בעת הזאת זכה ל\"ויפרוץ האיש מאד מאד\"<sup data-n=\"1123\">19</sup>, הצל­חה למעלה ממדידה והגבלה (ב' פעמים \"מאד\"<sup data-n=\"1124\">20</sup>) — ומובן, שזה כולל גם (ואד­רבה — בעיקר) הצלחה רוחנית<sup data-n=\"1125\">21</sup> (ובפרט שהמדובר בהאבות, שהיו \"מרכבה\" לר­צון העליון כל ימיהם<sup data-n=\"1126\">22</sup>, ובמכש\"כ משאר הצדיקים, שחייהם אינם חיים בשריים אלא חיים רוחניים<sup data-n=\"1127\">23</sup>) — אלא עוד זאת, שדוקא בבית לבן העמיד יעקב את שבטי ישראל (לבד מבנימין), ויסד את",[["1116","14","וראה בארוכה צרור המור ואלשיך כאן."],["1117","15","באלשיך (ועד\"ז בצרור המור) כאן, ש­\"זבולון הוא אכסניא לתורה. . שהוא זן את יששכר\". אבל לכאורה צ\"ע (כבפנים), דאיך אפ\"ל שהוא \"אכסניא לתורה\" יותר מיששכר?"],["1118","*15","ולהעיר מרש\"י ע\"ז יח, ב (ד\"ה שמזבלים): לשון יזבלני אישי, ענין חניי' של חיבור ואסיפה."],["1103","2","מ\"א ח, יג."],["1120","16","ולהוסיף מדיוק ל' רש\"י \"לא כו' אלא עמי\" — ל' שמורה שהוא לעיכובא (תוד\"ה מתני' — מנחות פג, סע\"ב) — ראה השקו\"ט במפרשי רש\"י כאן."],["1121","17","פרשתנו לא, ו; שם, מ (ולהעיר מב\"ר פס\"ח, יא: כל כ' שנה כו' מה הי' אומר כו' שיר המעלות כו'). — משא\"כ רועה צאן בכלל, לא באופן של \"פועל\" שחייב לעבוד בכל כחו כו'. וכמבואר בכ\"מ (מהם — מאמרי אדה\"ז­תקס\"ה (ח\"א) ע' קצב. תו\"ח ויחי (קב, ב). ועוד) שמטעם זה בחרו האבות להיות רועי צאן כי אין במלאכה זו טירדות כו'."],["1122","18","סוף הל' שכירות (מהשיעור דיום ש\"ק זה — תשמ\"ח). טושו\"ע חו\"מ סו\"ס שלז. שו\"ע אדה\"ז חו\"מ הל' שאלה ושכירות כו' ס\"כ. — ולהעיר מקו\"א להל' נזקי גו\"נ כו' סק\"ב."],["1123","19","פרשתנו ל, מג."],["1124","20","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370108\" data-slug=\"torah-or\" data-id=\"3901370108\">תו\"א פרשתנו (כג, ב</a>. שם, ג). ועוד."],["1125","21","ראה בארוכה ע\"ד החסידות תו\"א, תו\"ח וכו' פרשתנו."],["1126","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ\"ג</a>. ובכ\"מ."],["1127","23","ראה תניא אגה\"ק ביאור לסי' זך."]]],[1301410200,"ביתו, בית ישראל, שכאו\"א מהם יש לו נשמה קדושה<sup data-n=\"1128\">24</sup> וכלולה בנשמת יעקב<sup data-n=\"1129\">25</sup> — שזוהי מעלתו של יעקב<sup data-n=\"1130\">26</sup>, בחיר ה­אבות שהיתה \"מטתו שלימה\"<sup data-n=\"1131\">27</sup>, דלא כאברהם ויצחק ש\"יצאו מהם\" ישמעאל ועשו<sup data-n=\"1132\">28</sup>.\nשאינו מובן: איך זה שלהצלחה ה­רוחנית הגיע יעקב (לא בזמן עסקו בתורה כו' אלא) דוקא בהיותו פועל ובבית לבן!\nד. ויש לומר נקודת הביאור בזה:\nאמרו חז\"ל<sup data-n=\"1133\">29</sup> \"צדיקים. . דומין ל­בוראן\", דמזה מובן, שהסברת ענין \"עי­קר דירתו\" של יעקב היא בהתאם ל­המבואר בענין \"דירתו\" של הקב\"ה<sup data-n=\"1134\">30</sup>.\nוהנה ידוע מה שאמרו חז\"ל<sup data-n=\"1135\">31</sup> \"נתאוה הקב\"ה להיות לו דירה בתחתונים\", כלו­מר, \"דירתו\" של הקב\"ה אינה בעולמות עליונים, שהם עולמות רוחניים, אלא דוקא בעולם הזה הגשמי התחתון, ועד, כמ\"ש רבינו הזקן<sup data-n=\"1136\">32</sup>, ש\"הוא התחתון ב­מדריגה שאין תחתון למטה ממנו\".\nוזוהי הכוונה והמטרה של עבודת בנ\"י בכלל, ובפרט בכל משך זמן ה­גלות, שע\"י עבודתם בבירור וזיכוך ה­עולם (בעשיית מצוות בדברים גשמיים, וכן עשיית \"כל מעשיך לשם שמים\" — שעי\"ז מקדשים דברים הגשמיים שבהם עובדים את השם) נעשה העולם כלי הראוי לקדושה העליונה, ובגמר עבודה זו (בביאת המשיח) יהי' כל העולם כולו \"דירה\" להקב\"ה<sup data-n=\"1137\">33</sup>.\nובזה מובן הקשר בין שני הענינים שב\"זבולון\" — (א) השם זבולון, מלשון \"בית זבול\", דירת קבע, (ב) ענינו של זבולון: בעל עסק (ולא יושב אהל) — כי המשכת הקדושה בגשמיות העולם היא בעיקר ע\"י עבודתם של בעלי עסקים<sup data-n=\"1138\">34</sup>, שע\"י שעוסקים בענינים גשמיים של העולם לש\"ש ומקיימים בהם מצות כו', עושים את העולם הזה הגשמי \"דירה\" להקב\"ה; בעבודת זבולון נעשה ה\"בית זבול\" — דירה לו ית'.\nוזהו הטעם של הקדמת זבולון (בעלי עסק) ליששכר (יושבי אהל) — \"שמח זבולון בצאתך (ואח\"כ) ויששכר באהלך\" (כנ\"ל ס\"ב) — לפי שבענין עשיית דירה להקב\"ה, שזהו \"בתחתונים\" דוקא, בגש­מיות העולם \"שאין תחתון למטה ממנו\" —",[["1128","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא רפי\"ח</a>."],["1129","25","תניא אגה\"ק ס\"ז. ולהעיר — ישראל נקרא רק לאחרי עבודתו אצל לבן ומלחמת המלאך דעשו שלאח\"ז וע\"ש נצחונו בכ\"ז (וישלח לב, כט ובפרש\"י שם: ועם אנשים עשו ולבן), לאחרי עשיית הדירה. בכ\"ז הל' (הובא באגה\"ק בנדו\"ד — מב\"מ פד, א. זח\"א לה, ב. ובכ\"מ) שופרי' דיעקב כו'."],["1130","26","ראה ל\"ת להאריז\"ל ר\"פ לך, וביאורו באוה\"ת ח\"ש (קכו, א) שעיקר היחוד הי' ע\"י יעקב שהי' מטתו שלימה. ע\"ש. — וראה ע\"ד הנגלה בית האוצר (להר\"י ענגל) כלל א (סוף אות ד, ועוד)."],["1131","27","ויק\"ר פל\"ו, ה. וראה פסחים נו, א. תו\"כ בחוקותי כו, מב. ספרי ואתחנן ו, ד. האזינו לב, ט."],["1132","28","פסחים, ספרי, ויק\"ר שבהערה הקודמת."],["1133","29","ב\"ר פס\"ז, ח. אסת\"ר פ\"ו, ב. רות רבה פ\"ד, ג. ועוד."],["1134","30","ראה גם אלשיך כאן בפירוש \"יזבלני אישי\" — \"כאשר עשה לזבול שהשרה שם שכינה כן יעשה לי כו'\". וראה צרור המור. ולהעיר מבחיי (ועוד) כאן (ל, כא), ש\"ילדתי לו ששה בנים\" קאי על \"שש קצוות עליונים. . השכינה כלולה משש קצוות\". וראה שם (פסוק כ) השייכות לזבולון דוקא (מלשון \"זבול\"). וראה צרור המור ואלשיך שם."],["1135","31","ראה תנחומא נשא טז. ועוד. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["1136","32","תניא שם."],["1137","33","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>. ע\"ש."],["1138","34","עיין גם תניא אגה\"ק ס\"ה (קט, א­ב) שדוקא ע\"י בעלי מצות העוסקים בצדקה וגמ\"ח \"ממשיכין אור התורה למטה לעולם העשי'\"."]]],[1301410201,"יש יתרון בעבודת זבולון על עבודת יששכר, כנ\"ל.\nוי\"ל שזהו הטעם שאנו רואים כי עד בוא הזמן שמלאכתם נעשית ע\"י אחרים — לאחרי ביאת משיח<sup data-n=\"1139\">35</sup> — רוב בנ\"י הם בעלי עסק ולא יושבי אהל, ובלשון חז\"ל<sup data-n=\"1139\">35</sup> \"הרבה עשו כר' ישמעאל ועלתה בידן כרשב\"י ולא עלתה בידן\" והתורה על הרוב תדבר<sup data-n=\"1141\">36</sup> — כי להשלים מטרה זו — לעשות העולם הזה התחתון דירה לו ית', זה נעשה בעיקר על ידי \"זבולון\" דוקא, כנ\"ל.\nוע\"פ כל הנ\"ל יובן גם בנוגע ליעקב: (א) מכיון שדירתו של הקב\"ה היא בתחתונים דוקא, לכן גם קביעת \"עיקר דירתו\" של יעקב (שצדיקים דומין ל­בוראן כנ\"ל) קשורה דוקא בענינו של \"זבולון\"<sup data-n=\"1142\">37</sup> — עבודה בגשמיות העולם; (ב) פעולתו בהעמדת השבטים — שזה הי' יסודו של עם ישראל כנ\"ל — היתה דוקא ב\"חרן\", \"חרון אף של מקום (בעו­לם)\"<sup data-n=\"1143\">38</sup>, במקום ש\"אין תחתון למטה מ­מנו\", ובזמן כאשר אופן עבודתו של יעקב עצמו הי' בדומה לעבודתו של \"זבולון\" — לא יושב אהל, אלא פועל בבית לבן.\nה. אבל לכאורה עדיין חסר ביאור: סו\"ס הרי ענינו של יעקב הוא תורה כנ\"ל, וכידוע<sup data-n=\"1144\">39</sup> בענין ג' העמודים שעלי­הם העולם עומד, תורה עבודה וגמ\"ח<sup data-n=\"1145\">40</sup>, שהם כנגד ג' האבות, ויעקב הוא כנגד קו התורה — וא\"כ אף שיש יתרון מעלה בזבולון, מ\"מ אין זה טעם, לכאורה, שמעלה זו תכריע בקביעת עיקר מקום דירתו של יעקב — ומהו הקשר וה­שייכות דמעלה זו שבזבולון לענינו של יעקב — תורה?\nויובן זה בהקדם תוס' ביאור במעלת עבודת זבולון, שדוקא על ידי עבודה זו נעשה העולם דירה לו ית'. דלכאורה: מעלת ענינו של זבולון היא רק בעת העבודה — כאשר עסוקים (עדיין) בבי­רור וזיכוך של עניני העולם לעשותם כלים לקדושה עד וקודם שכל העולם כולו ייהפך לדירה לו ית'; אבל לאחרי גמר העבודה, ויקויים היעוד<sup data-n=\"1146\">41</sup> \"ואת רוח הטומאה אעביר מן הארץ\" — הרי אז, אין צורך לכאורה לעבודתו של זבולון ובלשון חז\"ל<sup data-n=\"1139\">35</sup> מלאכתן נעשית ע\"י אחרים [ולהעיר ממ\"ש אדמו\"ר הזקן<sup data-n=\"1148\">42</sup> יתירה מזה שלעת\"ל לא תהי' העבודה לברר טוב מן הרע אלא רק עליות ב­קדושה גופא]; ויתירה מזה הרי בבוא משיח צדקנו יהי' (בלשון הרמב\"ם<sup data-n=\"1149\">43</sup>) \"עסק כל העולם. . לדעת את ה' בלבד\", \"תורתו אומנתו\"<sup data-n=\"1150\">44</sup>.\nונמצא, לכאורה, שעבודת זבולון היא ענין עראי, ואין בה ענין הנצחיות; ו­כיצד מתאים שדוקא ע\"י עבודת זבולון יהי' ענין ה\"דירה\"<sup data-n=\"1151\">45</sup>, \"בית זבול\", דירת קבע (כביכול) של הקב\"ה?",[["1139","35","ברכות לה, ב."],["1139","35","ברכות לה, ב."],["1141","36","מו\"נ ח\"ג פל\"ד."],["1142","37","ואף שבפועל הי' \"עיקר דירתו\" של יעקב באהל רחל דוקא (ראה רש\"י פרשתנו לא, ד. שם, לג. וישלח לה, כב. ועוד) — י\"ל שזהו מפני ש\"אלה תולדות יעקב יוסף\" בנה של רחל. וכל תורתו מסר יעקב ליוסף (פרש\"י וישב לז, ג — מב\"ר פפ\"ד, ח)."],["1143","38","רש\"י ס\"פ נח."],["1144","39","ראה לעיל ע' 121 והערה 56. — וראה תניא אגה\"ק ס\"ז (קיא, סע\"ב) דיעקב \"הי' מרכבה ל­תורה\"."],["1145","40","אבות פ\"א מ\"ב."],["1146","41","זכרי' יג, ב."],["1139","35","ברכות לה, ב."],["1148","42","תניא אגה\"ק סו\"ס כו."],["1149","43","הל' מלכים בסופן."],["1150","44","ראה בארוכה \"הדרן על הרמב\"ם\" (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271251\" data-slug=\"likkutei-sichot\" data-id=\"1300271251\">לקו\"ש חכ\"ז ע' 237</a> ואילך)."],["1151","45","ועאכו\"כ מצד העולם עצמו, דזה שהוא ב­גדר \"תחתון. . בענין הסתר אורו ית'\" (<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>) הוא ענין עראי, עד שהעולם ייעשה דירה לו ית' שאז יתבטל ההסתר ושוב אינו בגדר \"תחתון. . בענין הסתר אורו ית' כו'\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151088\" data-slug=\"likkutei-sichot\" data-id=\"1300151088\">לקו\"ש חט\"ו ע' 88</a> הערה 40 ובשוה\"ג שם."]]],[1301410202,"והי' מסתבר לומר שדירת קבע של הקב\"ה תהי' ע\"י ובענין תורה<sup data-n=\"1152\">46</sup>, שהתורה היא נצחית ולא תהי' מוחלפת<sup data-n=\"1153\">*46</sup>, \"עומדת לעולם ולעולמי עולמים\"<sup data-n=\"1154\">47</sup>.\nו. ויש לומר הביאור בזה:\n\"דירה\" באופן של קבע ונצחיות אמנם לא יתכן אלא בדבר שהוא נצחי, כ­ישראל<sup data-n=\"1155\">48</sup> ותורה, שלהיותם דבוקים בה' הם נצחיים<sup data-n=\"1156\">49</sup>; ומה שה\"דירה\" נעשית דוקא על ידי עבודת זבולון, הוא (לא מצד עצם פעולת הזיכוך ובירור של ה­עולם, שזהו רק ענין עראי, כנ\"ל, אלא) מפני שעל ידי עבודה זו בא לידי גילוי התוקף והנצחיות שבישראל ותורה.\nובהקדם תוכן הכתוב<sup data-n=\"1157\">50</sup> \"מנסה ה\"א אתכם לדעת הישכם אוהבים את ה\"א גו'\", שע\"י נסיונות בא לידי גילוי — תוקף האהבה לה'.\nוע\"ד המבואר במ\"א<sup data-n=\"1158\">51</sup> בביאור דברי הרמב\"ם<sup data-n=\"1159\">52</sup> בענין בעל תשובה ש\"טעם טעם החטא ופירש ממנו וכבש יצרו\" ומעלתו על צדיקים \"שלא חטאו מעולם\" — דמי שלא טעם טעם חטא אינו מובטח שהוא יעמוד בצדקתו בכל המצבים, גם אם יהי' בנסיונות שאינו רגיל בהם כו', ובמילא לא בא לפועל וגם לא לגילוי תוקפו הדרוש לעמידה בנסיונות אלה;\nמשא\"כ בעל תשובה ש\"טעם טעם ה­חטא ופירש ממנו וכבש יצרו\", הרי נת­גלה ובא לפועל תוקפו ולא יכשל עוד הפעם (ובלשון הרמב\"ם<sup data-n=\"1160\">53</sup> \"יעיד עליו יודע תעלומות שלא ישוב כו' לעולם\").\nוכן בעניננו: כל זמן שאין לבנ\"י מו\"מ בעניני העולם לבררם ולזככם, אף ש­עוסקים בתורה ועבודת ה' — בכ\"ז הרי התוקף והנצחיות שבנשמתם לא בא ע­דיין לידי גילוי ועאכו\"כ לא לידי פועל בעבודתם, ולכן אין זו עבודה שתעשה בפועל דירה להקב\"ה.\nדוקא בעבודת זבולון, שעוסק ב\"תח­תונים\" — \"שאין תחתון למטה ממנו בענין הסתר אורו ית'\"<sup data-n=\"1161\">54</sup> — ומ\"מ עוסקים ב­תורה ומקיימים מצוות וכו', ה\"ז מגלה וכו' את התוקף<sup data-n=\"1162\">55</sup>, להיותם דבוקים",[["1152","46","ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא ספל\"ז</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161453\" data-slug=\"likkutei-sichot\" data-id=\"1300161453\">לקו\"ש חט\"ז ע' 440</a> ואילך (ובהערה 57 שם). ועוד."],["1153","*46","ולהעיר מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370531\" data-slug=\"torah-or\" data-id=\"3901370531\">תו\"א בהוספות (קיט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370551\" data-slug=\"torah-or\" data-id=\"3901370551\">וראה שם קכד, א</a>) בטעם שהתורה נק' \"ספר\" — \"שהספר הוא נצחי תמיד בלתי יבוטל לעולם. . אך האגרת אינו נכתב אלא לפי שעה בלבד ולא להתקיים כלל\". וראה שם בענין \"מגילת אסתר\" שנק' \"אגרת\" (כי \"מיד שעלו מן הגלות. . אין טעם להת­לבשות זאת\". ע\"ש), ונק' לפעמים גם בשם \"ספר\" — כי בהעלם יש גם בה ענין הנצחיות. ע\"ש. — וי\"ל שעד\"ז הוא בענין עבודת זבולון (ראה לקמן בפנים)."],["1154","47","ל' הרמב\"ם הל' יסודי התורה רפ\"ט."],["1155","48","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370341\" data-slug=\"torah-or\" data-id=\"3901370341\">תו\"א (עו, ד</a>) ועוד — \"להיות לו ית' דירה בתחתונים והיינו לשכון שכינתו בישראל\". ע\"ש (וכפשוטו של מקרא \"ושכנתי בתוכם\"). וראה בארוכה (לכללות סעיף זה) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161490\" data-slug=\"likkutei-sichot\" data-id=\"1300161490\">לקו\"ש חט\"ז ע' 477</a> ואילך. וש\"נ."],["1156","49","ראה אדר\"נ ספל\"ד."],["1157","50","פ' ראה יג, ד."],["1158","51","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291249\" data-slug=\"likkutei-sichot\" data-id=\"1300291249\">לקו\"ש חכ\"ט ע' 234</a> ואילך. וש\"נ."],["1159","52","רמב\"ם הל' תשובה פ\"ז ה\"ד."],["1160","53","רמב\"ם שם פ\"ב ה\"ב."],["1161","54","ל' התניא פל\"ו."],["1162","55","וי\"ל ששני ענינים בזה: (א) ההעלם וההסתר שבתחתונים מגלה תוקף הנשמה. (ב) מכיון שאמיתית מציאותו של יש הגשמי הוא יש האמיתי (ביאוה\"ז מג, ג ואילך. סה\"מ תרס\"א ע' קצז. ובכ\"מ)<sup data-n=\"e33\">*</sup> — לכן, ע\"י בירור וזיכוך התחתון מתגלה כח העצמות שבישראל (מצד שורש נשמתם). וראה המשך תרס\"ו ע' תצב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121074\" data-slug=\"likkutei-sichot\" data-id=\"1300121074\">לקו\"ש חי\"ב ע' 74</a> ואילך. וראה באתי לגני תשי\"ב (בסה\"מ באתי לגני ח\"א) פ\"ד (וש\"נ)."],["e33","*","כמבואר בכ\"מ שזהו הטעם שדירתו ית' היא בתחתונים דוקא (ראה סה\"מ תרע\"ח ע' קיג ואילך. ד\"ה באתי לגני תשי\"א פ\"ד). — אלא שעצם (ופנימיות) הדירה היא בישראל דוקא (ראה לקו\"ש חט\"ז שם. וש\"נ).\n‑"]]],[1301410203,"בתכלית עם השם. ובזה נעשים \"דירה\" לשכינה באופן קבוע ונצחי<sup data-n=\"1163\">56</sup>.\nוזהו הקשר בין ענין ה\"דירה\" העתי­דה להיות בגמר העבודה (דכל משך זמן הגלות), עם זה שאז \"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד. . יהיו ישראל חכמים גדולים כו'\", לימוד ה­תורה באופן של תורתו אומנתו — כי ענין ה\"דירה\", \"דירת קבע\" של הקב\"ה, מתגלה בעסק התורה של ישראל, אלא כדי שעסק זה יהי' בתכלית השלימות ה\"ז לאחרי העבודה כל משך זמן הגלות.\nוע\"פ הנ\"ל מובן שאין סתירה בין שני הענינים שביעקב — (א) שענינו הוא תו­רה, כנ\"ל, (ב) שלימות הצלחתו באופן ד\"ויפרוץ האיש מאד מאד\" והעמדת שבטי ישראל כו' באו דוקא בעת וע\"י עבודתו בבית לבן — כי: כדי שהתורה תהי' אצל יעקב בקביעות ולתמיד בלי כל הגבלה (\"מאד מאד\") — ה\"ז בא עי\"ז שיעקב הי' ב\"חרון אף של מקום (בעו­לם)\", ושם הי' רועה צאן (פועלו של לבן), שאז נמשך ונתגלה בתורתו ועבו­דתו של יעקב שיהי' \"ויפרוץ האיש מאד מאד\", למעלה מכל מדידה והגבלה.\nז. מענין האמור — שהעילוי הנפעל על ידי עבודת \"זבולון\" בבירור וזיכוך העולם יבא לידי גילוי בלימוד התורה של ימות המשיח — יש גם נפק\"מ ב­מעשה בפועל בעבודתנו עתה:\nאף שבכמות רוב זמנו של \"זבולון\" הוא בהתעסקות בעניני העולם (לשם שמים כו') — מ\"מ, הוא מחוייב לקבוע עתים לתורה, וכן לעסוק בעבודת התפלה.\nוע\"פ המבואר לעיל מובן, שאין ה­פירוש בזה שגם בעלי עסק מחוייבים בלימוד התורה ועבודת התפלה, אלא — שלימות העילוי שבזבולון לגבי יששכר (זה שעל ידי עבודתם עושים דירה ל­הקב\"ה, דירת קבע ונצחי) מתגלה בהם בעבודתם בתורה ותפלה<sup data-n=\"1164\">57</sup>. וי\"ל דהבחי­נה שבהיותו עסוק בעובדין דחול — עבד עבודתו כדבעי ועשה ה\"דירה\", וכ\"ז מאיר באופן קבוע, היא כאשר לימודו ועבודתו ביום השבת (שאז פנוי מפרק­מטיא) היא באופן נעלה ביותר, גם מ­עבודת יושבי אהל.\nויש לומר, שזוהי כוונת רבינו הזקן באגרתו הידועה<sup data-n=\"1165\">58</sup>, ש\"בשבתות וימים טובים שגם כל בעלי עסקים יש להם פנאי ושעת הכושר להאריך בתפלתם ב­כוונת לבם ונפשם לה' ואדרבה עליהם",[["1163","56","עפ\"ז יומתק הלשון \"תמכין דאורייתא\" (וראה אגה\"ק סוס\"ה) — כי זבולון פועל תמיכה וחיזוק בענין התורה, כבפנים. וראה מפרשים הנ\"ל הערה 15 שזבולון הוא \"אכסניא לתורה\".\nואולי י\"ל שע\"י שהם נותנים לפיו של יששכר כו', נפעל בלימוד התורה של יששכר גם העילוי שבעבודת זבולון (ע\"ד שיש לזבולון חלק בתורתו של יששכר)."],["1164","57","ולהעיר מפסק אדה\"ז (הל' ת\"ת פ\"ג ס\"ד) דגם מי ש\"דעתו קצרה\" ומותר לעסוק במו\"מ באופן קבע — צ\"ל המו\"מ \"כדי שיוכל להחזיק ידי ת\"ח שהם לומדי התורה יום ולילה כו' ויהא נחשב לו כאילו למד כן ממש בעצמו כו'\", היינו שגם העסק במו\"מ עצמו צ\"ל לשם לימוד התורה יומם ולילה ו\"נחשב לו כו' ממש בעצמו\"."],["1165","58","תניא אגה\"ק ס\"א."]]],[1301410204,"מוטל ביתר שאת ויתר עז\" — די\"ל ש­כוונתו אינה רק בנוגע להחיוב, שחל עליהם ביתר שאת ויתר עז (מיושבי אהל שיש להם פנאי להאריך בתפלה גם ב­ימות החול), אלא שעבודת התפלה שלהם היא \"ביתר שאת ויתר עז\" מתפלת יושבי אהל.\nוכמו שביאר אדה\"ז במק\"א<sup data-n=\"1166\">59</sup>, ש\"זהו טעות הבעלי עסקים שבדעתם שאין יכולים להתפלל כ\"כ כמו היושבי אוה­לים כי אדרבה נהפוך הוא שהם יכולים להתפלל יותר כי יתרון האור הוא מתוך החושך דוקא\", וכמו שמבאר שם, שדוקא משום שבימי החול טרודים בעניני פר­נסה כו', הנה אח\"כ בעת התפלה יכולים לעורר בעצמם אהבה בלתי מוגבלת (\"ב­כל מאדך\").\nועד\"ז הוא בנוגע לקביעות עתים בתורה — שיש יתרון מעלה בקביעות עתים לתורה של הבעלי עסק מפני \"ש­הוא בחי' אתכפייא יותר מביושבי אוה­לים\"<sup data-n=\"1167\">60</sup>, שזה שהבעל עסק כופה את עצמו כו' (נגד טרדותיו בעניני העולם) לעסוק בתורה, פועל שלימוד התורה שלו הוא באופן נעלה יותר מיושבי אהל.\nוזוהי ההוראה במעשה בפועל לרובם של בנ\"י — שאופן עבודתם הוא ע\"ד העבודה דבעלי עסקים (וגם עוסקים ב­צרכי ציבור הם בכלל זה): לכל לראש צריכים להוסיף בקביעות עתים לתורה, והקביעות צריכה להיות באופן דקביעות בנפש, וביום השבת צריכים גם לעסוק בעבודת התפלה באריכות,\nואין זה דבר נוסף על שליחותם ה­עיקרית לעשות את העולם \"בית זבול\" לו ית', אלא קשורים זב\"ז: העילוי של \"בית זבול\" הנעשה על ידי עבודתם בא לידי גילוי אצלם בלימוד תורתם וב­עבודתם בתפלה ובפרט בהאריכות ביום השבת.\nועל ידי זה מקרבים עוד יותר בוא יום שכולו שבת ומנוחה לחיי העולמים, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ ויקרא תשמ\"ב, ליל ה' דסוכות תשמ\"ג) </span>",[["1166","59","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א ר\"פ נח (ט, סע\"א</a>. וראה גם שם, ב). וראה גם תו\"א <a class=\"ft-cite\" href=\"#/read/torah-or/3901370358\" data-slug=\"torah-or\" data-id=\"3901370358\">תרומה פ, רע\"ג</a>."],["1167","60","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370358\" data-slug=\"torah-or\" data-id=\"3901370358\">תו\"א שם פ, ג</a>."]]],[1301410205,"<h3>שיחה ג</h3>\nא. עה\"פ<sup data-n=\"1168\">1</sup> \"ויקם יעקב וישא את בניו ואת נשיו על הגמלים\" מעתיק רש\"י \"את בניו ואת נשיו\" ומפרש \"הקדים זכרים לנקבות ועשו הקדים נקבות לזכרים שנאמר<sup data-n=\"1169\">2</sup> ויקח עשו את נשיו ואת בניו וגו'\".\nמשטחיות לשון רש\"י נראה, שבפי­רושו זה כוונתו לבאר השינוי שבין שני הכתובים — שביעקב נאמר \"את בניו (ואח\"כ) ואת נשיו\", ובעשו להיפך — \"את נשיו (ואח\"כ) ואת בניו\".\nאבל, כמדובר כמ\"פ: כאשר ישנה אי­זו קושיא וסתירה בפשש\"מ מכתוב אחד לשני, אין רש\"י בפירושו עומד עלי' לתרצה בפסוק הראשון, מכיון שאין קושיא עדיין, אלא בפסוק השני, במקום שמתעוררת השאלה. ועפ\"ז אינו מובן בנדו\"ד, מהי הקושיא בכתוב כאן שיש צורך בפירוש וביאור, ואשר בגללה הוזקק רש\"י להביא כאן ע\"ד הנהגת עשו המסופרת לקמן בפ' וישלח?\n[מקורו של רש\"י הוא אמנם מהמדרש עה\"פ כאן<sup data-n=\"1170\">3</sup>, אבל פרש\"י הרי ענינו, לכל לראש, הוא פשוטו של מקרא, ואין דרכו להעתיק אלא מדרשים המוכרחים ב­פשש\"מ<sup data-n=\"1171\">4</sup>].\nב. גם צריך להבין:\nלכאורה אין בדברי רש\"י הסברה ב­טעם השינוי בין הכתובים הנ\"ל; רש\"י רק מדגיש במה הוא השינוי, שיעקב הקדים זכרים לנקבות ועשו הקדים נקבות לזכרים, אבל אינו מבאר תוכנן של הנהגות אלו, למעליותא או לגרי­עותא.\nמפרשי רש\"י<sup data-n=\"1172\">5</sup> מבארים, \"כי עשו. . הי' מקדים נשיו<sup data-n=\"1173\">6</sup> קודם בנים דנשיו היו עיקר דעתו רק כי הבנים יצאו ממנו בסבת תאות נשיו<sup data-n=\"1174\">7</sup> אבל יעקב לא נשא נשיו רק בשביל להעמיד תולדות שנים עשר שבטים ובניו היו גורמים לישא אשה לכך בניו קודמים שהם הסיבה לנשיו ועשו הנשים הם סיבה לבניו כו'\".\nועפ\"ז אתי שפיר הא דלא ביאר רש\"י ענין זה בפירושו כאן, כי כבר נתפרש הבדל זה בין הנהגות יעקב ועשו בפי­רוש רש\"י לפנ\"ז: הן אודות הנהגת עשו בתאוות נשים, ש\"כל מ' שנה הי' עשו צד נשים מתחת יד בעליהן ומענה אותם\"<sup data-n=\"1175\">8</sup> (שמזה מובן גם בנוגע להנהגתו לאחר נישואיו); והן בנוגע להנהגתו ההפכית של יעקב, ש\"לא נשא נשיו רק בשביל להעמיד תולדות\" — מפורש כבר לעיל, דלא נשא אשה עד היותו בן פ\"ד שנה כאשר \"מלאו ימי\" ואמר \"אימתי אעמיד",[["1168","1","פרשתנו לא, יז."],["1169","2","וישלח לו, ו."],["1170","3","ב\"ר פרשתנו (פע\"ד, ה. וראה מת\"כ שם)."],["1171","4","ולהעיר שבמדרש הובא דרש זה עוה\"פ עה\"כ דפ' וישלח (ב\"ר פפ\"ב, יג), משא\"כ בפרש\"י שם."],["1172","5","גו\"א (וראה גם רא\"ם) כאן. ועד\"ז הוא בפירוש ר\"א בן הרמב\"ם כאן. ומסיים: וזה דרש נעים."],["1173","6","וראה גם מדרש שכל טוב פרשתנו עה\"פ: אבל עשיו ויקח את נשיו תחלה לזנות ואח\"כ את בניו."],["1174","7","ולהעיר מפרש\"י בראשית ד, יט: כך הי' דרכן של דור המבול כו'."],["1175","8","פרש\"י תולדות כו, לד."]]],[1301410206,"י\"ב שבטים\"<sup data-n=\"1176\">9</sup> (ועד אז עסק בתורה<sup data-n=\"1177\">10</sup>, וב­אופן ש\"לא שכב בלילה\"<sup data-n=\"1178\">11</sup>), וזו היתה כוונתו באמרו ללבן \"הבה את אשתי גו'\"<sup data-n=\"1179\">12</sup>, שרק \"להוליד תולדות אמר כך\"<sup data-n=\"1180\">13</sup>.\nאבל עפ\"ז אינו גלאַטיק לאידך גיסא: מה מחדש רש\"י בפירושו זה? הרי ה­הבדל התוכני שבין שני אופני הקדימה אין הוא מבאר בפירושו כאן אלא סומך על המובן ממה שפירש כבר לפנ\"ז; וב­נוגע לעצם השינוי בקדימה אין צורך בהערת רש\"י, כי הוא דבר המפורש בה­כתוב עצמו (שביעקב נאמר \"בניו\" קודם ל\"נשיו\" ובעשו נאמר להיפך).\nג. עוד צריך להבין (כמו שהאריכו במפרשים<sup data-n=\"1181\">14</sup>): גם ביעקב נאמר<sup data-n=\"1182\">15</sup> \"ויקח את שתי נשיו ואת שתי שפחותיו ואת אחד עשר ילדיו\", הרי מפורש שגם יעקב הקדים נשיו לילדיו, ורש\"י אינו מעיר ע\"ז כלום!\nעד\"ז מצינו לעיל<sup data-n=\"1183\">16</sup> שכשאמר יעקב ללבן \"שלחני ואלכה גו'\" הקדים נשיו לילדיו — \"תנה את נשי ואת ילדי\"<sup data-n=\"1184\">*16</sup>; וכן לקמן גבי משה נאמר<sup data-n=\"1185\">17</sup> \"ויקח משה את אשתו ואת בניו\".\nואף שבמפרשים<sup data-n=\"1181\">14</sup> האריכו בטעמי ה­חילוקים שבין כתובים אלו להנאמר ב­כתוב זה — מ\"מ, עדיין אינו מובן: לאחרי שרש\"י כותב באופן סתמי שיעקב \"הקדים זכרים לנקבות\", דהיינו שזוהי ההנהגה המתאימה לאיש צדיק — איך יתכן שרש\"י יסתום בכל מקומות הללו ולא יפרש במה שונים הם להיות יוצאים מן הכלל שכלל רש\"י שיעקב \"הקדים זכרים לנקבות\"?\n[וכמדובר כמ\"פ, שזה גופא שמצינו שקו\"ט ארוכה במפרשי רש\"י, זה מתרץ בכה וזה בכה כו', מכריח לומר שישנה הסברה פשוטה ביותר השוללת מעיקרא כל אריכות השקו\"ט; שהרי לא מסתבר לומר שרש\"י סותם וסומך שהבן חמש למקרא יעמוד על תירוצי המפרשים — כאשר במפרשים עצמם יש שקו\"ט דזה בונה וזה סותר].\nד. ויש לומר, שרש\"י מתרץ כל זה בדיוק לשונו \"הקדים זכרים לנקבות ועשו הקדים נקבות לזכרים\" — דלכ­אורה אינו מובן, מדוע לא נקט רש\"י לישנא דקרא: \"בניו. . נשיו\", \"נשיו. . בניו\"?\nאלא שכוונתו בזה להדגיש, דזה ש­יעקב הקדים לקיחת בניו הוא לא משום שבתור בניו (זרעו) החשיבם יותר מנשיו\n— שהרי אדרבה: הסדר הרגיל וה­מתאים הוא — שאדם מקדים אשתו ל­ילדיו, הן מפני שאשתו ה\"ה אמם, ובאה לפני בניו (ומפני כבוד אשתו<sup data-n=\"1187\">18</sup>), והן<sup data-n=\"1188\">19</sup> —",[["1176","9","פרשתנו כט, כא ובפרש\"י. וראה גם פרש\"י (ורש\"י ישן) ס\"פ תולדות."],["1177","10","כמ\"ש (תולדות כה, כז) ויעקב איש תם יושב אהלים, אהלו של שם ואהלו של עבר (רש\"י שם). וראה גם רש\"י (ורש\"י ישן) ס\"פ תולדות הנ\"ל. פרש\"י ריש פרשתנו (כח, יא ד\"ה וישכב). רש\"י וישלח לה, כט."],["1178","11","פרש\"י ריש פרשתנו שם."],["1179","12","פרשתנו כט, כא."],["1180","13","פרש\"י שם."],["1181","14","גו\"א. לבוש. דברי דוד (להט\"ז). וכ\"ה ב­ביאורי מהרא\"י (לבעל תרומת הדשן) וישלח (לב, כג). מלאכת הקודש על פרש\"י כאן. ועוד."],["1182","15","וישלח לב, כג."],["1183","16","פרשתנו ל, כה­ו."],["1184","*16","אבל בזה י\"ל בפשטות, כי שם ההדגשה (כהמשך דבריו) \"אשר עבדתי אותך בהן\", ובזה נשיו העיקר."],["1185","17","שמות ד, כ."],["1181","14","גו\"א. לבוש. דברי דוד (להט\"ז). וכ\"ה ב­ביאורי מהרא\"י (לבעל תרומת הדשן) וישלח (לב, כג). מלאכת הקודש על פרש\"י כאן. ועוד."],["1187","18","להעיר ד\"צוו חכמים שיהי' אדם מכבד את אשתו יותר מגופו\" (רמב\"ם הל' אישות פט\"ו הי\"ט. שו\"ע אדה\"ז חו\"מ סוף הל' אונאה. וש\"נ)."],["1188","19","להעיר מפרש\"י וישלח לג, ז."]]],[1301410207,"שאם יקדים אותם לפני אשתו, ה\"ז היפך ההדרכה בהנהגה של כיבוד אם —\nאלא מפני שהקדים זכרים לנקבות<sup data-n=\"1189\">20</sup>, כי בחיי (והתעסקותו של) יעקב הזכרים הם העיקר, כמובן בפשטות.\nוזהו הטעם שבכל הכתובים (גם גבי יעקב) שמצינו בהם קדימת הנשים לה­ילדים לא פרש\"י מאומה, כי אין בהם שאלה, שהרי זוהי ההנהגה המתאימה (ל­הקדים האם להילדים);\nהשאלה מתעוררת דוקא בפסוק דילן \"וישא את בניו ואת נשיו\" — שהקדים בניו לנשיו, היפך סדר הבריאה<sup data-n=\"1190\">21</sup> וכיבוד אם (והיפך כבוד אשתו)? [וכמובן שאין התמי' (מצד כיבוד אם) על בני יעקב עצמם — איך עלו על הגמלים לפני אמותיהם, כי פשוט שלא יכלו לסרב ולהתנגד לרצון יעקב אביהם<sup data-n=\"1191\">22</sup>, אלא ה­שאלה היא בנוגע להנהגת יעקב, כיצד הורה להם לעלות על הגמלים לפני אמותיהם, הרי הנהגה זו היא היפך כ­הנ\"ל?]<sup data-n=\"1192\">23</sup>.\nולכן מבאר רש\"י \"הקדים זכרים ל­נקבות\" — ומשנה מלשון הכתוב \"בניו. . נשיו\" — דהקדמת \"זכרים לנקבות\" מכ­ריחה וקובעת אפילו כשהמדובר (כב­קרא זה) — קדימת בניו לנשיו (שהם אמותיהם)<sup data-n=\"1193\">*23</sup>.\nה. אבל רש\"י אינו מסתפק בזה לחוד — כי אין בהנהגה זו של יעקב (שאצלו היו הזכרים העיקר) חידוש, לכאורה<sup data-n=\"1194\">24</sup>.\nולכן ממשיך רש\"י \"ועשו הקדים נקבות לזכרים שנאמר ויקח עשו את נשיו ואת בניו וגו'\"; שינוי והדגשה זו בפרש\"י באה להדגיש את ההבדל וה­הפרש שבין הנהגת יעקב והנהגת עשו (גם בענין זה), כי \"עשו הקדים נקבות לזכרים\".\nכלומר:\nכשלומדים אודות הנהגת עשו \"ויקח. . את נשיו ואת בניו ואת בנותיו\", הי' מקום לומר, שהטעם שהקדים עשו נשיו לבניו ובנותיו הוא מפני שכלפי חוץ",[["1189","20","ראה גם ספר זכרון פרשתנו כאן."],["1190","21","אין לומר דהכוונה ב\"וישא את בניו ואת נשיו על הגמלים\" אינה הפעולה הגשמית ד\"וישא\" (העלי' וישיבה על הגמלים, או נטילתם (ראה ת\"א כאן) בפועל על הגמלים) — אלא \"וישא גו' על הגמלים\" הוא הסיפור והתיאור (הכללי) של בריחת (והליכת) יעקב ומשפחתו מבית לבן וקדימת בניו לנשיו בקרא אינה אלא קדימה במעלה, שאנשי משפחתו של יעקב נמנו בקרא לפי סדר חשיבותם — אבל בנוגע לעלי' על הגמלים וכו' בפועל, הקדים יעקב נשיו,\nכי מופרך לגמרי לפרש כן, כי זהו היפך ה­מפורש בקרא."],["1191","22","והרי אפילו כאשר אמו מבקשת בפירוש — כיבוד אב קודם \"שאתה ואמך חייבים בכבוד אביך\" (קדושין לא, א. וש\"נ)."],["1192","23","משא\"כ בהכתוב ויגש (מו, ה), דזה שמקדים שם הילדים לנשיהם, הוא לפי שנאמר \"וישאו בני ישראל את יעקב אביהם ואת טפם ואת נשיהם בעגלות גו'\", ולכן הוקדם בכתוב — זה שזקוק יותר לעגלות. וכן משמע ממ\"ש שם מה, יט."],["1193","*23","הטעם שדוקא כאן הקדים זכרים לנקבות והכריע גם נגד קדימת נשיו לילדיו — יש לומר: כאן המדובר בהליכתו מבית לבן לשוב אל ארץ אבותיו ומולדתו, והיינו חיים באופן של התיישבות וקביעות, ובכללות חיי יעקב היו הזכרים העיקר; משא\"כ כשמדובר בעצם פעולת הלקיחה (וכיו\"ב), הרי מצד כבוד אם וכו' ההנהגה המתאימה היא ליקח נשיו תחלה ואח\"כ ילדיו, כנ\"ל בפנים. וראה גו\"א כאן בסופו."],["1194","24","וא\"כ למה מדגיש הכתוב קדימת הזכרים, והול\"ל באופן סתמי וכללי \"ויקח את משפחתו\" או \"אנשי ביתו\" וכיו\"ב."]]],[1301410208,"העמיד פנים כאיש המתנהג בכבוד וב­נימוס, וכפי שדייק בכיבוד אב, שלא ל­צער את אביו<sup data-n=\"1195\">*24</sup>, ואדרבה, השתדל לג­רום לו נח\"ר<sup data-n=\"1196\">25</sup> וכבוד כו'. וכן בעניננו, שכאשר לקח משפחתו עמו, התנהג בני­מוס ובדרך ארץ והקדים את נשיו לבניו ובנותיו.\nוזהו שרש\"י מחדש — שהטעם שעשו לקח נשיו תחלה הי' (לא מצד הנהגתו בדרך ארץ ובנימוס, כ\"א) מפני ש\"הקדים נקבות לזכרים\"<sup data-n=\"1197\">*25</sup>.\n[ועפ\"ז יומתק עוד דיוק בפירש\"י זה, שבהביאו את הכתוב בנוגע לעשו מדייק לכתוב \"ויקח עשו את נשיו ואת בניו וגו'\"<sup data-n=\"1198\">26</sup>, שתיבת \"וגו'\" מכוונת להמשך ה­כתוב \"ואת בנותיו\" — ומ\"מ לא העתיקו בפירוש.\nוהיינו, מכיון שלפי פירש\"י לא היתה הקדמת נשיו לבניו אלא רק משום \"שהקדים נקבות לזכרים\", הרי מעתה אין מקום להביא סיומו של הכתוב \"ואת בנותיו\", כי הוא כעין ראי' לסתור (ש(בנוגע לזרעו,) גם עשו הקדים בניו לבנותיו<sup data-n=\"1199\">27</sup>)].\nו. מיינה של תורה בפרש\"י:\nהטעם הפנימי לכך שרש\"י מביא ע\"ד הנהגת עשו — \"ועשו הקדים נקבות לזכרים\", בפסוק המדבר אודות יעקב — יש לומר, בהקדים:\nאע\"פ שע\"פ סדר התורה קדימה ל­זכרים, ובלשון הכתוב<sup data-n=\"1200\">28</sup> \"והוא ימשל בך\" — מ\"מ מצינו לפעמים גם קדימה לנקבות, וכמפורש<sup data-n=\"1201\">29</sup> לפני זה בנוגע ל­ראשון שבאבות אברהם. ואדרבה — אחד מהיעודים דלעתיד הוא שאז \"נקבה תסובב גבר\"<sup data-n=\"1202\">30</sup> (וכמבואר בזה<sup data-n=\"1203\">31</sup>, שאז תתגלה מעלת הנשים).\nועפ\"ז י\"ל שזהו הרמז במה שהביא רש\"י כאן ענין זה דהקדמת נקבות ל­זכרים (בעשו) — כי גם ביעקב, סדר ד­קדושה, ישנה הנהגה כזו, אלא שזהו לא בעבודת יעקב מצ\"ע, אלא \"עבודת עשו\" שביעקב.\nוהענין: נת' במ\"א<sup data-n=\"1204\">32</sup> שגם עשו, להיותו בנו של יצחק, נולד עם כחות ויכולת לעבוד את השם<sup data-n=\"1205\">33</sup> לפי דרכו המיוחדת ב­התאם לטבעו ותכונות נפשו<sup data-n=\"1206\">34</sup>, ויתירה",[["1195","*24","ראה פרש\"י תולדות כז, מא. ועוד."],["1196","25","ראה תולדות כה, כח ובפרש\"י. וראה גם פרש\"י כח, ז. ריש פרשתנו."],["1197","*25","וגם שם אצל עשו מדובר בלקיחתם ע\"מ לילך להתשייב במק\"א — ראה לעיל הערה *23."],["1198","26","כ\"ה בדפוסי רש\"י שלפנינו ובכמה כת\"י רש\"י (שתח\"י). אבל בדפוס ראשון ודפוס שני וכמה כת\"י רש\"י (שתח\"י) ליתא \"וגו'\"."],["1199","27","אלא שע\"פ הביאור הנ\"ל בתוכן הענין מובן שאין זו קושיא, כי מה שהקדים עשו נקבות לזכרים הוא מפני תאוותו — ודבר זה לא מצינו בעשו (עצמו*) ביחס לבנותיו (ע\"ד שמצינו אצל לוט — וירא יט, לג ואילך. וראה רש\"י שם, לג).\nולכן כתב רש\"י \"וגו'\" (לכמה גירסאות), לעורר ולהדגיש שלמרות המשך הכתוב \"ואת בנותיו\" — אין מזה סתירה לפירושו."],["1200","28","בראשית ג, טז."],["1201","29","וירא כא, יב ובפרש\"י. וראה פרש\"י פרשתנו כט, לד."],["1202","30","ירמי' לא, כא. וראה מפרשים שם."],["1203","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381191\" data-slug=\"likkutei-torah\" data-id=\"4001381191\">לקו\"ת שה\"ש טו, ג</a>. ובכ\"מ."],["1204","32","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201114\" data-slug=\"likkutei-sichot\" data-id=\"1300201114\">לקו\"ש ח\"כ ע' 114</a>. וש\"נ. לעיל ע' 114."],["1205","33","להעיר מהציווי: ואהבת גו' בכל לבבך בשני יצריך (פרש\"י ואתחנן ו, ה)."],["1206","34","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201108\" data-slug=\"likkutei-sichot\" data-id=\"1300201108\">לקו\"ש שם ע' 108</a> ואילך, ולעיל שם (ושם, דזה שעשו הי' \"מתרוצץ\" במעי אמו לע\"ז, היינו מפני שעבודתו היתה צ\"ל באופן ד\"כובש את יצרו\" (רמב\"ם שמונה פרקים פ\"ו). ע\"ש באורך)."]]],[1301410209,"מזה הי' בכור לעבודה להקב\"ה<sup data-n=\"1207\">35</sup>.\nאלא שבבחירתו החפשית \"יצא\" ו­נפרד<sup data-n=\"1208\">36</sup> מקדושת יצחק.\nוזהו הרמז בלשון רש\"י<sup data-n=\"1209\">37</sup> — \"ואלה תולדות יצחק, יעקב ועשו האמורים בפרשה\": זה שעשו הוא אחד מ\"תולדות יצחק\" (מתייחס אליו כבנו), הוא (רק) עשו ה\"אמור בפרשה\", היינו עשו כפי שהיתה צ\"ל עבודתו והנהגתו ע\"פ תורה.\nומכיון שעשו נפרד מקדושת יצחק, הרי גם עבודת עשו הייתה צריכה ל­העשות ע\"י יעקב — נוסף על עבודת יעקב מצד עצמו, עליו לעשות גם ה­עבודה — בקדושה — שמתחילה נועדה לעשו.\nועד\"ז י\"ל בעניננו: זה שהנהגת עשו בקדימת נקבות לזכרים היא הנהגה גרועה ושפלה כו' — הוא כפי שעשו יצא ונפרד מקדושת יצחק; אבל הנהגה זו יש בה ג\"כ אופן למעליותא כפי שעשו (ועבודתו) \"אמור בפרשה\"<sup data-n=\"1210\">38</sup>.\nז. ההסברה בזה:\nזכר ונקבה — איש ואשה — מורים גם על שני אופנים בעבודת השם, עבודת המוח ועבודת הלב. וע\"ד החילוק בזה בין איש ואשה, שעיקר ענין המוחין (והלימוד) הוא בהאיש<sup data-n=\"1211\">39</sup>, וייחודה של האשה (לגבי האיש) הוא בענין הרגש והמדות.\nומעלה בכל אחד:\nמעלת המוחין והשכל היא — שהאדם רואה ותופס בעין שכלו אמיתית הדבר כמו שהוא (בלי תערובת \"שוחד\" ונטיות טבע האדם); משא\"כ רגש האדם ומדותיו \"תופסים\" הדבר בהתאם לנטיות ורצונות האדם;\nולאידך יש מעלה במדות על השכל, כי טבע השכל הוא ענין הקרירות, בלי התפעלות, ובמילא במדידה והגבלה; משא\"כ כשיש לאדם רגש באיזה ענין, הרי מצד החמימות וההתפעלות בזה הת­קשרותו והתעסקותו בהענין היא בתוקף גדול.\nועד\"ז החילוק בין שני הסדרים — הקדים זכרים לנקבות, או נקבות ל­זכרים:\nסדר הבריאה בכלל הוא באופן ד\"הוא ימשל בך\" (זכרים קודם לנקבות) — כי הסדר הרצוי הוא, אשר המוח ישלוט על הלב<sup data-n=\"1212\">40</sup>, כלומר, המדות צרי­כות להיות (אבל צ\"ל) מונהגות ע\"י השכל. כי אם ילך האדם אחרי נטיות לבו, עלול הדבר להזיק לא רק למוח ש­בראש אלא גם לרגש שבלב עצמו; ורק כאשר המדות מונהגות ומודרכות ע\"י",[["1207","35","תולדות כה, לד. ובפרש\"י."],["1208","36","פסחים נו, א. ועוד. לקו\"ת ואתחנן ה, א. ועוד."],["1209","37","ר\"פ תולדות."],["1210","38","להעיר עד\"ז משעטנז — איסור חמור (במו\"נ ח\"ג פל\"ז \"כי כן הי' תיקון הכומרים\" לע\"ז. וראה ברכות יט, ב. רמב\"ם הל' כלאים פ\"י הכ\"ט), בבגדי כהונה — מוכרח (רמב\"ם סוף הל' כלאים. הל' כלי המקדש פ\"ח הי\"א­יב), בציצית — מותר (יבמות ד, רע\"א. פרש\"י תצא כב, יב. רמב\"ם הל' כלאים פ\"י ה\"ד)."],["1211","39","שלכן האיש מצווה בת\"ת משא\"כ אשה \"אינה במצות ת\"ת\" (הל' ת\"ת לאדה\"ז ספ\"א. ע\"ש. וש\"נ).\nוכבר שקו\"ט במפרשים בהא (נדה מה, ב) דנתן הקב\"ה בינה יתירה באשה יותר מבאיש (ראה מפרשי הע\"י שם). ואכ\"מ."],["1212","40","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב</a>. ובכ\"מ."]]],[1301410210,"השכל שבמוח, אזי חמדת הלב (ובמילא הנהגת האדם) היא כדבעי.\nאמנם לפעמים ישנו מצב שהאדם מוכרח לעבוד את קונו למעלה מכפי הסדר דטעם ודעת, והוא כאשר רבו ה­העלמות וההסתרים ומנגדים לעבודת השם, שאז אינו מספיק לעבוד את ה' באופן מדוד ומוגבל ע\"פ טעם ודעת, אלא זקוקים לעבודה נעלית יותר, של­מעלה מהגבלת השכל. וזה מתגלה ב­עבודת הלב דוקא (וכידוע<sup data-n=\"1213\">41</sup> שעצם ה­נפש מתגלה בלב דוקא, ולא במוח).\nוזהו הרמז בפרש\"י שיעקב \"הקדים זכרים לנקבות ועשו הקדים נקבות לזכרים\": עבודתו של יעקב, \"איש תם יושב אהלים\"<sup data-n=\"1214\">42</sup>, היא עבודה ע\"פ סדר, זכרים לפני נקבות, תחילה עבודת המוח ועי\"ז בא לעבודת הלב (והלב משפיע על שאר חלקי הגוף);\nאבל בעבודת עשו — \"איש שדה\"<sup data-n=\"1215\">43</sup>, עבודה במקום של העלמות והסתרים<sup data-n=\"1216\">44</sup> — הסדר הוא להיפך, נקבות לפני הזכ­רים, כי בעבודה זו אי אפשר להסתפק בעבודה שבמדידה והגבלה ע\"פ הסדר, אלא צ\"ל עבודה שלמעלה מסדר, של­מעלה ממדידה והגבלה, כנ\"ל.\nוי\"ל שזהו גם אחד הביאורים בזה שלעתיד לבוא \"נקבה תסובב גבר\" — כי, כל<sup data-n=\"1217\">45</sup> הגילויים דלעתיד לבא תלויים \"ב­מעשינו ועבודתנו כל זמן משך הגלות\", והיינו שאז יתגלו כל העילויים שנעשו על ידי עבודתנו בזמן הגלות. ואחד מה­עילויים העיקריים בהעבודה בזמן הג­לות — ובפרט בגלותנו זה האחרון (גלות עשו, אדום) שרבו בו ההעלמות וההסת­רים וכו' — היא העבודה דמסירת נפש<sup data-n=\"1218\">46</sup>, שלמעלה מטעם ודעת, המתגלית בעיקר בלב.\nח. עפ\"ז יש לבאר גם הטעם הפנימי שענין זה — ש\"עשו הקדים נקבות ל­זכרים\" — הובא ברש\"י בקשר לסיפור בריחת יעקב מלבן והכנתו לפגוש את עשו:\nמבואר בכ\"מ<sup data-n=\"1219\">47</sup> הטעם ששלח יעקב מלאכים לעשו (כמסופר בפ' הסמוכה, וישלח<sup data-n=\"1220\">48</sup>), כי יעקב הי' כבר מוכן אז לה­מצב דלעתיד, שאז יהי' \"ועלו מושיעים בהר ציון לשפוט את הר עשו\"<sup data-n=\"1221\">49</sup>, אלא שאח\"כ הודיעו המלאכים ליעקב שעשו הוא עדיין במדריגה תחתונה ביותר, ואדרבה, \"הולך לקראתך וארבע מאות איש עמו\"<sup data-n=\"1222\">50</sup> — היינו שהוא במצב הפכי לגמרי, ובמילא עדיין צריכים לעבור את גלות עשו (אדום), ושלימות הבירור יהי' בימי המשיח, כמו שפירש\"י בפ' וישלח<sup data-n=\"1223\">51</sup>.\nוזהו הרמז בפרש\"י כאן, גבי בריחת יעקב מלבן: כאשר נגמרה גלותו של יעקב אצל לבן (דהיינו, שיעקב גמר עבודתו אצלו ונגמר בירורו של לבן) והותחלו הכנותיו של יעקב לעבודתו עם",[["1213","41","המשך תרס\"ו ע' ס ואילך. ובכ\"מ."],["1214","42","תולדות כה, כז. וראה פרש\"י שם ד\"ה תם."],["1215","43","תולדות שם."],["1216","44","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201110\" data-slug=\"likkutei-sichot\" data-id=\"1300201110\">לקו\"ש ח\"כ ס\"ע 110</a> ואילך. ע' 113 ואילך."],["1217","45","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1218","46","ראה ד\"ה אין הקב\"ה בא בטרוניא (סה\"מ תרפ\"ה ע' רנז. סה\"מ אידיש בתחלתו). ד\"ה אני ישנה תש\"ט. ועוד."],["1219","47","ראה תו\"א ותו\"ח פ' וישלח."],["1220","48","לב, ד ואילך."],["1221","49","עובדי' א, כא — הפטורת פ' וישלח."],["1222","50","וישלח לב, ז."],["1223","51","לג, יד בסופו (ומביא פסוק הנ\"ל דעובדי')."]]],[1301410211,"עשו, הרי כפי שראה יעקב את עשו — ראהו כפי שהוא בשרשו (\"אמור בפר­שה\" —), דהיינו כפי שהוא אחר הבירור והזיכוך כבשרשו ומוכן להגאולה, שאז תהי' הקדמת \"נקבות לזכרים\" למעל­יותא, \"נקבה תסובב גבר\",\nכן תהי' לנו בביאת משיח צדקנו, בקרוב ממש.\n<span data-k=\"q\">(משיחות ש\"פ ויצא, וישלח תשמ\"ב, ש\"פ נשא תשד\"מ) </span>"],[1301410212,"<h3>שיחה א</h3>\nא. באיסור גיד הנשה נתפרש בתורה שבכתב גם טעם האיסור<sup data-n=\"1224\">1</sup> — \"על כן לא יאכלו בני ישראל את גיד הנשה אשר על כף הירך עד היום הזה כי נגע בכף ירך יעקב בגיד הנשה\"<sup data-n=\"1225\">2</sup>.\nוטעם זה גם קובע פרטי אופן ה­איסור: אין האיסור אלא על הגיד שעל כף הירך<sup data-n=\"1226\">3</sup>; עוף — שאין לו כף הירך — גידו מותר<sup data-n=\"1227\">4</sup>; יש פלוגתא בין ר' יהודה וחכמים<sup data-n=\"1228\">5</sup> אם גיד הנשה נוהג רק בירך של ימין או גם בירך של שמאל, וטעם הפלוגתא<sup data-n=\"1229\">6</sup> — שלדעת ר\"י נגע המלאך רק בירך ימין של יעקב, וחכמים ס\"ל ד\"נשיי' בתרווייהו\" (\"הכהו בשתיהם עד שנשו ממקומם ועלו\"<sup data-n=\"1230\">7</sup>) ולכן נאסרו שתי­הן.\nוצריך ביאור:\nבביאור הטעם שבכתוב \"על כן לא יאכלו גו' כי נגע גו'\" איתא במפרשים<sup data-n=\"1231\">8</sup>, שהוא \"לזכרון גבורתו של יעקב ונס ש­עשה לו הקב\"ה כו'\", כלומר, אין זה רק זכר לנגיעת מלאכו של עשו בכף ירך יעקב, אלא על כללות המאורע דמלחמת יעקב והצלתו מיד המלאך.\nוהטעם שעושים זכר על הצלה זו דוקא — אף שמצינו מפורש בתושב\"כ כמה נסים ועניני הצלה באברהם, וגם ביעקב עצמו, ומ\"מ לא נקבע עליהם זכר לדורות — מובן ממ\"ש החינוך<sup data-n=\"1232\">9</sup> (ועוד מפרשים<sup data-n=\"1233\">10</sup>) ב\"שרשי\" מצוה זו, שהוא \"רמז לישראל שאע\"פ שיעברו צרות רבות בגלות מיד העמים ומיד בני עשו שיהיו בטוחים שלא יאבדו אלא לעולם יעמוד זרעם כו'\". והיינו שהצלה זו קשורה עם ענין כללי ביותר בחיי עם ישראל.\nולפ\"ז יש להבין: כשעושים \"זכר\" ל­מאורע או ענין מסוים צ\"ל המזכיר דומה לענין הנזכר — כמו זכר ליציאת מצרים בחג הפסח, שהוא ע\"י שעושים \"כל מעשה לילה זה דרך חירות\"<sup data-n=\"1234\">11</sup>; זכר ל­מעשה בראשית בשבת ע\"י השביתה מ­מלאכה כו';\nמדוע, א\"כ, הזכר לדבר יסודי וכללי כזה (הצלת יעקב שהיא רמז על הצלת כלל ישראל מיד בני עשו) הוא רק באיסור פרטי דגיד הנשה<sup data-n=\"1235\">12</sup> (שהוא רק פרט אחד של המאורע<sup data-n=\"1236\">13</sup>); ויתירה מזו:",[["1224","1","וראה לקמן בסוף הסעיף."],["1225","2","פרשתנו לב, לג."],["1226","3","כדעת רבנן (חולין צו, א­ב). וכ\"ה ההלכה — רמב\"ם הל' מאכלות אסורות פ\"ח ה\"ב. רמ\"א יו\"ד ר\"ס ק."],["1227","4","משנה חולין פט, ב. וראה שם צב, ריש ע\"ב ד\"אית לי' ולא עגיל\"."],["1228","5","משנה חולין שם ושם צ, ב."],["1229","6","חולין צא, א. וראה ב\"ר פע\"ח, ו ובמ\"כ (ועוד) שם."],["1230","7","רש\"י חולין שם ד\"ה ורבנן."],["1231","8","רשב\"ם עה\"פ. ועד\"ז בכמה מפרשים."],["1232","9","מצוה ג."],["1233","10","ראה רמב\"ן (לב, כו), אברבנאל ועוד."],["1234","11","ל' אדה\"ז שו\"ע או\"ח סתע\"ב סוס\"ז."],["1235","12","משא\"כ לפי הטעם שבחזקוני עה\"פ (וכ\"ה בתוס' דעת זקנים ועוד מפרשים) — \"שיש לקנוס ולענוש בנ\"י מאכילת גיד הנשה שהניחו אביהם הולך יחידי\", או דכיון \"שהוזק יעקב בגיד הנשה קבלו עליהם בניו. . שלא יאכלו ממנו\" — שלפ\"ז נוגע מקום ההיזק. וראה ע\"ד הקבלה והחסידות — סהמ\"צ להצ\"צ מצות גיד הנשה (וש\"נ). ועוד."],["1236","13","ועוד: גיד הנשה הוא מקום ההיזק היפך ההצלה (אף שי\"ל שבא להדגיש שההיזק הי' רק בזה (ראה ספורנו, אברבנאל ועוד), או שלמרות ההיזק ניצל, או שנרפא גם מנזק זה). ואכ\"מ."]]],[1301410213,"האיסור מצומצם באופנו ופרטיו בהתאם לפרטי המאורע דנגיעת כף ירך יעקב, כנ\"ל (אף שאין בפרטים אלה חשיבות, לכאורה, בכללות המאורע וההצלה<sup data-n=\"1237\">14</sup>) — ואין זה \"זכר\" מתאים ל(כללות) ההצלה כו'.\nויש להוסיף בזה: מכיון שהתורה מ­דייקת לכתוב טעם האיסור [ועד כ\"כ, שלפי דעת חכמים, מקרא זה (\"על כן לא יאכלו גו'\") \"בסיני<sup data-n=\"1238\">15</sup> נאמר אלא שנכתב במקומו לידע מאיזה טעם נאסר להם\", כלומר, כ\"כ חשוב לדעת \"מאיזה טעם נאסר\" עד שנכתב מקרא זה תיכף, לא ב­מקום אמירתו] — מסתבר לומר, שגם שני קצוות אלה שבאיסור גיד הנשה (זכר למאורע כללי ביותר; ו\"צמצומו\" לפרט שבפרט שבמאורע זה) אינם גזירת ה­כתוב שלא נתגלה טעמה<sup data-n=\"1239\">16</sup>, אלא שיש בהם \"טעם\" (שכלי).\nב. ויובן זה בהקדם הסברת אחת ה­מעלות שבהשגחתו יתברך על בני ישר­אל [שזהו תוכנה של מצות גיד הנשה, כנ\"ל — להזכיר ע\"ד שמירת והשגחת הקב\"ה על עמו ישראל שלא יאבד ח\"ו בגלות העמים] לגבי ההשגחה על שאר הברואים — ובהקדמה:\nידוע פירוש וחידוש מורנו הבעש\"ט<sup data-n=\"1240\">17</sup> בענין השגחת הקב\"ה על עולמו, שיש השגחה פרטית לא רק על מין המדבר, אלא על כל הברואים — גם חי צומח ו­דומם. דכמה מחכמי ישראל עד הבעש\"ט ס\"ל אשר השגח\"פ היא רק על כל אחד ואחד ממין המדבר ואילו בחי צומח ודומם יש רק השגחה כללית על המין<sup data-n=\"1241\">18</sup>; והבעש\"ט פירש וחידש דגם פרטי (ה­מאורעות של) דומם צומח וחי הם ע\"פ השגחתו יתברך.\n[וכמדובר כמ\"פ, אשר כל הענינים ה­מבוארים בתורת החסידות מקורם בנגלה דתורה (אם באופן מפורש או עכ\"פ ב­דרך רמז) — וכן בענין זה, שיש ראי' מפורשת מנגלה דתורה שהשגח\"פ היא גם בדצ\"ח (שהביאה אדמו\"ר הזקן<sup data-n=\"1242\">19</sup> — בעל השמחה והגאולה די\"ט כסלו) — מדברי חז\"ל במס' חולין<sup data-n=\"1243\">20</sup>: \"ר' יוחנן כי הוה חזי שלך (עוף \"השולה דגים מן הים\") אמר משפטיך<sup data-n=\"1244\">21</sup> תהום רבה\", וכ­פרש\"י<sup data-n=\"1245\">22</sup> \"שזמנתה שלך לשפוט ולעשות נקמתך בדגת הים להמית המזומנים למות\" — הרי מפורש להדיא, שיש דין ומשפט גם על פרטי דגי הים, ועד ש­הקב\"ה מזמין עוף פרטי כדי להמית דג פרטי זה המזומן למות].",[["1237","14","ולהעיר משאלה עד\"ז בנוגע לחנוכה (המ­משמש ובא), שהיו\"ט נקבע על נס הפך (שבת כא, ב וברש\"י שם) — דלכאורה, \"עיקר הנס הי' בנצחון המלחמה רבים ביד מעטים כו' איך עשו מן הטפל עיקר\" (שערי אורה לאדמו\"ר האמצעי כב, א. ועוד). וראה פר\"ח או\"ח סתר\"ע."],["1238","15","חולין קא, ב. וראה בארוכה תו\"ש פרשתנו עה\"פ אות קס. וש\"נ."],["1239","16","אף שאין לנו ידיעה בטעמי כל פרטי המצות (ראה מו\"נ ח\"ג פכ\"ו. תניא אגה\"ק סי\"ט (קכח, א))."],["1240","17","ראה כתר שם טוב בהוספות (הוצאת קה\"ת) סקי\"ט ואילך. וש\"נ. וראה גם רשימה \"השגחה פרטית\" (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081288\" data-slug=\"likkutei-sichot\" data-id=\"1300081288\">לקו\"ש ח\"ח ע' 277</a> ואילך. וש\"נ)."],["1241","18","אבל ראה לקמן סוף הערה הבאה. וראה רשימה הנ\"ל (ע' 278 ואילך). וש\"נ."],["1242","19","הובא באוה\"ת להצ\"צ על תהלים (יהל אור) ע' קלב. וראה גם סה\"מ תרפ\"ו ע' קנו­ז.\nולהעיר מדרך חיים לאדמו\"ר האמצעי (יג, א­ב) שגם לפמ\"ש הרמב\"ם במו\"נ (ח\"ג פי\"ז­יח) יש השגח\"פ בדצ\"ח. ואכ\"מ."],["1243","20","סג, א."],["1244","21","ל' הכתוב — תהלים לו, ז."],["1245","22","חולין שם ד\"ה ומשפטיך."]]],[1301410214,"וגדר השגחה פרטית זו ביאר ה­בעש\"ט<sup data-n=\"1246\">23</sup> — \"דלא זו בלבד דכל פרטי תנועות הנבראים למיניהם הם בהשגחה פרטית מהבורא ית'\", אלא \"עוד זאת דתנועה פרטית דנברא פרטי הרי יש לו יחס כללי לכללות כוונת הבריאה. . דגם תנועה אחת של דשא פרטי משלים הכוונה העליונה בענין הבריאה\".\n[וכמדובר כמ\"פ דוגמא פשוטה לזה בחיי האדם: דרכה של אשת חיל<sup data-n=\"1247\">24</sup>, ע­קרת­בית מוצלחת היא, שנוסף על ש­היא מפקחת היטב על כל פרטי הדברים הנמצאים בביתה, שכל דבר נמצא במקו­מו הראוי לו והכל מתנהג בסדר מדויק — הנה עוד זאת, שכל פרטי חפצי ביתה יש להם חלק במטרה הכללית של הנ­הגת הבית, עד שהכל הוא בחשבון ו­בדיוק באופן דלא חסר ולא יתר — לא חסר משהו להנהגת הבית ואין דבר מיותר (שאינו משמש למטרה זו).\nואם כן הדבר בחיי עקרת­בית פשו­טה — עאכו\"כ להבדיל הבדלות עד אין קץ אצל בורא העולם ומנהיגו, שנוסף שכל פרטי המאורעות של כל הנבראים שבעולמו של הקב\"ה הם ע\"פ השגחתו ית', הנה כל אחד מהם נוגע להשלמת הכוונה העליונה בענין הבריאה].\nג. מובן, שגם לפי שיטת הבעש\"ט (שיש השגחה פרטית על כל הברואים) יש הבדל יסודי בין ההשגחה פרטית ש­על כל הברואים והשגחתו ית' שעל בני ישראל.\nוכמו שמביא כ\"ק מו\"ח אדמו\"ר בשם הבעש\"ט<sup data-n=\"1248\">25</sup>, דאף שהשגח\"פ היא על כל הברואים וגם על פרט קטן ביותר — מ\"מ, ענין ההשגח\"פ על עם קרובו ית' אי אפשר לצייר ואי אפשר להבין (\"דאָס קען מען גאָרניט אויסמאָלן. . דאָס וואָס עס איז נוגע אַ אידן הוא בהשגחה פרטית וואָס מען קען דאָס ניט פאַר­שטיין\").\nומפשטות הלשון מובן, שעילוי זה הוא גם בנוגע לפרטיותה של ההשגחה. כלומר, באיזו מדה כל פרט ופרט מוש­גח ממנו ית' ומשלים הכוונה העליונה.\nדהנה ידוע<sup data-n=\"1249\">26</sup> שיש כמה מדריגות ואו­פנים בהשגחה — מהם, בלשון הכתוב<sup data-n=\"1250\">27</sup> \"עין ה' אל יראיו\", \"עיני ה' אל צדיקים\" (בעין א' או בב' עינים<sup data-n=\"1251\">28</sup>) — שהחילוק בי­ניהם<sup data-n=\"1252\">29</sup> י\"ל (לכאורה) הוא לא ב\"פרטיות\" ההשגחה אלא רק באופנה, ולדוגמא: אם ההשגחה מלובשת ומוסתרת בדרכי ה­טבע, או שהיא השגחה גלוי' לעין כל (ועד שהיא מביאה להנהגה נסית כו').\nאבל מפשטות המשך לשון כ\"ק מו\"ח אדמו\"ר (בשם הבעש\"ט) הנ\"ל משמע, ש­העילוי בהשגחה על עם קרובו ית' הוא לא רק באופנה אלא גם בפרטיותה. דעם היות שהשגח\"פ היא על כל הברואים, ועד שכל פרט ופרט נוגע להשלמת ה­כוונה הכללית בענין הבריאה — מ\"מ, יש",[["1246","23","כתר שם טוב שם סקי\"ט. וש\"נ."],["1247","24","ראה משלי לא ובמפרשים."],["1248","25","נעתק בכתר שם טוב שם סק\"כ."],["1249","26","ראה בזה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת ראה</a> סד\"ה כי תשמע (כג, ד ואילך. כד, ג). אוה\"ת וירא ד\"ה אשר יאמר (קג, א ואילך). ועוד. — וראה שומר אמונים (להר\"י אירגס) בסופו."],["1250","27","תהלים לג, יח. שם לד, טז."],["1251","28","ראה לקו\"ת שם (וכן באוה\"ת (יהל אור) על תהלים שם (ע' קכב) ובהנסמן שם. ועוד) שבהשגחה ב\"עין א'\" יש ב' אופנים — שלמטה מהשגחה בב' עינים או למעלה ממנה. ע\"ש."],["1252","29","לפי שיטת הבעש\"ט שבכל הברואים יש השגחה פרטית (משא\"כ לשיטת אחדים מחכמי ישראל שקדמוהו) — ראה רשימה הנ\"ל שם."]]],[1301410215,"עילוי נפלא בההשגחה על כל פרט ו­פרט של עם קרובו (ועילוי כזה שהוא למעלה מן השכל).\nד. ויש לומר הביאור בזה:\nאף שכל הברואים \"לא נמצאו אלא מאמתת המצאו\"<sup data-n=\"1253\">30</sup> ומושגחים מאתו ית' — מ\"מ, (עיקר) רצונו ובחירתו של הקב\"ה הוא רק בישראל, ש\"בחר בנו מכל ה­עמים\"<sup data-n=\"1254\">31</sup>, ונאמר<sup data-n=\"1255\">32</sup> \"אהבתי אתכם אמר ה' גו' אח עשו ליעקב גו' ואוהב את יעקב\".\nוי\"ל שזהו גם תוכן מאמר רז\"ל<sup data-n=\"1256\">33</sup> שה­עולם נברא \"בשביל התורה. . ובשביל ישראל\": ישראל ותורה הם כוונת ה­בריאה (וכמחז\"ל<sup data-n=\"1257\">34</sup> \"אני (לא<sup data-n=\"1258\">*34</sup>) נבראתי (אלא<sup data-n=\"1258\">*34</sup>) לשמש את קוני\"), רצונו ובחי­רתו של הקב\"ה הוא בהם עצמם;\nמשא\"כ שאר הנבראים אינם תכלית ומטרה בפני עצמם אלא רק \"אמצעי\" שעל ידם נשלמה כוונת הקב\"ה בתורה וישראל, וכמאמר חז\"ל<sup data-n=\"1257\">34</sup> ש\"לא נבראו אלא לשמשני\", שאין רצונו ית' בהם מצד עצמם והם רק \"משמשים\" (\"אמצעי\") לתורה וישראל.\nוהנה תכונת ענין הרצון (והבחירה) היא<sup data-n=\"1261\">35</sup>, דכאשר רוצים (ובוחרים) באיזה דבר אפשר שהרצון בכל חלקי ופרטי הדבר יהי' בשווה (באותו התוקף), למ­רות החילוקים בחשיבותם ומעלתם של הפרטים (מצד תוכנם הם) [ועד שכאשר יחסר פרט אחד מהדבר (גם פרט קטן וטפל לכאורה) יחסר בהכלל כולו, מ­אחר שרצונו לא נשלם].\nוכמו שמצינו בענין המצות, שהם רצון העליון ב\"ה (גזירות המלך<sup data-n=\"1262\">36</sup>), דאף שמצינו חילוקים מן הקצה אל הקצה במצות התורה, בלשון חז\"ל<sup data-n=\"1263\">37</sup> שיש \"קלה שבקלות\" ויש עד ל\"חמורה שבחמורות\" — מ\"מ אמרו<sup data-n=\"1263\">37</sup> \"לא תהא יושב ושוקל מצוותי' של תורה\" אלא צ\"ל אותה ה­זהירות בכל המצוות בשווה; כי למרות החילוקים שבין המצות בתוכנם (בלשון החינוך \"שרשי המצוה\") וכיו\"ב — כולן הן רצונו ית', \"אשר קדשנו במצותיו ו­צונו\"<sup data-n=\"1265\">38</sup>, וזה הוא בשווה ממש בכל ה­מצות. דכמו שהקב\"ה רוצה את החמורות כך רוצה את הקלות, באותו רצון<sup data-n=\"1266\">39</sup>.\n[וי\"ל אשר מצד ענין זה שבמצוות, מצינו לפעמים, שכשחסר פרט אחד — חסר הכלל כולו. וכמו: גר שקיבל עליו כל התורה כולה חוץ מדבר אחד (אפילו מדברי סופרים) אין מקבלין אותו<sup data-n=\"1267\">40</sup>; וכן \"האומר שאין התורה מעם ה' אפילו פסוק אחד אפילו תיבה אחת. . ה\"ז",[["1253","30","ל' הרמב\"ם ריש הל' יסודי התורה. וזה צ\"ל תמיד — כההמשך שם. וראה הדרן על הרמב\"ם (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271267\" data-slug=\"likkutei-sichot\" data-id=\"1300271267\">לקו\"ש חכ\"ז ע' 253</a>)."],["1254","31","נוסח ברכת התורה."],["1255","32","מלאכי א, ב — ושייך לענין הבחירה (ראה תו\"א ו, ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560197\" data-slug=\"or-hatorah-hb\" data-id=\"8316560197\">אוה\"ת בראשית (כרך ג) תקסה, א</a>. ועוד)."],["1256","33","רש\"י בראשית א, א."],["1257","34","משנה (וברייתא) סוף קידושין."],["1258","*34","גירסא שהובאה במלאכת שלמה ועוד. ועד\"ז ביל\"ש ירמי' רמז רעו. ולהעיר מתוד\"ה מתני' מנחות (פג, סע\"ב) ד\"לא. . אלא\" מדגיש לעיכובא כו'."],["1258","*34","גירסא שהובאה במלאכת שלמה ועוד. ועד\"ז ביל\"ש ירמי' רמז רעו. ולהעיר מתוד\"ה מתני' מנחות (פג, סע\"ב) ד\"לא. . אלא\" מדגיש לעיכובא כו'."],["1257","34","משנה (וברייתא) סוף קידושין."],["1261","35","ראה ד\"ה ואני תפלתי תרצ\"ד וד\"ה אגורה תרצ\"ה (בסה\"מ קונטרסים ח\"ב). ובכ\"מ."],["1262","36","ראה מכילתא יתרו כ, ג. ועוד."],["1263","37","תנחומא עקב ב. ובכ\"מ. וראה אבות רפ\"ב."],["1263","37","תנחומא עקב ב. ובכ\"מ. וראה אבות רפ\"ב."],["1265","38","נוסח ברכת כל המצות."],["1266","39","ולהעיר מדין מורד במלך, שהוא אפילו כשגזר על אחד שילך למקום פלוני (רמב\"ם הל' מלכים פ\"ג ה\"ח) — מכיון שעשה נגד רצון (וגזירת) המלך. וראה חגיגה (ה, ב) מאן דמחוי לי' במחוג קמי מלכא כו'."],["1267","40","בכורות ל, ב. רמב\"ם הל' איסורי ביאה פי\"ד ה\"ח."]]],[1301410216,"כופר בתורה\"<sup data-n=\"1268\">41</sup>, \"ואין<sup data-n=\"1269\">42</sup> (בזה) הפרש בין ובני חם כוש ומצרים<sup data-n=\"1270\">43</sup> ושם אשתו מהי­טבאל<sup data-n=\"1271\">44</sup>. . ובין אנכי ה' אלקיך<sup data-n=\"1272\">45</sup> כו'\"].\nה. ועפ\"ז מובן העילוי בהשגחה פר­טית על ישראל עם קרובו של הקב\"ה לגבי ההשגחה פרטית על שאר עניני הבריאה:\nבשאר הברואים, אף שכל פרט ופרט נוגע להשלמת הכוונה הכללית (כנ\"ל), מ\"מ, מכיון שחשיבות הפרטים תלוי' במעלתם\n[כמו גוף האדם, דאף ששלימותו היא כאשר יש בו כל האברים (וגם שערות וצפרנים), מ\"מ אי אפשר לדמות כלל חשיבות האברים שהנשמה תלוי' בהם ל­גבי שאר חלקי הגוף (ומכל שכן ל­שערות וצפרנים שהם פרטים טפלים ביותר)]\nלכן, גם ההשגחה שעל כל פרט ופרט היא ב\"כל אחד לפי מעלתו\"<sup data-n=\"1273\">46</sup> (עד כמה הוא \"משמש\" את התורה ואת ישראל).\nמשא\"כ בישראל עם קרובו, מכיון שהשגחתו ית' עליהם היא תוצאה מרצונו ובחירתו בהם, הרי נוסף לזה שיש הש­גחה על כל פרט ופרט (ובאופן שכל פרט משלים הכוונה הכללית בענין ה­בריאה) — הנה אופן ההשגחה על ה­פרטים הוא לא רק כפי חשיבותו הפרטית של כל פרט ופרט (שבזה יש חילוקים לפי חשיבותו של הפרט), אלא ההשגחה היא באופן שווה בכולם. כי מצד רצונו ובחירתו ית' בישראל, הרי כל פרט ופרט שבהם \"נוגע\" באופן שווה<sup data-n=\"1274\">47</sup>.\nו. ע\"פ כל זה יש לבאר הטעם מה שה\"זכר\" להצלת יעקב נקבע דוקא ב­פרט אחד של המאורע, ובזה גופא — מדייקים בפרט שבפרט (אם רק גיד ש­בירך ימין או גם של שמאל וכו') — כי עי\"ז בא לידי ביטוי גדר ואופן השגחתו ית' על יעקב אבינו (ובמילא — גם על עם ישראל, בני יעקב):",[["1268","41","רמב\"ם הל' תשובה פ\"ג ה\"ח. פיהמ\"ש שבהערה הבאה."],["1269","42","פיהמ\"ש להרמב\"ם סנהדרין ר\"פ חלק היסוד הח'."],["1270","43","נח י, ו."],["1271","44","פרשתנו לו, לט."],["1272","45","יתרו כ, ב. ואתחנן ה, ו."],["1273","46","ל' כ\"ק מו\"ח אדמו\"ר בד\"ה הטה תרצ\"ד (סה\"מ קונטרסים ח\"ב רעט, א). ולהעיר מלשון כ\"ק מו\"ח אדמו\"ר בשם הבעש\"ט (כש\"ט שם סק\"כ) \"יעדער באַשעפעניש פאַרנעמט גאָר אַ באַזונדער אָרט לויט זיין מהות\"."],["1274","47","ויש לומר, שמצד זה יש עילוי בהשגחה פרטית על ישראל בענין חשיבות הפרטים ביחס להשלמת הכוונה הכללית בענין הבריאה<sup data-n=\"e34\">*</sup>:\nמכיון שישראל הם הם כוונת ותכלית הבריאה, הרי ההשגחה עליהם היא באופן כזה שנרגש בה­השגחה איך שכל פרט ופרט בהם משלים את ה­כוונה הכללית בענין הבריאה; ולכן אין בהשגחה זו הבדל בין פרט לפרט, כי בהענין ד\"השלמת הכלל\" כולם<sup data-n=\"e35\">**</sup> משלימים הכלל.\n[משא\"כ בשאר הברואים שאין הכוונה בהם עצמם והם רק \"משמשים\" (\"אמצעי\") לתורה ו­ישראל — לכן ההשגחה על כל פרט ופרט היא בכל אחד לפי מעלתו, עד כמה הוא \"משמש\" את התורה ואת ישראל (אף שכל הפרטים משלימים הכוונה הכללית בענין הבריאה)]."],["e34","*","להעיר מלשון כ\"ק מו\"ח אדמו\"ר באגרות קודש שלו ח\"ט ע' ערב. ולהעיר ג\"כ ממשנ\"ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231164\" data-slug=\"likkutei-sichot\" data-id=\"1300231164\">לקו\"ש חכ\"ג ע' 164</a> ואילך."],["e35","**","וכמו אברי הגוף ששלימות הגוף היא דוקא כאשר יש בו כל האברים, גם האברים התחתונים (ראה ספר הערכים חב\"ד ערך אברים בתחלתו, וש\"נ).\n‑"]]],[1301410217,"השגחתו ית' היא באופן כזה, שלא זו בלבד שכל פרט ופרט מושגח מאתו יתברך (ויתירה מזו — שכל פרט ופרט נוגע להשלמת הכוונה הכללית) — אלא עוד זאת, שבענין השלמת רצונו יתברך הפרטים החשובים ביותר או הפרטים הנראים כטפלים ומעוטי הערך, כולם מושגחים מאתו יתברך באופן שווה.\nוענין זה מודגש במצות גיד הנשה, ש­הזכר על כללות המאורע דהצלת יעקב נקבע דוקא על פרט שבפרט דהמאורע — ללמדנו, שגם פרט טפל כו' הי' נוגע לכללות ההצלה.\nז. אמנם עדיין אין הענין מחוור כל צרכו, כי הן אמת שע\"י קביעת הזכרון בפרט שבפרט של מאורע זה נרמז ה­עילוי שבהשגחתו ית' על בנ\"י, באופן ההשגחה על כל פרט ופרט כנ\"ל — אבל מ\"מ, סו\"ס הי' ראוי יותר, לכאורה, לקבוע הזכר בענין כללי. כלומר: ע\"י קביעת הזכרון באופן כזה חסר לכאורה הזכר לכללות ההצלה — כי סו\"ס הרי גיד הנשה הוא רק פרט של המאורע<sup data-n=\"1275\">48</sup>?\nוי\"ל הביאור בזה בהקדם עוד ענין ביחס בנ\"י להקב\"ה<sup data-n=\"1276\">49</sup>: בבנ\"י נאמר<sup data-n=\"1277\">50</sup> \"כי חלק ה' עמו\", שהם כמו \"חלק מן ה­עצם\"<sup data-n=\"1278\">51</sup>, וע\"ד הבן שהוא חלק מעצמות אביו. כלומר: נוסף לזה שהקב\"ה בחר בעמו ישראל ואוהב אותם (שבזה עדיין נרגש שיש כאן שנים, בוחר ונבחר, אוהב ואהוב), אלא שהם עצם אחד כביכול.\n[וכמשל הידוע מהה\"מ<sup data-n=\"1279\">52</sup>, \"דאף קודם שנבראו ישראל הי' נחקק צורתם במח­שבה כמ\"ש רז\"ל<sup data-n=\"1280\">53</sup> ישראל עלה במח­שבה\" — כלומר, גם \"קודם שנבראו ישר­אל\" להיות מציאות בפ\"ע, \"נחקק צורתם במחשבה\", וי\"ל דזהו הדיוק נחקק — דחקיקה היא מני' ובי', כי ישראל וקב\"ה כולא חד].\nוהנה ידוע המאמר<sup data-n=\"1281\">54</sup> \"כשאתה תופס במקצת מן העצם אתה תופס בכולו\", כי ה\"עצם\" נמצא בכל עצמותו בכל חל­קיו<sup data-n=\"1282\">55</sup>.\nוע\"ד שמצינו דוגמא לזה בענין ה­מצוות — \"העוסק במצוה פטור מן ה­מצוה\"<sup data-n=\"1283\">56</sup>, שהפירוש בזה הוא, דהוי \"כמו שמקיים גם זה\"<sup data-n=\"1284\">57</sup> (המצוה השני'), כי כל מצוה כלולה משאר כל המצות. ומבואר בזה<sup data-n=\"1285\">58</sup>, כי רצון העליון בתרי\"ג מצות",[["1275","48","ואף את\"ל שיש מקום לקביעת זכר על פרט דגיד הנשה להשמיענו ענין האמור בגדר השגח\"פ על ישראל — מ\"מ הי' ראוי לקבוע זכרון גם בענין כללי (בנוסף לגיד הנשה)."],["1276","49","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281177\" data-slug=\"likkutei-sichot\" data-id=\"1300281177\">לקו\"ש חכ\"ח ע' 177</a> ואילך (בביאור ג' הלשונות \"חלקנו. . גורלנו. . ירו­שתנו\")."],["1277","50","האזינו לב, ט."],["1278","51","ראה בארוכה ד\"ה זאת תורת הבית תרפ\"ט (בסה\"מ קונטרסים ח\"א) פ\"ד ואילך."],["1279","52","אור תורה ב, סע\"ג. וראה שם בתחלת ה­ספר (וכן בספרו לקוטי אמרים בתחלתו)."],["1280","53","ב\"ר פ\"א, ד."],["1281","54","מאמר הבעש\"ט — כתר שם טוב בהוספות סקט\"ז (וש\"נ). המשך תער\"ב ח\"א ס\"פ ערב."],["1282","55","וכמו חיות הנפש שבאדם, שהנפש \"כולה עצם אחד רוחני פשוט\" (ל' התניא פנ\"א — עא, ריש ע\"ב) — שבחיות הכללי, המחי' את כל הגוף כאחד, הרי כש\"תופסים במקצתו\" (כפי שמתפשט באבר אחד) תופסים בכולו, דבכל חלק וחלק הוא אותו ה\"עצם\" והחיות הזה."],["1283","56","סוכה כה, א."],["1284","57","צפע\"נ כללי התורה והמצוה בערכו. וראה ע\"ד החסידות המשך תרס\"ו (ע' סח. ע' תקכב). ד\"ה לםרבה המשרה ה'ש\"ת (בסה\"מ קונטרסים ח\"ב) פ\"ג. ועוד."],["1285","58","המשך תרס\"ו ע' תקכב. המשך תער\"ב ח\"ב ע' א'פא. ע\"ש."]]],[1301410218,"הוא רצון עצמי, ולכן ע\"י התפיסא ב­\"מקצת\" רצון זה (קיום מצוה אחת) תופ­סים בכולו, והוי כמו שמקיים גם המצוה האחרת<sup data-n=\"1286\">59</sup>.\nועד\"ז מצינו בבני ישראל — דגם \"נפש אחת מישראל\" ה\"ה \"עולם מלא\"<sup data-n=\"1287\">60</sup>, ועד כ\"כ ש(בדיני פקו\"נ) מצינו לפעמים שיש ל\"נפש אחת מישראל\" אותה החשי­בות של רבים וכלל. ועד כ\"כ דעכו\"ם שאמרו לקבוצה של בנ\"י \"תנו לנו אחד מכם ונהרגנו ואם לאו נהרוג כולכם יהרגו כולם ואל ימסרו להם נפש אחת מישראל\"<sup data-n=\"1288\">61</sup> — שאחד הביאורים בזה הוא, כי בכל \"חלק\" של כלל ישראל \"תופסים בכולו\", היינו, שב\"עצמיות\" שבכל איש ישראל נתפס העצם של הכלל כולו.\nח. ובזה יובן בעומק יותר העילוי ש­בההשגחה פרטית על ישראל עם קרובו:\nבענינים אלה שבהם באה לידי ביטוי וגילוי אחדות זו שבין ישראל והקב\"ה (שהם \"חלק מן העצם\") — הרי ההשגחה בהם היא באופן (שלא זו בלבד שהקב\"ה משגיח על כל פרט ופרט שלהם, ובאופן שבכמה ענינים כל פרט ופרט נוגע ב­שווה להשלמת הכוונה הכללית, אלא עוד זאת) שבכל פרט ופרט של השגחה זו על עמו ישראל \"תופסים בכולו\", כל הקשר העצמי שביניהם.\nוכן הי' במאורע זה של הצלת יעקב מיד מלאכו של עשו, שהי' ענין כללי ב­יותר בחיי יעקב, עד שנגע עד לעצ­מיותו.\nומטעם זה נקבע הזכר על הצלת יעקב (לא בענין כללי, כ\"א) דוקא על פרט שבפרט (כנ\"ל) — להורות על ענין הכי עמוק שבהשגחת ושמירת הקב\"ה על ישראל, שהשגחה זו [כפי שבאה לידי ביטוי ביעקב, שהוא העצם דכלל ישר­אל<sup data-n=\"1289\">62</sup>, ונשמתו היתה \"כלולה מכל ה­נשמות שבישראל מעולם ועד עולם\"<sup data-n=\"1290\">63</sup>] — היא באופן, שבכל פרט ופרט, עד ל­פרט קטן וטפל ביותר, תופסים \"בכולו\".\n<span data-k=\"q\">(משיחות ערב חג השבועות תשמ\"ו; שמח\"ת תשח\"י) </span>",[["1286","59","היינו, שרצון העליון בכל מצוה ומצוה פר­טית אינו רק פרט מן הכלל, אלא הוא גם חלק מן העצם — הרצון העצמי בתרי\"ג מצות (שלמעלה מ­התחלקות), ולכן, ע\"י קיום מצוה אחת \"תופסים\" לא רק הרצון שבמצוה פרטית זו, אלא \"כל\" הרצון (ובמילא גם הרצון שבמצוה השני' שפטור ממנה) — כן מובן מהמבואר בהמשך תרס\"ו ומפורש בהמשך תער\"ב שם."],["1287","60","משנה סנהדרין לז, א."],["1288","61","רמב\"ם הל' יסודי התורה פ\"ה ה\"ה (וראה שם דכ\"ה אפילו ב\"יחדוהו להם\" — מלבד \"אם הי' מחוייב מיתה כו'\")."],["1289","62","ראה צפע\"נ עה\"ת (המלוקט) ר\"פ וישב (ושם, שזהו כשנאמר \"ישראל\". ולהעיר שבמאורע זה נאמר \"לא יעקב יאמר עוד שמך כי אם ישראל\" (פרשתנו לב, כט))."],["1290","63","תניא אגה\"ק ס\"ז (קיא, סע\"ב)."]]],[1301410219,"<h3>שיחה ב</h3>\nא. כתב הרמב\"ם<sup data-n=\"1291\">1</sup> \"טומאת ע\"ז מדברי סופרים ויש לה רמז בתורה הסירו<sup data-n=\"1292\">2</sup> את אלקי הנכר אשר בתוככם והטהרו והח­ליפו שמלותיכם, וארבע אבות הטומאה יש בה כו' וטומאת כולן מדבריהן\".\nויש לעיין, מה ראה הרמב\"ם להביא \"רמז בתורה\" על גזירה זו (\"מדבריהן\") של טומאת ע\"ז, שלא כדרכו (ברוב ה­מקומות ככולן) שאינו מביא רמז ואס­מכתא על גזירות דרבנן (אף כשיש רמז מפורש בחז\"ל)<sup data-n=\"1293\">3</sup>.\nוביותר תמוה: רמז זה מן התורה ל­טומאת ע\"ז מן הכתוב \"הסירו גו' והטהרו גו'\", לא נמצא לפנינו במשנה וגמ', וגם לא במדרשי חז\"ל (הקדומים<sup data-n=\"1294\">4</sup>) שהגיעו לידינו; ולאידך, מפורש במשנה<sup data-n=\"1295\">5</sup> \"מנין לע\"ז שמטמאה. . כנדה שנאמר<sup data-n=\"1296\">6</sup> תזרם כמו דוה\", וכן למדו<sup data-n=\"1297\">7</sup> מן הכתוב<sup data-n=\"1298\">8</sup> \"שקץ תשקצנו גו'\" שמטמאה כשרץ, וכן אית­קש למת<sup data-n=\"1299\">9</sup> כמו שנאמר<sup data-n=\"1300\">10</sup> \"וישלך את עפרה על קבר בני העם\" (וכפי שמסיק בגמ'<sup data-n=\"1301\">11</sup> למאי הלכתא איתקש ע\"ז לשרץ, לנדה ולמת) — שלימודים אלה הם אס­מכתא בעלמא<sup data-n=\"1302\">12</sup>, כמפורש במסקנת ה­גמ'<sup data-n=\"1303\">13</sup> ד\"טומאת ע\"ז דרבנן היא\" —\nוא\"כ, מדוע הביא הרמב\"ם \"רמז בתו­רה\" ממדרש בלתי מצוי, ולא מהלימודים המפורשים במשנה וגמ'?\nועוד זאת: בהלכה הבאה אכן מביא הרמב\"ם<sup data-n=\"1304\">14</sup> הלימוד מ\"שקץ תשקצנו\" ש­ע\"ז מטמאה כשרץ, ובהלכה שלאחרי' — הלימוד מ\"תזרם כמו דוה\" שמטמאה כ­נדה; ועפ\"ז ייפלא ביותר, ל\"ל להרמב\"ם להקדים \"רמז בתורה\" מן הכתוב \"הסירו גו'\" ולא הסתפק בהלימודים המפורשים בש\"ס שהביאם בהלכות הבאות<sup data-n=\"1305\">15</sup>?\nב. ויש לומר הביאור בזה: גדרה של טומאת ע\"ז יש לבארו בשני אופנים:",[["1291","1","הל' שאר אבות הטומאה רפ\"ו. ועד\"ז כתב הרמב\"ם בפיהמ\"ש בהקדמתו לסדר טהרות."],["1292","2","פרשתנו לה, ב."],["1293","3","ראה לדוגמא הל' ברכות פ\"א ה\"ב לענין ברכה ראשונה (ראה ברכות לה, א ובתוד\"ה אלא שם). שם פ\"ו ה\"א­ב לענין חיוב נטילת ידים (ראה חולין קו, א ובכס\"מ לרמב\"ם שם). ועוד."],["1294","4","ורק במדרש לקח טוב (ושכל טוב) פרשתנו עה\"פ מצינו דרשה כזו. וכן במדרש הגדול. ולהעיר גם מפרש\"י עה\"פ \"והטהרו — מע\"ז\" ובנחלת יעקב ומשכיל לדוד על פרש\"י שם (ובבאר בשדה על פרש\"י פי' שגם כוונת הרא\"ם היא לטומאת ע\"ז). וראה גם רמב\"ן, רד\"ק ועוד שם."],["1295","5","שבת רפ\"ט (פב, סע\"א). ועד\"ז במשנה ע\"ז מז, ריש ע\"ב."],["1296","6","ישעי' ל, כב."],["1297","7","משנה ע\"ז שם. הובא בגמ' שבת שם ע\"ב."],["1298","8","עקב ז, כו."],["1299","9","שבת פג, ב."],["1300","10","מ\"ב כג, ו."],["1301","11","שבת שם. והובא גם ברמב\"ם כאן (הלכה ג)."],["1302","12","כלשון רש\"י שם ד\"ה דרבנן."],["1303","13","שם. וכ\"ה לשון הרמב\"ם כאן בסוף ההלכה \"וטומאת כולן מדבריהן\"."],["1304","14","וכן בפיהמ\"ש (שבהערה 1), מביא הלימוד מ\"שקץ תשקצנו\"."],["1305","15","שמזה מובן שאין לתרץ שהרמב\"ם מביא רמז זה לפי שהוא דרשה פשוטה יותר (ראה יד מלאכי כללי הרמב\"ם אות ד') — דכיון שמביא ב­לאה\"כ הדרשות שבש\"ס, אין צורך להוסיף עוד דרשה (אף שהיא פשוטה יותר)."]]]]});
